((window.CARDS_BY_LANG = window.CARDS_BY_LANG || {}).el = window.CARDS_BY_LANG.el || {}).character = [{"name":"Χάρι Πότερ","emoji":"⚡","meta":["«Χάρι Πότερ»","νεαρός μάγος","1997"],"description":"Ορφανό αγόρι που στα έντεκα του μαθαίνει ότι είναι μάγος και ξεκινά τις σπουδές του στη σχολή Χόγκουαρτς. Όλη του τη ζωή τον καταδιώκει ο σκοτεινός μάγος Βόλντεμορτ, που σκότωσε τους γονείς του και του άφησε στο μέτωπο μια ουλή σε σχήμα κεραυνού.","fact":"Στις ταινίες τον Χάρι υποδύθηκε ο Ντάνιελ Ράντκλιφ, που ήταν έντεκα ετών όταν ξεκίνησαν τα γυρίσματα της πρώτης.","wiki_en":"Harry Potter (character)"},{"name":"Ερμιόνη Γκρέιντζερ","emoji":"📚","meta":["«Χάρι Πότερ»","αριστούχος μάγισσα","1997"],"description":"Μία από τις πιο ικανές μαθήτριες του Χόγκουαρτς, κι όμως γεννημένη σε οικογένεια κοινών ανθρώπων, των Μαγκλ. Έχει κοφτερό μυαλό, πάθος για τα βιβλία και απόλυτη αφοσίωση στους φίλους της, και οι γνώσεις της σώζουν ξανά και ξανά τον Χάρι Πότερ και τον Ρον Ουέσλι.","fact":"Στις ταινίες την Ερμιόνη υποδύθηκε η Έμα Γουότσον, που πέρασε την οντισιόν όσο ήταν ακόμη μαθήτρια.","wiki_en":"Hermione Granger"},{"name":"Σέβερους Σνέιπ","emoji":"🧪","meta":["«Χάρι Πότερ»","καθηγητής των Φίλτρων","1997"],"description":"Σκυθρωπός και δηκτικός καθηγητής των Φίλτρων στο Χόγκουαρτς, του οποίου τα πραγματικά αισθήματα για τον Χάρι Πότερ παραμένουν για χρόνια αίνιγμα. Πίσω από την ψυχρότητα κρύβεται μια δύσκολη ζωή, δεμένη στενά με το παρελθόν των γονιών του αγοριού.","fact":"Ο Άλαν Ρίκμαν γνώριζε το βασικό μυστικό του ήρωα πολύ πριν κυκλοφορήσουν τα τελευταία βιβλία: του το είχε πει η ίδια η Ρόουλινγκ.","wiki_en":"Severus Snape"},{"name":"Λόρδος Βόλντεμορτ","emoji":"🐍","meta":["«Χάρι Πότερ»","σκοτεινός μάγος","1997"],"description":"Ο ισχυρότερος σκοτεινός μάγος της εποχής του, με εμμονή στην αθανασία και στην εξουσία πάνω στον κόσμο της μαγείας. Οι περισσότεροι μάγοι φοβούνται να προφέρουν το όνομά του και τον αποκαλούν απλώς Σκοτεινό Άρχοντα ή Αυτόν-που-δεν-πρέπει-να-κατονομάζεται.","fact":"Ο Ρέιφ Φάινς γύρισε τον ρόλο χωρίς την άκρη της μύτης του: την αφαιρούσαν ψηφιακά.","wiki_en":"Lord Voldemort"},{"name":"Άλμπους Ντάμπλντορ","emoji":"🧙","meta":["«Χάρι Πότερ»","διευθυντής του Χόγκουαρτς","1997"],"description":"Διευθυντής της σχολής Χόγκουαρτς και ένας από τους ισχυρότερους μάγους του κόσμου, γνωστός για τη σοφία και για μια δόση εκκεντρικότητας. Στέκεται μέντορας του Χάρι Πότερ και είναι από τους λίγους που ο Βόλντεμορτ φοβάται πραγματικά.","fact":"Πρώτος Ντάμπλντορ στον κινηματογράφο ήταν ο Ρίτσαρντ Χάρις· μετά τον θάνατό του τον ρόλο ανέλαβε ο Μάικλ Γκάμπον.","wiki_en":"Albus Dumbledore"},{"name":"Φρόντο Μπάγκινς","emoji":"💍","meta":["«Ο Άρχοντας των Δαχτυλιδιών»","χόμπιτ κομιστής","1954"],"description":"Ταπεινό χόμπιτ από το Σάιρ, που καλείται να καταστρέψει το Ένα Δαχτυλίδι. Το μακρύ και επικίνδυνο ταξίδι μέσα από τη Μέση Γη ως τα πυρά του Όρους του Χαμού γίνεται η σκληρότερη δοκιμασία της ζωής του και τον αλλάζει για πάντα.","fact":"Στη μεταφορά του Πίτερ Τζάκσον τον Φρόντο υποδύθηκε ο Ελάιζα Γουντ, που έπαιζε σε ταινίες από μικρό παιδί.","wiki_en":"Frodo Baggins"},{"name":"Γκάνταλφ","emoji":"🧙‍♂️","meta":["«Ο Άρχοντας των Δαχτυλιδιών»","περιπλανώμενος μάγος","1937"],"description":"Ισχυρός περιπλανώμενος μάγος που στηρίζει τους λαούς της Μέσης Γης στον αγώνα τους κατά του σκότους. Εμφανίζεται πρώτα στο «Χόμπιτ» ως ο μυστηριώδης οδηγός του Μπίλμπο Μπάγκινς και αργότερα γίνεται πνευματικός ηγέτης της Συντροφιάς του Δαχτυλιδιού.","fact":"Κατά τον ίδιο τον Τόλκιν, η μορφή του Γκάνταλφ γεννήθηκε από μια καρτ ποστάλ με έναν γέρο οδοιπόρο στα βουνά.","wiki_en":"Gandalf"},{"name":"Γκόλουμ","emoji":"🐟","meta":["«Ο Άρχοντας των Δαχτυλιδιών»","διχασμένο πλάσμα","1937"],"description":"Πλάσμα που κάποτε έμοιαζε με χόμπιτ και παραμορφώθηκε από τη μακρόχρονη κατοχή του Ενός Δαχτυλιδιού, που το αποκαλεί «πολύτιμό μου». Μέσα του παλεύουν ταυτόχρονα ένα άθλιο, δόλιο όν και τα αδύναμα υπολείμματα της παλιάς, καλής του φύσης.","fact":"Στις ταινίες του Πίτερ Τζάκσον τον Γκόλουμ ερμήνευσε ο Άντι Σέρκις με τεχνολογία καταγραφής κίνησης.","wiki_en":"Gollum"},{"name":"Άραγκορν","emoji":"⚔️","meta":["«Ο Άρχοντας των Δαχτυλιδιών»","διάδοχος του θρόνου","1954"],"description":"Περιπλανώμενος γνωστός και ως Γοργοπόδαρος, που αποδεικνύεται νόμιμος διάδοχος του αρχαίου βασιλείου της Γκόντορ. Οδηγεί τη Συντροφιά του Δαχτυλιδιού μέσα από τους κινδύνους της Μέσης Γης και τελικά γίνεται ο βασιλιάς που ενώνει τους ανθρώπους κατά του σκότους.","fact":"Ο ρόλος του Άραγκορν δόθηκε στον Βίγκο Μόρτενσεν σχεδόν την τελευταία στιγμή, όταν τα γυρίσματα της τριλογίας είχαν ήδη αρχίσει.","wiki_en":"Aragorn"},{"name":"Λέγκολας","emoji":"🏹","meta":["«Ο Άρχοντας των Δαχτυλιδιών»","ξωτικό τοξότης","1954"],"description":"Πρίγκιπας των ξωτικών του δάσους και δεινός τοξότης, μέλος της Συντροφιάς του Δαχτυλιδιού. Η ευστοχία του, η οξεία όρασή του και η απρόσμενη φιλία του με τον νάνο Γκίμλι, παρά την παλιά έχθρα των λαών τους, είναι από τις πιο αγαπημένες στιγμές της ιστορίας.","fact":"Για τον ρόλο ο Ορλάντο Μπλουμ έμαθε τοξοβολία, ιππασία και ξιφασκία.","wiki_en":"Legolas"},{"name":"Νταρθ Βέιντερ","emoji":"🫁","meta":["«Πόλεμος των Άστρων»","σκοτεινός άρχοντας των Σιθ","1977"],"description":"Πανίσχυρος πολεμιστής της σκοτεινής πλευράς της Δύναμης, που τον αναγνωρίζεις από τη μαύρη μάσκα και τη βαριά μηχανική του ανάσα. Κάποτε ιππότης Τζεντάι, πέρασε στο στρατόπεδο της Αυτοκρατορίας και έγινε ένας από τους πιο αναγνωρίσιμους κακούς του κινηματογράφου.","fact":"Στην αρχική τριλογία τη φωνή του Νταρθ Βέιντερ έδωσε ο Τζέιμς Ερλ Τζόουνς, ενώ τη στολή φορούσε άλλος ηθοποιός.","wiki_en":"Darth Vader"},{"name":"Λουκ Σκαϊγουόκερ","emoji":"🌅","meta":["«Πόλεμος των Άστρων»","ιππότης Τζεντάι","1977"],"description":"Νέος από τον ερημικό πλανήτη Τατουίν, που ανακαλύπτει τον προορισμό του και γίνεται ένας από τους τελευταίους ιππότες Τζεντάι. Η ενηλικίωσή του και η πάλη του με την Αυτοκρατορία είναι ο κεντρικός άξονας της αρχικής τριλογίας.","fact":"Η σκηνή όπου ο Λουκ κοιτάζει τη δύση των δύο ήλιων του Τατουίν έγινε ένα από τα πιο αναγνωρίσιμα πλάνα της σάγκα.","wiki_en":"Luke Skywalker"},{"name":"Γιόντα","emoji":"🟢","meta":["«Πόλεμος των Άστρων»","δάσκαλος Τζεντάι","1980"],"description":"Ένας από τους αρχαιότερους και σοφότερους Τζεντάι του γαλαξία, που διδάσκει στους νέους μαθητές τη χρήση της Δύναμης παρά το μικροσκοπικό του ύψος. Ο ανάστροφος τρόπος που μιλά και τα λιτά αποφθέγματά του έγιναν κομμάτι της παγκόσμιας ποπ κουλτούρας.","fact":"Τη μαριονέτα του Γιόντα στις αρχικές ταινίες κινούσε και υποδυόταν ο Φρανκ Οζ, γνωστός και από τους Μάπετς.","wiki_en":"Yoda"},{"name":"Χαν Σόλο","emoji":"🚀","meta":["«Πόλεμος των Άστρων»","λαθρέμπορος πιλότος","1977"],"description":"Θρασύς πιλότος και λαθρέμπορος, κυβερνήτης του «Χιλιετούς Γερακιού», που στην αρχή κινείται μόνο από συμφέρον και σιγά σιγά γίνεται αληθινός ήρωας της εξέγερσης κατά της Αυτοκρατορίας. Το κοφτερό του χιούμορ τον έκανε από τους πιο αγαπημένους ήρωες.","fact":"Ο ρόλος του Χαν Σόλο έκανε τον Χάρισον Φορντ παγκόσμιο αστέρι πριν ακόμη παίξει τον Ιντιάνα Τζόουνς.","wiki_en":"Han Solo"},{"name":"Πριγκίπισσα Λέια","emoji":"👑","meta":["«Πόλεμος των Άστρων»","αρχηγός των επαναστατών","1977"],"description":"Πριγκίπισσα του Άλντεραν, του πλανήτη που κατέστρεψε η Αυτοκρατορία, και μία από τις ηγέτιδες της Συμμαχίας των Επαναστατών. Αποφασιστική και ατρόμητη, συνδυάζει διπλωματικό ταλέντο με τη διάθεση να πολεμήσει η ίδια για την ελευθερία του γαλαξία.","fact":"Η Κάρι Φίσερ έπαιξε τη Λέια στην αρχική τριλογία και επέστρεψε στον ρόλο σχεδόν σαράντα χρόνια μετά, στη «Δύναμη Ξυπνάει».","wiki_en":"Princess Leia"},{"name":"Τσουμπάκα","emoji":"🔫","meta":["«Πόλεμος των Άστρων»","πολεμιστής Γούκι","1977"],"description":"Πανύψηλος και απίστευτα δυνατός πολεμιστής του λαού των Γούκι, πιστός φίλος και συγκυβερνήτης του Χαν Σόλο στο «Χιλιετές Γεράκι». Παρά την τρομακτική του όψη, είναι από τους πιο αφοσιωμένους και καλόκαρδους ήρωες όλης της σάγκα.","fact":"Στην αρχική τριλογία τον Τσουμπάκα υποδύθηκε ο Πίτερ Μέιχιου, που ξεπερνούσε τα δύο μέτρα.","wiki_en":"Chewbacca"},{"name":"R2-D2","emoji":"🤖","meta":["«Πόλεμος των Άστρων»","αστρομηχανικό ντρόιντ","1977"],"description":"Μικρό αστρομηχανικό ντρόιντ, πιστός σύντροφος των ηρώων, ικανό να επισκευάζει διαστημόπλοια και να φυλάει τα πιο κρίσιμα μυστικά δεδομένα. Μιλά μόνο με ήχους και σφυρίγματα, κι όμως σχεδόν όλοι γύρω του τον καταλαβαίνουν άριστα.","fact":"Σε ορισμένες σκηνές της αρχικής τριλογίας μέσα στο κέλυφος του R2-D2 καθόταν ο κοντός ηθοποιός Κένι Μπέικερ.","wiki_en":"R2-D2"},{"name":"Γκρόγκου","emoji":"👶","meta":["«The Mandalorian»","μικρός του είδους του Γιόντα","2019"],"description":"Μυστηριώδες μικρό πλάσμα του ίδιου είδους με τον δάσκαλο Γιόντα, με έμφυτη σύνδεση με τη Δύναμη. Τον βρίσκει και τον παίρνει υπό την προστασία του ένας πολεμιστής Μανταλόριαν, και η συγκινητική τους φιλία έγινε το κεντρικό θέμα της σειράς.","fact":"Πριν ανακοινωθεί το επίσημο όνομά του, οι θεατές σε όλο τον κόσμο τον έλεγαν απλώς «μικρό Γιόντα».","wiki_en":"Grogu"},{"name":"Spider-Man","emoji":"🕷️","meta":["Marvel","υπερήρωας-αράχνη","1962"],"description":"Ο Πίτερ Πάρκερ, ένας συνηθισμένος μαθητής που μετά το δάγκωμα μιας ραδιενεργού αράχνης αποκτά υπεράνθρωπη δύναμη, ευλυγισία και αίσθηση του κινδύνου. Πολεμά το έγκλημα στη Νέα Υόρκη και στην καθημερινή ζωή παραμένει ένα μετρημένο παιδί.","fact":"Ο Σταν Λι και ο Στιβ Ντίτκο ήθελαν ο ήρωάς τους να έχει, σε αντίθεση με τους άλλους, τα πιο κοινά εφηβικά προβλήματα.","wiki_en":"Spider-Man"},{"name":"Iron Man","emoji":"🦾","meta":["Marvel","ιδιοφυΐα με πανοπλία","1963"],"description":"Ο δισεκατομμυριούχος εφευρέτης Τόνι Σταρκ φτιάχνει μια ισχυρή μαχητική στολή για να πολεμήσει το κακό και να εξιλεωθεί για τα δικά του όπλα που κατέληξαν σε λάθος χέρια. Το πνεύμα και η τεχνική του ευφυΐα τον έκαναν από τους πιο αναγνωρίσιμους υπερήρωες.","fact":"Ο ρόλος του Τόνι Σταρκ στο σινεμά της Marvel έκανε τον Ρόμπερτ Ντάουνι Τζούνιορ έναν από τους πιο ακριβοπληρωμένους ηθοποιούς.","wiki_en":"Iron Man"},{"name":"Captain America","emoji":"🛡️","meta":["Marvel","υπερστρατιώτης","1941"],"description":"Ο φιλάσθενος νέος Στιβ Ρότζερς, που χάρη σε ένα πειραματικό ορό γίνεται υπερστρατιώτης και σύμβολο του αγώνα κατά του φασισμού στον Β΄ Παγκόσμιο Πόλεμο. Στη σημερινή εποχή παραμένει το πρότυπο της στρατιωτικής τιμής μέσα στο σύμπαν της Marvel.","fact":"Ο Captain America δημιουργήθηκε πριν μπουν οι ΗΠΑ στον Β΄ Παγκόσμιο Πόλεμο και πολεμούσε τους ναζί από το πρώτο τεύχος.","wiki_en":"Captain America"},{"name":"Thor","emoji":"⚡","meta":["Marvel","θεός της βροντής","1962"],"description":"Ο πανίσχυρος θεός της βροντής από το Άσγκαρντ, κάτοχος του μαγικού σφυριού Μιόλνιρ, που μόνο ο άξιος μπορεί να σηκώσει. Περήφανος και οξύθυμος στην αρχή της ιστορίας του, μαθαίνει σταδιακά τη σοφία και την ευθύνη ενός ηγεμόνα.","fact":"Ο ήρωας της Marvel βασίζεται στον σκανδιναβικό θεό Θορ, αλλά με τα χρόνια απέκτησε δική του, αυτοτελή μυθολογία.","wiki_en":"Thor (Marvel Comics)"},{"name":"Hulk","emoji":"💚","meta":["Marvel","πράσινος γίγαντας","1962"],"description":"Ο επιστήμονας Μπρους Μπάνερ, που υπό την επίδραση της οργής μεταμορφώνεται σε ένα απίστευτα δυνατό πράσινο πλάσμα, σχεδόν άτρωτο στα συνηθισμένα όπλα. Η εσωτερική πάλη του λογικού ανθρώπου με το καταστροφικό τέρας είναι το κλειδί της ιστορίας του.","fact":"Στα κόμικς ο Hulk ήταν αρχικά γκρίζος, αλλά λόγω δυσκολιών στην εκτύπωση το χρώμα έγινε γρήγορα πράσινο.","wiki_en":"Hulk"},{"name":"Black Widow","emoji":"🖤","meta":["Marvel","κατάσκοπος των Avengers","1964"],"description":"Η Νατάσα Ρομανόφ, πρώην σοβιετική κατάσκοπος και εκτελέστρια, που περνά στο πλευρό της ομάδας υπερηρώων Avengers. Δεν έχει υπερδυνάμεις και στη μάχη βασίζεται στις πολεμικές της ικανότητες, στην πονηριά και σε χρόνια εκπαίδευσης στις μυστικές υπηρεσίες.","fact":"Στο σινεμά της Marvel τη Νατάσα Ρομανόφ υποδύθηκε η Σκάρλετ Γιόχανσον, από το «Iron Man 2» και μετά.","wiki_en":"Black Widow (Natasha Romanova)"},{"name":"Thanos","emoji":"💜","meta":["Marvel","Τιτάνας κατακτητής","1973"],"description":"Πανίσχυρος Τιτάνας με εμμονή να αποκαταστήσει την ισορροπία του σύμπαντος με ριζικό και σκληρό τρόπο. Κρατώντας αντικείμενα απίστευτης δύναμης, γίνεται ο μεγαλύτερος αντίπαλος που αντιμετώπισαν ποτέ οι υπερήρωες της Marvel.","fact":"Στις ταινίες της Marvel τον Thanos υποδύθηκε ο Τζος Μπρόλιν, αν και το μεγαλύτερο μέρος της μορφής του φτιάχτηκε ψηφιακά.","wiki_en":"Thanos"},{"name":"Loki","emoji":"🎭","meta":["Marvel","θεός της απάτης","1962"],"description":"Θετός αδελφός του Thor και θεός της απάτης της σκανδιναβικής μυθολογίας στην εκδοχή της Marvel, με κίνητρα που ταλαντεύονται αιώνια μεταξύ κακίας και ανάγκης να αποδείξει την αξία του. Η απροβλεψία του τον έκανε αγαπημένο αντιήρωα του κινηματογράφου.","fact":"Ο Τομ Χίντλστον πήρε τον ρόλο του Loki αφού αρχικά είχε δώσει οντισιόν για τον Thor.","wiki_en":"Loki (Marvel Comics)"},{"name":"Deadpool","emoji":"🗨️","meta":["Marvel","πολυλογάς μισθοφόρος","1991"],"description":"Ο Γουέιντ Γουίλσον, μισθοφόρος παραμορφωμένος από πειράματα που του χάρισαν ταχύτατη αναγέννηση και ένα ιδιότυπο χιούμορ. Σε αντίθεση με τους άλλους υπερήρωες, απευθύνεται συνεχώς κατευθείαν στον θεατή, σπάζοντας τον τέταρτο τοίχο.","fact":"Ο Deadpool ξεκίνησε ως παρωδία του Deathstroke της DC: τα αληθινά ονόματα, Γουέιντ Γουίλσον και Σλέιντ Γουίλσον, ηχούν επίτηδες ίδια.","wiki_en":"Deadpool"},{"name":"Wolverine","emoji":"🗡️","meta":["Marvel","μεταλλαγμένος με νύχια","1974"],"description":"Ο Λόγκαν, μεταλλαγμένος με ικανότητα αναγέννησης, οξυμένες αισθήσεις και ανασυρόμενα νύχια από υπερανθεκτικό μέταλλο. Ο οξύθυμος χαρακτήρας του και ένα παρελθόν γεμάτο απώλειες τον έκαναν από τους πιο δημοφιλείς ήρωες της Marvel.","fact":"Ο Χιου Τζάκμαν έπαιξε τον Wolverine σχεδόν δύο δεκαετίες, περισσότερο από τους περισσότερους ηθοποιούς σε άλλα φραντσάιζ υπερηρώων.","wiki_en":"Wolverine (character)"},{"name":"Groot","emoji":"🌳","meta":["Marvel","δεντρόμορφο πλάσμα","1960"],"description":"Εξωγήινο νοήμον πλάσμα που μοιάζει με δέντρο και μπορεί να λέει μόνο τη φράση «Είμαι ο Groot», κι όμως οι συνομιλητές του τον καταλαβαίνουν άριστα. Παρά το φτωχό του λεξιλόγιο, είναι από τα πιο αφοσιωμένα και συγκινητικά μέλη των «Φυλάκων του Γαλαξία».","fact":"Στις ταινίες της Marvel τη φωνή του Groot έδωσε ο Βιν Ντίζελ, λέγοντας την ίδια φράση με διαφορετικούς τόνους.","wiki_en":"Groot"},{"name":"Batman","emoji":"🦇","meta":["DC","υπερήρωας χωρίς δυνάμεις","1939"],"description":"Ο δισεκατομμυριούχος Μπρους Γουέιν, που γίνεται νυχτερινός τιμωρός αφού ένας ληστής του δρόμου σκοτώνει τους γονείς του. Χωρίς καμία υπερδύναμη, στηρίζεται στο μυαλό του, στις πολεμικές του ικανότητες και σε ένα οπλοστάσιο τεχνολογίας για να προστατεύει το Γκόθαμ.","fact":"Ο Batman είναι από τους λίγους εμβληματικούς υπερήρωες που δεν έχουν καμία υπερφυσική ικανότητα.","wiki_en":"Batman"},{"name":"Joker","emoji":"🃏","meta":["DC","παράφρων κακοποιός","1940"],"description":"Χαοτική εγκληματική ιδιοφυΐα με κατάλευκα βαμμένο πρόσωπο και ανατριχιαστικό χαμόγελο, ο βασικός αντίπαλος του Batman στο Γκόθαμ. Η πραγματική του καταγωγή παραμένει θολή, ενώ ο ίδιος ενσαρκώνει την καθαρή αναρχία και την απροβλεψία.","fact":"Ο ρόλος του Joker χάρισε Όσκαρ σε δύο ηθοποιούς, τον Χιθ Λέτζερ και τον Χοακίν Φίνιξ, σε διαφορετικές ταινίες.","wiki_en":"Joker (character)"},{"name":"Superman","emoji":"🪐","meta":["DC","υπερήρωας από τον Κρύπτον","1938"],"description":"Ο εξωγήινος Καλ-Ελ, που στάλθηκε μωρό από τον ετοιμοθάνατο πλανήτη Κρύπτον στη Γη, όπου αποκτά υπεράνθρωπη δύναμη, πτήση και σχεδόν πλήρη ατρωσία. Δουλεύοντας ως δημοσιογράφος με το όνομα Κλαρκ Κεντ, υπερασπίζεται τον κόσμο ως σύμβολο ελπίδας.","fact":"Ο Superman θεωρείται ένας από τους πρώτους υπερήρωες με τη σημερινή έννοια: το κόμικ του κυκλοφόρησε το 1938.","wiki_en":"Superman"},{"name":"Wonder Woman","emoji":"🪢","meta":["DC","αμαζόνα πολεμίστρια","1941"],"description":"Η Νταϊάνα, πριγκίπισσα των Αμαζόνων, που αφήνει το νησί της, τη Θεμίσκυρα, για να φέρει δικαιοσύνη και συμπόνια στον κόσμο των ανθρώπων. Πολεμά με το μαγικό λάσο της αλήθειας και υπεράνθρωπη δύναμη, από τις πρώτες πραγματικά εμβληματικές υπερηρωίδες.","fact":"Ο δημιουργός της Wonder Woman, Γουίλιαμ Μάρστον, ήταν και ένας από τους εφευρέτες μιας πρώιμης μορφής του ανιχνευτή ψεύδους.","wiki_en":"Wonder Woman"},{"name":"Harley Quinn","emoji":"🔨","meta":["DC","πρώην ψυχίατρος του Joker","1992"],"description":"Η Χάρλιν Κουίνζελ, ψυχίατρος στο άσυλο του Γκόθαμ, ερωτεύτηκε τον ασθενή της, τον Joker, έγινε συνεργός του και αργότερα αυτόνομη αντιηρωίδα. Η εκκεντρικότητα, η ακροβατική της δεινότητα και το μαύρο χιούμορ την έκαναν από τις πιο δημοφιλείς κακές της DC.","fact":"Η Harley Quinn δεν πρωτοεμφανίστηκε στα κόμικς αλλά στην κινούμενη σειρά «Batman» στις αρχές της δεκαετίας του 1990.","wiki_en":"Harley Quinn"},{"name":"Catwoman","emoji":"🐱","meta":["DC","κλέφτρα με μάσκα γάτας","1940"],"description":"Η Σελίνα Κάιλ, ευέλικτη διαρρήκτρια που δρα στο Γκόθαμ με μάσκα γάτας και ισορροπεί ανάμεσα στο έγκλημα και στη συμπάθειά της για τον Batman. Η σχέση της με τον Σκοτεινό Ιππότη είναι μείγμα ανταγωνισμού, φλερτ και αμοιβαίου σεβασμού.","fact":"Η Catwoman εμφανίστηκε στα κόμικς του Batman σχεδόν ταυτόχρονα με τον ίδιο τον Joker, το 1940.","wiki_en":"Catwoman"},{"name":"Τζέιμς Μποντ","emoji":"🍸","meta":["«Τζέιμς Μποντ»","Βρετανός πράκτορας","1953"],"description":"Ο κομψός πράκτορας της βρετανικής υπηρεσίας πληροφοριών με το σήμα 007, που συνδυάζει θανάσιμες ικανότητες με άψογο στιλ και ατάραχη ψυχραιμία. Οι περιπέτειές του απέναντι σε διεθνείς κακοποιούς γέννησαν μία από τις πιο μακρόβιες σειρές ταινιών.","fact":"Τον Τζέιμς Μποντ έχουν υποδυθεί στο σινεμά αρκετοί διαφορετικοί ηθοποιοί μέσα στις δεκαετίες, με πρώτο τον Σον Κόνερι.","wiki_en":"James Bond"},{"name":"Ιντιάνα Τζόουνς","emoji":"🤠","meta":["«Ιντιάνα Τζόουνς»","αρχαιολόγος τυχοδιώκτης","1981"],"description":"Καθηγητής αρχαιολογίας που στον χρόνο του εκτός αμφιθεάτρου κυνηγά αρχαία κειμήλια σε επικίνδυνες αποστολές σε όλο τον κόσμο. Το καπέλο και το μαστίγιό του έγιναν από τα πιο αναγνωρίσιμα σύμβολα του περιπετειώδους κινηματογράφου.","fact":"Τον Ιντιάνα Τζόουνς υποδυόταν επί δεκαετίες αποκλειστικά ο Χάρισον Φορντ.","wiki_en":"Indiana Jones"},{"name":"Εξολοθρευτής T-800","emoji":"🤖","meta":["«Εξολοθρευτής»","ρομπότ δολοφόνος","1984"],"description":"Κυβόργιο σταλμένο από το μέλλον, με μεταλλικό σκελετό κάτω από ζωντανό ιστό, φτιαγμένο να φέρνει σε πέρας την αποστολή του ό,τι κι αν συμβεί. Ανάλογα με την ταινία εμφανίζεται άλλοτε ως αδίστακτος δολοφόνος και άλλοτε ως προστάτης των ανθρώπων.","fact":"Η ατάκα «I'll be back» δεν γράφτηκε για να μείνει: έγινε σήμα κατατεθέν του ήρωα μόνο μετά την προβολή της ταινίας.","wiki_en":"Terminator (character)"},{"name":"Ρόκι Μπαλμπόα","emoji":"🥊","meta":["«Ρόκι»","πυγμάχος από τη Φιλαδέλφεια","1976"],"description":"Ταπεινός ερασιτέχνης πυγμάχος από τη Φιλαδέλφεια, που παίρνει απρόσμενα την ευκαιρία να αναμετρηθεί με τον παγκόσμιο πρωταθλητή. Η ιστορία του πείσματος, της προπόνησης και της αυτοπεποίθησής του έγινε σύμβολο υπέρβασης για γενιές θεατών.","fact":"Το σενάριο για τον Ρόκι το έγραψε ο ίδιος ο Σιλβέστερ Σταλόνε για να πάρει τον πρωταγωνιστικό ρόλο, ενώ τα στούντιο ήθελαν άλλα αστέρια.","wiki_en":"Rocky Balboa"},{"name":"Τζον Ράμπο","emoji":"🪖","meta":["«Ράμπο»","βετεράνος των ειδικών δυνάμεων","1972"],"description":"Βετεράνος του πολέμου του Βιετνάμ, του οποίου η εκπαίδευση στην επιβίωση και στη μάχη καταλήγει σε βίαιη σύγκρουση με τις αρχές μιας ήσυχης μικρής πόλης. Ο ήρωας έγινε σύμβολο της δύσκολης μοίρας των στρατιωτών που γύρισαν σε μια αδιάφορη κοινωνία.","fact":"Ο ήρωας γεννήθηκε στα βιβλία: πρώτα ήρθε το μυθιστόρημα «Πρώτο αίμα» του Ντέιβιντ Μόρελ και δέκα χρόνια μετά η ταινία με τον Σταλόνε.","wiki_en":"John Rambo"},{"name":"Τζον Γουίκ","emoji":"🐕","meta":["«Τζον Γουίκ»","συνταξιούχος εκτελεστής","2014"],"description":"Θρυλικός επαγγελματίας δολοφόνος που προσπάθησε να αποσυρθεί μετά τον θάνατο της γυναίκας του, αλλά αναγκάζεται να επιστρέψει στον κόσμο του εγκλήματος. Η ψυχραιμία, οι πολεμικές του ικανότητες και οι καταιγιστικές ανταλλαγές πυρών έκαναν τη σειρά πρότυπο σύγχρονης δράσης.","fact":"Ο Κιάνου Ριβς εκτέλεσε ο ίδιος μεγάλο μέρος των ακροβατικών και της σκοποβολής, προπονούμενος επί μήνες για τον ρόλο.","wiki_en":"John Wick (character)"},{"name":"Νίο","emoji":"💊","meta":["«Μάτριξ»","ο εκλεκτός χάκερ","1999"],"description":"Ο προγραμματιστής Τόμας Άντερσον ανακαλύπτει ότι ο γνώριμος κόσμος είναι μια προσομοίωση υπολογιστή και παίρνει την ευκαιρία να ελευθερώσει την ανθρωπότητα. Η επιλογή ανάμεσα στο μπλε και στο κόκκινο χάπι έγινε μία από τις πιο αναγνωρίσιμες εικόνες του σινεμά.","fact":"Τον Νίο υποδύθηκε ο Κιάνου Ριβς, ενώ τη χορογραφία των μαχών ανέλαβαν δάσκαλοι του κινηματογράφου του Χονγκ Κονγκ.","wiki_en":"Neo (The Matrix)"},{"name":"Έλεν Ρίπλεϊ","emoji":"👩‍🚀","meta":["«Άλιεν»","επιζήσασα στο διάστημα","1979"],"description":"Αξιωματικός εμπορικού διαστημοπλοίου, η μόνη που καταφέρνει να αντισταθεί σε έναν θανάσιμο εξωγήινο θηρευτή. Η ψυχραιμία και η αποφασιστικότητά της την έκαναν μία από τις πρώτες πραγματικά δυνατές ηρωίδες του κινηματογράφου επιστημονικής φαντασίας.","fact":"Η Σιγκούρνεϊ Γουίβερ ήταν υποψήφια για Όσκαρ για τη Ρίπλεϊ στη συνέχεια «Άλιενς», κάτι σπάνιο για ταινία δράσης και φαντασίας.","wiki_en":"Ellen Ripley"},{"name":"Μάρτι ΜακΦλάι","emoji":"⏰","meta":["«Επιστροφή στο Μέλλον»","ταξιδιώτης του χρόνου","1985"],"description":"Ένας συνηθισμένος μαθητής λυκείου που καταλήγει κατά λάθος, μέσα σε ένα μετασκευασμένο αυτοκίνητο, στα νιάτα των γονιών του. Πρέπει να τους φέρει κοντά χωρίς να αλλάξει την ιστορία, όσο ο φίλος του ο εφευρέτης ψάχνει τρόπο να τον γυρίσει πίσω.","fact":"Το DeLorean έγινε χρονομηχανή ήδη στο σενάριο: σε μια πρώιμη εκδοχή τον ρόλο του έπαιζε ένα κοινό ψυγείο.","wiki_en":"Marty McFly"},{"name":"Φόρεστ Γκαμπ","emoji":"🍫","meta":["«Φόρεστ Γκαμπ»","αγαθός νότιος","1986"],"description":"Καλόκαρδος άνθρωπος από την Αλαμπάμα που, παρά τις περιορισμένες νοητικές του ικανότητες, βρίσκεται άθελά του μάρτυρας και συμμέτοχος στα μεγάλα γεγονότα της αμερικανικής ιστορίας του 20ού αιώνα. Η ειλικρίνεια και η πιστή αγάπη του για την Τζένι συγκινούν εδώ και δεκαετίες.","fact":"Την περίφημη ατάκα για το κουτί με τα σοκολατάκια δεν την έγραψε ο συγγραφέας του μυθιστορήματος αλλά ο σεναριογράφος της ταινίας.","wiki_en":"Forrest Gump"},{"name":"Καπετάνιος Τζακ Σπάροου","emoji":"🏴‍☠️","meta":["«Πειρατές της Καραϊβικής»","πονηρός καπετάνιος πειρατής","2003"],"description":"Ο εξεζητημένος και διαρκώς μεθυσμένος καπετάνιος του «Μαύρου Μαργαριταριού», που ξεγλιστρά από κάθε μπελά με πονηριά, γοητεία και τύχη. Το τρεκλό του βάδισμα και οι απρόβλεπτες αποφάσεις του έγιναν σήμα κατατεθέν όλου του φραντσάιζ.","fact":"Ο Τζόνι Ντεπ έχει παραδεχτεί ότι έχτισε τον χαρακτήρα εμπνεόμενος από τους τρόπους του μουσικού Κιθ Ρίτσαρντς.","wiki_en":"Jack Sparrow"},{"name":"Χάνιμπαλ Λέκτερ","emoji":"🧠","meta":["μυθιστορήματα του Τόμας Χάρις","ψυχίατρος και κανίβαλος","1981"],"description":"Λαμπρός ψυχίατρος με οξύτατο μυαλό και εκλεπτυσμένο γούστο, που πίσω από τους άψογους τρόπους του κρύβει κλίση σε τερατώδη εγκλήματα. Η αναγκαστική συνεργασία του με τους ερευνητές για τη σύλληψη ενός άλλου δολοφόνου γέννησε ένα θρυλικό θρίλερ.","fact":"Ο ρόλος χάρισε στον Άντονι Χόπκινς Όσκαρ, παρότι ο χρόνος του στην οθόνη ήταν εξαιρετικά μικρός.","wiki_en":"Hannibal Lecter"},{"name":"Τάιλερ Ντέρντεν","emoji":"🧼","meta":["«Λέσχη του Καυγά»","χαρισματικός αναρχικός","1996"],"description":"Θρασύς και χαρισματικός έμπορος σαπουνιού, που στήνει μια υπόγεια λέσχη πυγμαχίας ως διαμαρτυρία ενάντια στην καταναλωτική κοινωνία. Η φιλοσοφία του περί αυτοκαταστροφής και απαλλαγής από τα πράγματα μετατρέπει απλούς άντρες σε μέλη ενός ριζοσπαστικού κινήματος.","fact":"Ο ήρωας πρωτοεμφανίστηκε στο μυθιστόρημα του Τσακ Παλάνιουκ και τον έκανε θρύλο η μεταφορά του Ντέιβιντ Φίντσερ.","wiki_en":"Tyler Durden"},{"name":"Βίτο Κορλεόνε","emoji":"🐈","meta":["«Ο Νονός»","αρχηγός οικογένειας της μαφίας","1969"],"description":"Σεβαστός και φοβερός αρχηγός μιας ιταλοαμερικανικής οικογένειας της μαφίας, που ζει με τον δικό του σκληρό κώδικα τιμής και δικαιοσύνης. Η ήρεμη εξουσία του και η περίφημη βραχνή του φωνή έγιναν πρότυπο για αμέτρητες μιμήσεις στο σινεμά.","fact":"Ο ρόλος του Βίτο Κορλεόνε χάρισε στον Μάρλον Μπράντο Όσκαρ, το οποίο ο ηθοποιός αρνήθηκε επιδεικτικά.","wiki_en":"Vito Corleone"},{"name":"Τόνι Μοντάνα","emoji":"🚬","meta":["«Ο Σημαδεμένος»","Κουβανός βαρόνος ναρκωτικών","1983"],"description":"Φιλόδοξος Κουβανός μετανάστης που ανεβαίνει με βίαιο και ιλιγγιώδη τρόπο στην κορυφή της αυτοκρατορίας ναρκωτικών του Μαϊάμι. Η ακόρεστη δίψα του για εξουσία και η περίφημη τελευταία του ατάκα τον έκαναν εμβληματική μορφή του αστυνομικού κινηματογράφου.","fact":"Τον Τόνι Μοντάνα υποδύθηκε ο Αλ Πατσίνο, που δούλεψε ειδικά πάνω στην κουβανική προφορά του ήρωα.","wiki_en":"Tony Montana"},{"name":"Σέρλοκ Χολμς","emoji":"🔍","meta":["Άρθουρ Κόναν Ντόιλ","ιδιοφυής ντετέκτιβ","1887"],"description":"Ο οξυδερκής σύμβουλος ντετέκτιβ του Λονδίνου, που εξιχνιάζει τα πιο μπερδεμένα εγκλήματα με επαγωγικό συλλογισμό και προσοχή στην παραμικρή λεπτομέρεια. Η φιλία του με τον δόκτορα Γουάτσον, η πίπα και ο δίκορφος σκούφος έγιναν το σύμβολο του κλασικού αστυνομικού.","fact":"Ο Άρθουρ Κόναν Ντόιλ προσπάθησε να σκοτώσει τον Χολμς σε ένα διήγημα, αλλά η πίεση των αναγνωστών τον ανάγκασε να τον επαναφέρει.","wiki_en":"Sherlock Holmes"},{"name":"Δόκτωρ Γουάτσον","emoji":"🩺","meta":["Άρθουρ Κόναν Ντόιλ","πιστός φίλος και γιατρός","1887"],"description":"Απόστρατος στρατιωτικός γιατρός, που γίνεται συγκάτοικος και σταθερός σύντροφος του Σέρλοκ Χολμς στις έρευνές του. Οι περισσότερες ιστορίες του ντετέκτιβ αφηγούνται από τη δική του οπτική, ενώ η πρακτικότητά του αναδεικνύει την εκκεντρική ιδιοφυΐα του φίλου του.","fact":"Το όνομα του δόκτορα Γουάτσον έγινε με τον καιρό συνώνυμο του πιστού βοηθού μιας ιδιοφυΐας.","wiki_en":"Dr. Watson"},{"name":"Ηρακλής Πουαρό","emoji":"🥚","meta":["Αγκάθα Κρίστι","Βέλγος ντετέκτιβ","1920"],"description":"Εκκεντρικός Βέλγος ντετέκτιβ με πλούσιο μουστάκι, που βασίζεται στα «μικρά γκρίζα κύτταρα» του μυαλού του και όχι στη σωματική δύναμη. Η τάξη και η σχολαστικότητά του ξεδιαλύνουν τα πιο περίτεχνα εγκλήματα στα μυθιστορήματα της Αγκάθα Κρίστι.","fact":"Με τον καιρό η Αγκάθα Κρίστι κουράστηκε τον ήρωά της και τον χαρακτήριζε κάποτε ανυπόφορο και ενοχλητικό τύπο.","wiki_en":"Hercule Poirot"},{"name":"Κόμης Δράκουλας","emoji":"🦇","meta":["Μπραμ Στόκερ","αριστοκράτης βρικόλακας","1897"],"description":"Κόμης βρικόλακας από την Τρανσυλβανία, που ζει αιώνες πίνοντας ανθρώπινο αίμα και μπορεί να μεταμορφώνεται σε νυχτερίδα. Η μορφή που έπλασε ο Μπραμ Στόκερ αποτελεί την πηγή σχεδόν όλης της σύγχρονης μυθολογίας των βρικολάκων.","fact":"Ως πρότυπο του κόμη θεωρείται εν μέρει ο ηγεμόνας της Βλαχίας του 15ου αιώνα Βλαντ ο Παλουκωτής, γνωστός για τη σκληρότητά του.","wiki_en":"Dracula"},{"name":"Το τέρας του Φρανκενστάιν","emoji":"⚡","meta":["Μέρι Σέλεϊ","τεχνητός γίγαντας","1818"],"description":"Ανώνυμο πλάσμα, φτιαγμένο από τον επιστήμονα Βίκτορ Φρανκενστάιν από μέλη νεκρών σωμάτων και ζωντανεμένο με τρόπο άγνωστο στην επιστήμη. Παρά την τρομακτική του όψη, στο μυθιστόρημα της Μέρι Σέλεϊ είναι ένα πονεμένο και μοναχικό ον, απορριμμένο από τον ίδιο του τον δημιουργό.","fact":"Στη μαζική κουλτούρα το όνομα του δημιουργού, Φρανκενστάιν, αποδίδεται λανθασμένα στο ίδιο το τέρας.","wiki_en":"Frankenstein's monster"},{"name":"Κινγκ Κονγκ","emoji":"🦍","meta":["«Κινγκ Κονγκ»","γιγάντιος γορίλας","1933"],"description":"Τεράστιος νοήμων γορίλας που ζει στο χαμένο Νησί του Κρανίου και αιχμαλωτίζεται για να μεταφερθεί στη Νέα Υόρκη ως αξιοθέατο. Η τελική του αναρρίχηση σε ουρανοξύστη έγινε μία από τις πιο αναγνωρίσιμες εικόνες του κινηματογράφου των τεράτων.","fact":"Στην αρχική ταινία του 1933 ο Κινγκ Κονγκ ζωντάνευε με τεχνική κίνησης καρέ καρέ μιας μικρής μακέτας.","wiki_en":"King Kong"},{"name":"Γκοτζίλα","emoji":"🦖","meta":["Toho","γιγάντιο τέρας σαύρα","1954"],"description":"Πελώριο τέρας που ξύπνησε από τις πυρηνικές δοκιμές και εκτοξεύει από το στόμα του καταστροφική ατομική ακτίνα. Φτιαγμένο αρχικά ως μεταφορά για τη φρίκη των πυρηνικών όπλων, έγινε ένα από τα πιο αναγνωρίσιμα τέρατα του παγκόσμιου σινεμά.","fact":"Η αρχική στολή της Γκοτζίλα του 1954 ζύγιζε δεκάδες κιλά και ο ηθοποιός μέσα της δυσκολευόταν πάρα πολύ να κινηθεί.","wiki_en":"Godzilla"},{"name":"Ταρζάν","emoji":"🌴","meta":["Έντγκαρ Ράις Μπάροουζ","ο άνθρωπος της ζούγκλας","1912"],"description":"Άγγλος αριστοκράτης εκ γενετής, που μεγάλωσε ανάμεσα σε πιθήκους στη ζούγκλα της Αφρικής μετά τον θάνατο των γονιών του. Η απίστευτη σωματική του δύναμη, η περίφημη κραυγή και η φιλία του με τα ζώα τον έκαναν ήρωα της περιπετειώδους λογοτεχνίας και του σινεμά.","fact":"Η περίφημη κραυγή του Ταρζάν στις παλιές ταινίες φτιάχτηκε στο στούντιο, με ανάμειξη διαφορετικών ηχητικών εγγραφών.","wiki_en":"Tarzan"},{"name":"Ζορό","emoji":"🗡️","meta":["Τζόνστον ΜακΚάλεϊ","εκδικητής με μάσκα","1919"],"description":"Αριστοκράτης που κάτω από μάσκα και μανδύα υπερασπίζεται τους απλούς ανθρώπους της Καλιφόρνια απέναντι στην αδικία των αποικιακών αρχών. Το σήμα του, ένα γράμμα Z χαραγμένο με το σπαθί, έγινε έμβλημα του ευγενούς μασκοφόρου εκδικητή.","fact":"Ο ήρωας επηρέασε τον Batman: στα κόμικς ο Μπρους Γουέιν χάνει τους γονείς του γυρίζοντας από προβολή ταινίας του Ζορό.","wiki_en":"Zorro"},{"name":"Ρομπέν των Δασών","emoji":"🏹","meta":["αγγλική λαϊκή παράδοση","ευγενής ληστής","πριν τον 15ο αιώνα"],"description":"Ο θρυλικός ευγενής ληστής του δάσους του Σέργουντ, που κλέβει τους πλούσιους και μοιράζει τα λάφυρα στους φτωχούς μαζί με την πιστή του συντροφιά. Η σύγκρουσή του με τον σκληρό σερίφη του Νότιγχαμ και η ευστοχία του στο τόξο γέννησαν αμέτρητα βιβλία και ταινίες.","fact":"Οι ιστορικοί διαφωνούν ακόμη για το αν πίσω από τον θρύλο υπήρξε κάποιο πραγματικό πρόσωπο.","wiki_en":"Robin Hood"},{"name":"Πίτερ Παν","emoji":"🧚","meta":["Τζέιμς Μπάρι","το αγόρι που δεν μεγάλωσε","1904"],"description":"Το αγόρι που αρνήθηκε να μεγαλώσει και ζει στο μαγικό νησί της Χώρας του Ποτέ ανάμεσα σε νεράιδες και πειρατές. Ξέρει να πετά και το μαθαίνει στα παιδιά της οικογένειας Ντάρλινγκ, ενώ αιώνιος αντίπαλός του είναι ο δόλιος καπετάν Γάντζος.","fact":"Το όνομα του ήρωα έγινε συνώνυμο των ενηλίκων που ψυχολογικά δεν μεγάλωσαν ποτέ.","wiki_en":"Peter Pan"},{"name":"Αλίκη στη Χώρα των Θαυμάτων","emoji":"🐇","meta":["Λιούις Κάρολ","περίεργο κορίτσι","1865"],"description":"Περίεργο αγγλάκι που ακολουθεί το Άσπρο Κουνέλι μέσα στο λαγούμι του και βρίσκεται σε μια παράλογη μαγική χώρα. Οι συναντήσεις της με τον Γάτο του Τσεσάιρ, τον Τρελό Καπελά και τη Βασίλισσα Κούπα είναι κλασικά δείγματα της αγγλικής λογοτεχνίας του παραλόγου.","fact":"Ο Λιούις Κάρολ σκέφτηκε την ιστορία κάνοντας βαρκάδα με ένα αληθινό κορίτσι που το έλεγαν Αλίκη και με τις αδελφές της.","wiki_en":"Alice (Alice's Adventures in Wonderland)"},{"name":"Γουίνι το Αρκουδάκι","emoji":"🍯","meta":["Άλαν Μιλν","λούτρινο αρκουδάκι","1926"],"description":"Καλόκαρδο λούτρινο αρκουδάκι με πριονίδι στο κεφάλι και αμετακίνητη αγάπη για το μέλι, που ζει στο Δάσος των Εκατό Στρεμμάτων. Μαζί με τους φίλους του, το Γουρουνάκι, τον μελαγχολικό γαϊδαράκο και τον Τίγρη, ζει απλές αλλά συγκινητικές ιστορίες φιλίας.","fact":"Πρότυπο του αρκουδάκιου στάθηκε ένα αληθινό λούτρινο παιχνίδι του γιου του συγγραφέα Άλαν Μιλν.","wiki_en":"Winnie-the-Pooh"},{"name":"Κάρλσον στη στέγη","emoji":"🌀","meta":["Άστριντ Λίντγκρεν","χοντρούλης με έλικα","1955"],"description":"Αστείος και καυχησιάρης χοντρούλης που ζει στη στέγη μιας πολυκατοικίας της Στοκχόλμης και πετά χάρη σε έναν έλικα στην πλάτη του. Γίνεται ο κρυφός φίλος ενός μοναχικού αγοριού και το παρασύρει στις σκανταλιές και στις παράλογες ιδέες του.","fact":"Στο σουηδικό πρωτότυπο της Άστριντ Λίντγκρεν ο τίτλος είναι «Karlsson på taket», δηλαδή ο Κάρλσον πάνω στη στέγη.","wiki_en":"Karlsson-on-the-Roof"},{"name":"Πίπη Φακιδομύτη","emoji":"🧦","meta":["Άστριντ Λίντγκρεν","το πιο δυνατό κορίτσι","1945"],"description":"Κοκκινομάλλα με πεταχτές κοτσίδες, που ζει μόνη στο δικό της σπίτι με μια μαϊμού και ένα άλογο, χωρίς κανέναν μεγάλο. Με απίστευτη σωματική δύναμη και πλήρη περιφρόνηση για τους τύπους, αναστατώνει τη ζωή μιας ήσυχης σουηδικής κωμόπολης.","fact":"Η Άστριντ Λίντγκρεν επινόησε την ιστορία για την άρρωστη κόρη της, ενώ το όνομα της ηρωίδας το διάλεξε το ίδιο το κορίτσι.","wiki_en":"Pippi Longstocking"},{"name":"Ο Μικρός Πρίγκιπας","emoji":"🌹","meta":["Αντουάν ντε Σεντ-Εξιπερί","αγόρι από αστεροειδή","1943"],"description":"Μυστηριώδες αγόρι που ήρθε από έναν μικροσκοπικό αστεροειδή, όπου μεγαλώνει το μοναδικό τριαντάφυλλο της ζωής του. Η συνάντησή του με έναν αεροπόρο ναυαγισμένο στην έρημο γίνεται φιλοσοφική παραβολή για την αγάπη, τη φιλία και το ουσιώδες.","fact":"Το βιβλίο του Σεντ-Εξιπερί είναι από τα πιο πολυμεταφρασμένα στον κόσμο, με ελάχιστους τίτλους να το ξεπερνούν σε γλώσσες.","wiki_en":"The Little Prince"},{"name":"Πινόκιο","emoji":"🤥","meta":["Κάρλο Κολόντι","ξύλινο αγόρι","1883"],"description":"Ξύλινη μαριονέτα, σκαλισμένη από τον γερο-μαραγκό Τζεπέτο, που ονειρεύεται να γίνει αληθινό ζωντανό παιδί. Κάθε ψέμα του κάνει τη μύτη του να μακραίνει, και ο δρόμος του προς την ανθρώπινη υπόσταση περνά από μια σειρά διδακτικών περιπετειών.","fact":"Στο ιταλικό πρωτότυπο η ιστορία είναι πολύ πιο σκοτεινή και σκληρή από τη γνωστή εκδοχή της Disney.","wiki_en":"Pinocchio"},{"name":"Σταχτοπούτα","emoji":"👠","meta":["ευρωπαϊκή λαϊκή παράδοση","καλόκαρδη προγονή","17ος αιώνας"],"description":"Πράο κορίτσι που υπομένει τους εξευτελισμούς της μητριάς και των ετεροθαλών αδελφών της, ώσπου μια καλή νεράιδα το στέλνει στον βασιλικό χορό. Το χαμένο κρυστάλλινο γοβάκι γίνεται το κλειδί της ευτυχίας της σε ένα από τα πιο γνωστά παραμύθια του κόσμου.","fact":"Παρόμοιες ιστορίες για μια κατατρεγμένη προγονή υπάρχουν στη λαϊκή παράδοση πολλών λαών, πολύ πριν τη γαλλική εκδοχή του Περό.","wiki_en":"Cinderella"},{"name":"Χιονάτη","emoji":"🍎","meta":["αδελφοί Γκριμ","η ομορφότερη πριγκίπισσα","1812"],"description":"Νέα πριγκίπισσα, της οποίας η ομορφιά προκαλεί τη ζήλια της κακιάς μητριάς βασίλισσας, που διατάζει να την ξεφορτωθούν. Το καταφύγιο στους εφτά νάνους και το φαρμακωμένο μήλο έκαναν το παραμύθι μία από τις πιο αναγνωρίσιμες ιστορίες της παγκόσμιας κουλτούρας.","fact":"Η «Χιονάτη και οι εφτά νάνοι» ήταν η πρώτη ταινία μεγάλου μήκους της Disney και από τις πρώτες στην ιστορία του κινουμένου σχεδίου.","wiki_en":"Snow White"},{"name":"Άριελ η Μικρή Γοργόνα","emoji":"🧜‍♀️","meta":["Disney","ονειροπόλα γοργόνα","1989"],"description":"Περίεργη νεαρή γοργόνα που λαχταρά να γνωρίσει τον κόσμο των ανθρώπων και είναι έτοιμη να θυσιώσει για αυτό τη φωνή της. Η συλλογή της από ανθρώπινα μικροπράγματα και η λαχτάρα της για έναν φαινομενικά άπιαστο κόσμο την έκαναν αγαπημένη πριγκίπισσα της Disney.","fact":"Η ταινία της Disney βασίζεται στο παραμύθι του Χανς Κρίστιαν Άντερσεν, αν και το τέλος στην εκδοχή της Disney είναι πολύ πιο γλυκό.","wiki_en":"Ariel (The Little Mermaid)"},{"name":"Έλσα","emoji":"❄️","meta":["Disney, «Ψυχρά κι Ανάποδα»","βασίλισσα με μαγεία του χιονιού","2013"],"description":"Η μεγαλύτερη από δύο αδελφές πριγκίπισσες, γεννημένη με μαγική εξουσία στον πάγο και στο χιόνι, που από παιδί έμαθε να την καταπιέζει και να την κρύβει. Η πορεία της προς την αποδοχή της δύναμής της και το περίφημο τραγούδι για την ελευθερία έγιναν φαινόμενο πολύ πέρα από το παιδικό κοινό.","fact":"Το τραγούδι της Έλσα από την ταινία κέρδισε Όσκαρ καλύτερου τραγουδιού και έγινε μία από τις πιο αναγνωρίσιμες μελωδίες της Disney.","wiki_en":"Elsa (Frozen)"},{"name":"Σίμπα","emoji":"🦁","meta":["Disney, «Ο Βασιλιάς των Λιονταριών»","νεαρός διάδοχος λέοντας","1994"],"description":"Λιονταράκι και διάδοχος του θρόνου της σαβάνας, που μετά μια τραγωδία στην οικογένειά του αναγκάζεται να φύγει από το κοπάδι του. Η ενηλικίωσή του, η φιλία με τον Τιμόν και τον Πούμπα και τελικά η επιστροφή του για τον θρόνο είναι κλασική ιστορία ωρίμανσης.","fact":"Η πλοκή συγκρίνεται συχνά με τον «Άμλετ» του Σαίξπηρ, ομοιότητα που έχουν παραδεχτεί και οι δημιουργοί της ταινίας.","wiki_en":"Simba"},{"name":"Μίκι Μάους","emoji":"🐭","meta":["Disney","το ποντίκι-σύμβολο του στούντιο","1928"],"description":"Χαρούμενο ποντίκι με κόκκινο σορτσάκι και μεγάλα κίτρινα παπούτσια, που έγινε το επίσημο σύμβολο ολόκληρης της εταιρείας Disney. Η πρώτη του εμφάνιση σε μια ταινία μικρού μήκους με συγχρονισμένο ήχο θεωρείται σταθμός στην ιστορία του κινουμένου σχεδίου.","fact":"Αρχικά τη φωνή του Μίκι Μάους την έδινε ο ίδιος ο δημιουργός του, ο Γουόλτ Ντίσνεϊ.","wiki_en":"Mickey Mouse"},{"name":"Ντόναλντ Ντακ","emoji":"🦆","meta":["Disney","οξύθυμος πάπιος","1934"],"description":"Οξύθυμος και άτυχος πάπιος με ναυτικό μπλουζάκι, που η χαρακτηριστική τραχιά φωνή του και οι συχνές εκρήξεις οργής τον έκαναν από τους πιο δημοφιλείς ήρωες της Disney. Παρά τις αποτυχίες του, το κοινό τον αγαπά για την ειλικρίνεια των συναισθημάτων του.","fact":"Τη φωνή του Ντόναλντ Ντακ έδινε επί δεκαετίες ο ίδιος ηθοποιός, ο Κλάρενς Νας.","wiki_en":"Donald Duck"},{"name":"Γκούφι","emoji":"🐶","meta":["Disney","αδέξιος καλόκαρδος","1932"],"description":"Ψηλόλιγνος και καλόκαρδος, αλλά απίστευτα αδέξιος ανθρωπόμορφος σκύλος, φίλος του Μίκι Μάους και του Ντόναλντ Ντακ. Οι κωμικές τούμπες του και η χαρακτηριστική κραυγή που βγάζει καθώς πέφτει έγιναν σήμα κατατεθέν του κλασικού σχεδίου της Disney.","fact":"Πριν γίνει αυτόνομος ήρωας, ο Γκούφι εμφανιζόταν στα καρτούν απλώς ως ανώνυμος θεατής στην εξέδρα.","wiki_en":"Goofy"},{"name":"Μπαγκς Μπάνι","emoji":"🥕","meta":["Warner Bros, «Looney Tunes»","πονηρός λαγός","1940"],"description":"Ατάραχος γκρίζος λαγός με ένα καρότο στα χέρια, που ξεγελά πάντα τους άτυχους αντιπάλους του, από τον κυνηγό Έλμερ Φαντ μέχρι δεκάδες άλλους. Η ατάκα του «What's up, Doc?» είναι από τις πιο πολυθρύλητες στην ιστορία του κινουμένου σχεδίου.","fact":"Ο τρόπος που ο Μπαγκς μασά το καρότο ενώ μιλά ήταν, κατά τους σχεδιαστές, νεύμα σε μια σκηνή ταινίας με τον Κλαρκ Γκέιμπλ.","wiki_en":"Bugs Bunny"},{"name":"Τομ και Τζέρι","emoji":"🧀","meta":["MGM","αντίπαλοι γάτος και ποντίκι","1940"],"description":"Ο οικόσιτος γάτος Τομ και το πονηρό ποντίκι Τζέρι, που κυνηγιούνται ατέρμονα σε εναλλασσόμενες νίκες και ήττες, σχεδόν χωρίς λέξη. Οι τρελές τους καταδιώξεις, γεμάτες σωματική κωμωδία, έγιναν κλασικά δείγματα του παγκόσμιου κινουμένου σχεδίου.","fact":"Παρά τις αδιάκοπες τσακωμάρες, η σειρά κέρδισε μέσα στα χρόνια αρκετά Όσκαρ ταινίας μικρού μήκους.","wiki_en":"Tom and Jerry"},{"name":"Σκούμπι-Ντου","emoji":"🐕","meta":["Hanna-Barbera","δειλός σκύλος ντετέκτιβ","1969"],"description":"Μεγαλόσωμος και δειλός δανέζικος σκύλος, λάτρης των μπισκότων, που μπλέκει συνεχώς σε μυστηριώδεις περιπέτειες μαζί με μια παρέα εφήβων. Παρά τον τρόμο του για τα φαντάσματα, συχνά είναι η τυχαία δική του βοήθεια που ξεσκεπάζει το επόμενο «τέρας».","fact":"Το όνομα του ήρωα εμπνεύστηκε από έναν στίχο του τραγουδιού Strangers in the Night του Φρανκ Σινάτρα.","wiki_en":"Scooby-Doo (character)"},{"name":"Χόμερ Σίμπσον","emoji":"🍩","meta":["«The Simpsons»","αγαθιάρης οικογενειάρχης","1989"],"description":"Εργαζόμενος σε πυρηνικό εργοστάσιο στη φανταστική πόλη Σπρίνγκφιλντ, γνωστός για την αγάπη του στα ντόνατς και στην μπίρα, αλλά και για τη σπάνια ατυχία του. Η ατάκα που ξεφεύγει σε κάθε νέα αποτυχία του έγινε από τις πιο αναγνωρίσιμες του κινουμένου σχεδίου.","fact":"Η κραυγή του Χόμερ «D'oh!» καταχωρίστηκε με τον καιρό επίσημα στα αγγλικά λεξικά.","wiki_en":"Homer Simpson"},{"name":"Μπαρτ Σίμπσον","emoji":"🛹","meta":["«The Simpsons»","άτακτος μαθητής","1989"],"description":"Δεκάχρονος ακαταπόνητος και ο μεγαλύτερος άτακτος του σχολείου στο Σπρίνγκφιλντ, λάτρης των φαρσών και του σκέιτμπορντ. Η ατάκα του «¡Ay, caramba!» και το χαρακτηριστικό του κούρεμα τον έκαναν από τους πιο αναγνωρίσιμους έφηβους του κινουμένου σχεδίου.","fact":"Τη φωνή του Μπαρτ Σίμπσον δίνει επί δεκαετίες αδιάλειπτα η ηθοποιός Νάνσι Κάρτραϊτ.","wiki_en":"Bart Simpson"},{"name":"Πίτερ Γκρίφιν","emoji":"🍺","meta":["«Family Guy»","αγαθιάρης οικογενειάρχης","1999"],"description":"Εκρηκτικός και κουτός αρχηγός μιας οικογένειας στη φανταστική πόλη Κουαχόγκ, λάτρης της μπίρας και των ατελείωτων καβγάδων με ένα γιγαντιαίο κοτόπουλο. Η σειρά στηρίζεται στις παράλογες πράξεις του και στις αναφορές στην ποπ κουλτούρα που πετά μέσα στη δράση.","fact":"Στο πρωτότυπο τη φωνή του Πίτερ Γκρίφιν δίνει ο ίδιος ο δημιουργός της σειράς, ο Σεθ ΜακΦάρλεϊν.","wiki_en":"Peter Griffin"},{"name":"Έρικ Κάρτμαν","emoji":"🧥","meta":["«South Park»","ανυπόφορος μαθητής","1997"],"description":"Ένα από τα τέσσερα αγόρια της πόλης Σάουθ Παρκ, γνωστό για τον οξύθυμο χαρακτήρα του, τους χειρισμούς του και τα διαρκή εγωιστικά σχέδια πλουτισμού. Τα δηκτικά του σχόλια και η παντελής έλλειψη τακτ τον κάνουν τον πιο σκανδαλώδη ήρωα της σειράς.","fact":"Οι δημιουργοί της σειράς, Τρέι Πάρκερ και Ματ Στόουν, δίνουν οι ίδιοι φωνή στον Κάρτμαν και στους περισσότερους ήρωες.","wiki_en":"Eric Cartman"},{"name":"Ρικ Σάντσεζ","emoji":"🥼","meta":["«Rick and Morty»","τρελός επιστήμονας","2013"],"description":"Κυνικός και ιδιοφυής εφευρέτης, που ταξιδεύει σε παράλληλα σύμπαντα μαζί με τον εγγονό του Μόρτι σε ένα διαστημόπλοιο που έφτιαξε μόνος του. Ο αλκοολισμός, το μαύρο χιούμορ και η περιφρόνησή του για κάθε κανόνα δεν τον εμποδίζουν να είναι το ευφυέστερο ον του πολυσύμπαντος.","fact":"Το όνομα και ο χαρακτήρας του παρωδούν εν μέρει τον δόκτορα Έμετ Μπράουν από την «Επιστροφή στο Μέλλον».","wiki_en":"Rick Sanchez (Rick and Morty)"},{"name":"Μπέντερ","emoji":"🤖","meta":["«Futurama»","ρομπότ απατεώνας","1999"],"description":"Κυνικό ανθρωποειδές ρομπότ του 30ού αιώνα, φτιαγμένο για να λυγίζει μεταλλικές δοκούς και να ονειρεύεται δόξα και εύκολο χρήμα. Η αγάπη του για τα πούρα, την μπίρα και τις μικροαπάτες συνυπάρχει με μια απρόσμενη αφοσίωση στους φίλους του, τον Φράι και τη Λίλα.","fact":"Το πλήρες όνομά του είναι Μπέντερ Μπέντινγκ Ροδρίγκεζ, ενώ ο σειριακός του αριθμός επανέρχεται συχνά στα αστεία της σειράς.","wiki_en":"Bender (Futurama)"},{"name":"Μπομπ Σφουγγαράκης","emoji":"🧽","meta":["«Μπομπ Σφουγγαράκης»","ακατάβλητο σφουγγάρι μάγειρας","1999"],"description":"Ακατάβλητα χαρούμενο θαλάσσιο σφουγγάρι, που δουλεύει μάγειρας στο σνακ μπαρ «Κρίστι Κραμπ» στον βυθό του Ειρηνικού και αγαπά τη δουλειά του πάνω απ' όλα. Η παιδική του αφέλεια συγκρούεται διαρκώς με τον στρυφνό γείτονά του Σκουίντγουορντ και τον κολλητό του Πάτρικ.","fact":"Ο δημιουργός της σειράς, Στίβεν Χίλενμπεργκ, ήταν θαλάσσιος βιολόγος και σχεδιαστής κινουμένων πριν την ξεκινήσει.","wiki_en":"SpongeBob SquarePants (character)"},{"name":"Πάτρικ Στάρ","emoji":"⭐","meta":["«Μπομπ Σφουγγαράκης»","αγαθός αστερίας","1999"],"description":"Ρόδινος αστερίας που ζει κάτω από μια πέτρα στον βυθό του ωκεανού και είναι ο κολλητός του Μπομπ Σφουγγαράκη. Η απίστευτη βλακεία του και η παράξενη λογική του οδηγούν τακτικά τους δύο φίλους σε γελοίες αλλά ξεκαρδιστικές περιπέτειες.","fact":"Παρά τη διαρκή επίδειξη βλακείας, σε μεμονωμένα επεισόδια ο Πάτρικ δείχνει απρόσμενα ψήγματα ευφυΐας.","wiki_en":"Patrick Star"},{"name":"Σρεκ","emoji":"👹","meta":["«Σρεκ»","καλόκαρδος ογκρ","2001"],"description":"Γκρινιάρης πράσινος ογκρ, που δεν θέλει τίποτε άλλο από τη μοναξιά του στον βάλτο του και μπλέκει στη διάσωση μιας πριγκίπισσας για να ξανακερδίσει την ησυχία του. Παρωδώντας τα κλισέ των παραμυθιών, η ιστορία του έγινε ένα από τα πιο εισπρακτικά φραντσάιζ κινουμένων σχεδίων.","fact":"Ο ήρωας βασίζεται σε ένα παιδικό εικονογραφημένο βιβλίο του Γουίλιαμ Στάιγκ, αλλά οι δημιουργοί του στούντιο τον άλλαξαν πολύ.","wiki_en":"Shrek (character)"},{"name":"Γάιδαρος","emoji":"🫏","meta":["«Σρεκ»","ο πολυλογάς σύντροφος του ογκρ","2001"],"description":"Ακούραστος ομιλών γάιδαρος, που δεν σωπαίνει ούτε δευτερόλεπτο και επιβάλλεται στον Σρεκ ως κολλητός του παρά τη θέλησή του. Η ατελείωτη φλυαρία και η καλόκαρδη αφέλειά του γίνονται με τον καιρό αληθινό στήριγμα για τον σκληροτράχηλο ογκρ.","fact":"Τη φωνή του Γάιδαρου έδωσε ο κωμικός Έντι Μέρφι, του οποίου οι αυτοσχεδιασμοί διαμόρφωσαν σε μεγάλο βαθμό τον ήρωα.","wiki_en":"Donkey (Shrek)"},{"name":"Ο Παπουτσωμένος Γάτος","emoji":"🐈","meta":["«Σρεκ»","τολμηρός γάτος μισθοφόρος","2004"],"description":"Γοητευτικός σπαθομάχος γάτος με μπότες και καπέλο με φτερό, που στέλνεται αρχικά να σκοτώσει τον Σρεκ και καταλήγει πιστός σύντροφός του. Το περίφημο κόλπο με το δακρυσμένο βλέμμα των τεράστιων λυπημένων ματιών έγινε από τις πιο αναγνωρίσιμες σκηνές του φραντσάιζ.","fact":"Ο ήρωας εμπνέεται από το κλασικό ευρωπαϊκό παραμύθι, αλλά ο Αντόνιο Μπαντέρας του έδωσε φωνή Ισπανού τυχοδιώκτη.","wiki_en":"Puss in Boots (Shrek)"},{"name":"Μπαζ Λάιτγιαρ","emoji":"🚀","meta":["«Toy Story»","παιχνίδι διαστημικός φύλακας","1995"],"description":"Παιχνίδι διαστημικού φύλακα με ανοιγόμενα φτερά και λέιζερ, που πιστεύει ειλικρινά ότι είναι αληθινός ήρωας και όχι εμπόρευμα από ράφι καταστήματος. Ο ανταγωνισμός και μετά η φιλία του με τον καουμπόι Γούντι στηρίζουν την πλοκή της πρώτης ταινίας μεγάλου μήκους της Pixar.","fact":"Η ατάκα του Μπαζ «Στο άπειρο και ακόμη πιο πέρα!» έγινε ένα από τα πιο αναγνωρίσιμα σλόγκαν της Pixar.","wiki_en":"Buzz Lightyear"},{"name":"Σερίφης Γούντι","emoji":"🤠","meta":["«Toy Story»","παιχνίδι καουμπόι","1995"],"description":"Πάνινος καουμπόι με κορδόνι στην πλάτη, που για χρόνια ήταν το αγαπημένο παιχνίδι του μικρού Άντι, ώσπου εμφανίστηκε ο Μπαζ Λάιτγιαρ. Η αγωνία του μήπως χάσει την αγάπη του αφεντικού του και η φροντίδα για τους φίλους του είναι το συναισθηματικό κέντρο του φραντσάιζ.","fact":"Τη φωνή του Γούντι σε όλες τις ταινίες της σειράς δίνει ο ηθοποιός Τομ Χανκς.","wiki_en":"Woody (Toy Story)"},{"name":"Λάιτνινγκ ΜακΚουίν","emoji":"🏎️","meta":["«Αυτοκίνητα»","ξιπασμένο αγωνιστικό αυτοκίνητο","2006"],"description":"Νεαρό και ξιπασμένο αγωνιστικό αυτοκίνητο, που ονειρεύεται το κύπελλο του πρωταθλητή αλλά μένει κολλημένο σε μια υπνηλή κωμόπολη στην άκρη του δρόμου, το Ρέιντιεϊτορ Σπρινγκς. Η γνωριμία με τους παράξενους κατοίκους της του μαθαίνει να εκτιμά τη φιλία πάνω από την προσωπική δόξα.","fact":"Ο αριθμός 95 στο πλευρό του είναι νεύμα στο 1995, τη χρονιά που βγήκε η πρώτη ταινία μεγάλου μήκους της Pixar.","wiki_en":"Lightning McQueen"},{"name":"WALL-E","emoji":"🤖","meta":["«WALL-E»","μοναχικό ρομπότ καθαριστής","2008"],"description":"Μικρό ρομπότ που επί αιώνες καθαρίζει μόνο του τα σκουπίδια σε μια ερημωμένη Γη και συλλέγει τα αστεία ανθρώπινα ευρήματά του. Η συνάντηση με ένα γυαλιστερό ρομπότ ανίχνευσης, την EVE, αλλάζει την ήσυχη ζωή του και τη μοίρα όλης της ανθρωπότητας.","fact":"Σχεδόν το μισό της ταινίας κυλά χωρίς ούτε μία ανθρώπινη φράση.","wiki_en":"WALL-E"},{"name":"Πο","emoji":"🐼","meta":["«Kung Fu Panda»","αδέξιο πάντα πολεμιστής","2008"],"description":"Παχουλό και αδέξιο πάντα, που δουλεύει στο μαγαζί με τα νουντλς του πατέρα του αλλά ονειρεύεται κουνγκ φου, και ξαφνικά επιλέγεται ως ο θρυλικός Πολεμιστής Δράκος. Παρά τα πειράγματα των δασκάλων, το πείσμα και η καλοσύνη του τον κάνουν αληθινό ήρωα της κοιλάδας.","fact":"Τη φωνή του Πο στην αρχική εκδοχή έδωσε ο ηθοποιός Τζακ Μπλακ.","wiki_en":"Po (Kung Fu Panda)"},{"name":"Μίνιονς","emoji":"🍌","meta":["«Εγώ, ο Απαισιότατος»","κίτρινα πλασματάκια βοηθοί","2010"],"description":"Μικρά κίτρινα πλασματάκια σε σχήμα κάψουλας, που επί χιλιετίες υπηρετούν τους πιο διάφορους κακούς και αγαπούν τις μπανάνες πάνω απ' όλα. Η ακατάληπτη γλώσσα τους και η χαοτική αφοσίωση στο αφεντικό τους τα έκαναν από τα πιο αναγνωρίσιμα πλάσματα του σύγχρονου κινουμένου σχεδίου.","fact":"Η ομιλία των Μίνιονς είναι μείγμα αληθινών γλωσσών και επινοημένων ασυναρτησιών, που ηχογράφησαν οι ίδιοι οι σκηνοθέτες.","wiki_en":"Minions (Despicable Me)"},{"name":"Πίκατσου","emoji":"⚡","meta":["«Pokémon»","ηλεκτρικό Pokémon-μασκότ","1996"],"description":"Κίτρινο πλάσμα που μοιάζει με ποντίκι και χτυπά τους αντιπάλους του με εκκενώσεις ηλεκτρισμού, το επίσημο πρόσωπο όλου του φραντσάιζ Pokémon. Πιστός σύντροφος του εκπαιδευτή Ας Κέτσαμ, αρνείται να εξελιχθεί για να παραμείνει ο εαυτός του.","fact":"Το όνομα Πίκατσου προέρχεται από ιαπωνικές ηχομιμητικές λέξεις για το τσίριγμα του ποντικιού και τη σπίθα του ηλεκτρισμού.","wiki_en":"Pikachu"},{"name":"Μάριο","emoji":"🍄","meta":["Nintendo","μουστακαλής υδραυλικός ήρωας","1981"],"description":"Κοντός μουστακαλής Ιταλός υδραυλικός με κόκκινο σκουφάκι, που σώζει ξανά και ξανά την πριγκίπισσα Πιτς από τα νύχια του δράκου Μπάουζερ. Τα άλματα, τα μανιτάρια δύναμης και τα νομίσματά του έγιναν η βάση της πιο εμπορικής σειράς βιντεοπαιχνιδιών στην ιστορία.","fact":"Αρχικά ο ήρωας λεγόταν απλώς Jumpman και πήρε το όνομα Μάριο από τον ιδιοκτήτη του γραφείου της Nintendo στην Αμερική.","wiki_en":"Mario"},{"name":"Σόνικ","emoji":"💙","meta":["Sega","γαλάζιος σκαντζόχοιρος δρομέας","1991"],"description":"Έντονα γαλάζιος σκαντζόχοιρος με υπερηχητική ταχύτητα, που μαζεύει χρυσά δαχτυλίδια και αντιστέκεται στην κακή ιδιοφυΐα, τον δόκτορα Ρομπότνικ. Φτιαγμένος ως απάντηση της Sega στη δημοτικότητα του Μάριο, έγινε σύμβολο όλης της πλατφόρμας παιχνιδιών της εταιρείας.","fact":"Το ανυπόμονο χτύπημα του ποδιού έγινε η χαρακτηριστική κίνηση του Σόνικ όταν ο παίκτης τον αφήνει πολλή ώρα αδρανή.","wiki_en":"Sonic the Hedgehog (character)"},{"name":"Λάρα Κροφτ","emoji":"🏺","meta":["«Tomb Raider»","τολμηρή λεηλάτρια τάφων","1996"],"description":"Βρετανίδα αριστοκράτισσα και αρχαιολόγος, που εξερευνά αρχαίους τάφους και ναούς σε όλο τον κόσμο ψάχνοντας κειμήλια και επικίνδυνα μυστικά. Τα δύο πιστόλια και η αθλητική ευλυγισία της την έκαναν μία από τις πρώτες πραγματικά εμβληματικές ηρωίδες των βιντεοπαιχνιδιών.","fact":"Τα πρώτα μοντέλα του ήρωα φτιάχτηκαν με τους περιορισμούς των γραφικών της εποχής, και οι αναλογίες του σώματος προκάλεσαν διαφωνίες.","wiki_en":"Lara Croft"},{"name":"Γκέραλτ της Ρίβια","emoji":"⚔️","meta":["«The Witcher», Άντζεϊ Σαπκόφσκι","μεταλλαγμένος κυνηγός τεράτων","1986"],"description":"Επαγγελματίας εξολοθρευτής τεράτων, που πέρασε από μαγικές μεταλλάξεις για να αποκτήσει απάνθρωπη δύναμη, ταχύτητα και κάτασπρα μαλλιά. Η ηθική του αμφισημία και η ικανότητά του να βλέπει τις αποχρώσεις του γκρι τον κάνουν από τους πιο σύνθετους ήρωες του σύγχρονου φανταστικού.","fact":"Ο ήρωας πρωτοεμφανίστηκε σε διήγημα του Πολωνού συγγραφέα Άντζεϊ Σαπκόφσκι και όχι σε βιντεοπαιχνίδι.","wiki_en":"Geralt of Rivia"},{"name":"Ναρούτο Ουζουμάκι","emoji":"🍥","meta":["«Naruto»","νεαρός απόβλητος νίντζα","1999"],"description":"Φωνακλάς και πεισματάρης νεαρός νίντζα του χωριού Κόνοχα, που από τη γέννησή του κουβαλά σφραγισμένο μέσα του έναν πανίσχυρο δαίμονα αλεπού και ονειρεύεται να γίνει αρχηγός του χωριού. Το «ποτέ μην τα παρατάς» και η αφοσίωση στους φίλους του τον έκαναν αγαπημένο ήρωα του μάνγκα.","fact":"Το αγαπημένο του φαγητό, τα νουντλς ράμεν, έγινε με τον καιρό ανεπίσημο σύμβολο όλου του φραντσάιζ.","wiki_en":"Naruto Uzumaki"},{"name":"Σον Γκόκου","emoji":"🐒","meta":["«Dragon Ball»","εξωγήινος πολεμιστής με ουρά","1984"],"description":"Αγαθός και απίστευτα δυνατός μαχητής εξωγήινης καταγωγής, που από αφελές αγόρι με ουρά πιθήκου γίνεται υπερασπιστής όλης της Γης. Η ατέρμονη δίψα του να γίνει δυνατότερος και η αγάπη του για τις έντιμες μονομαχίες καθόρισαν ένα ολόκληρο είδος μάνγκα.","fact":"Ο ήρωας εμπνέεται σε μεγάλο βαθμό από τον βασιλιά των πιθήκων Σουν Γουκόνγκ του κλασικού κινεζικού μυθιστορήματος «Ταξίδι στη Δύση».","wiki_en":"Goku"},{"name":"Μόνκι Ντι Λούφι","emoji":"🏴‍☠️","meta":["«One Piece»","λαστιχένιος καπετάνιος πειρατών","1997"],"description":"Ακατάβλητα χαρούμενος καπετάνιος πειρατικού πληρώματος, που το σώμα του τεντώνεται σαν λάστιχο αφότου έφαγε κατά λάθος ένα Φρούτο του Διαβόλου. Το όνειρό του να βρει τον θρυλικό θησαυρό One Piece και να γίνει βασιλιάς των πειρατών κινεί ένα από τα πιο εμπορικά μάνγκα του κόσμου.","fact":"Το ψάθινο καπέλο του Λούφι είναι δώρο του πειρατή Σανκς, στον οποίο υποσχέθηκε πως κάποτε θα του το επιστρέψει.","wiki_en":"Monkey D. Luffy"},{"name":"Sailor Moon","emoji":"🌙","meta":["«Sailor Moon»","κορίτσι πολεμιστής με ναυτική στολή","1991"],"description":"Μια συνηθισμένη Γιαπωνέζα μαθήτρια, που μεταμορφώνεται σε ατρόμητη πολεμίστρια με ναυτική στολή για να προστατεύσει τη Γη από κακούς του διαστήματος. Μαζί με τις άλλες πολεμίστριες μάχεται με τη δύναμη της αγάπης και τη μαγεία της Σελήνης.","fact":"Οι σύντροφοί της πήραν τα ονόματά τους από τους πλανήτες του ηλιακού συστήματος, και από τον πλανήτη εξαρτώνται οι μαγικές τους δυνάμεις.","wiki_en":"Sailor Moon (character)"},{"name":"Τοτόρο","emoji":"🌳","meta":["Studio Ghibli","καλό πνεύμα του δάσους","1988"],"description":"Τεράστιο χνουδωτό πνεύμα του δάσους, κάτι ανάμεσα σε κουκουβάγια και γάτα, που το βλέπουν μόνο τα παιδιά που έτυχε να μετακομίσουν δίπλα στο δάσος του. Η σιωπηλή του καλοσύνη και η ομπρέλα κάτω από τη βροχή έγιναν εμβληματικές εικόνες του ιαπωνικού κινουμένου σχεδίου.","fact":"Η σιλουέτα του ήρωα έγινε το επίσημο λογότυπο του ίδιου του στούντιο Ghibli.","wiki_en":"My Neighbor Totoro"},{"name":"Hello Kitty","emoji":"🎀","meta":["Sanrio","λευκή γατούλα με φιόγκο","1974"],"description":"Λευκή ανθρωπόμορφη γατούλα με κόκκινο φιόγκο στο αυτί, που σχεδιάζεται πάντα χωρίς στόμα, ώστε ο καθένας να φαντάζεται μόνος του τη διάθεσή της. Δημιούργημα της ιαπωνικής εταιρείας Sanrio, έγινε από τους πιο αναγνωρίσιμους και εμπορικούς ήρωες της ποπ κουλτούρας.","fact":"Κατά την επίσημη βιογραφία της Sanrio, δεν είναι γάτα αλλά ένα μικρό αγγλικό κορίτσι που λέγεται Κίτι Γουάιτ.","wiki_en":"Hello Kitty"},{"name":"Γουόλτερ Γουάιτ","emoji":"🧪","meta":["«Breaking Bad»","καθηγητής χημείας που έγινε βαρόνος","2008"],"description":"Μετρημένος καθηγητής χημείας σε λύκειο, που μετά τη διάγνωση μιας θανατηφόρας αρρώστιας αρχίζει να παρασκευάζει υπερκαθαρή μεθαμφεταμίνη για να αφήσει χρήματα στην οικογένειά του. Η αργή μεταμόρφωσή του σε αδίστακτο αρχηγό αυτοκρατορίας ναρκωτικών είναι από τις πιο διαπεραστικές της τηλεόρασης.","fact":"Το ψευδώνυμό του στον κόσμο του εγκλήματος, Χάιζενμπεργκ, παραπέμπει στον περίφημο φυσικό της κβαντομηχανικής.","wiki_en":"Walter White (Breaking Bad)"},{"name":"Τζέσι Πίνκμαν","emoji":"💰","meta":["«Breaking Bad»","πρώην μαθητής και συνεργάτης","2008"],"description":"Ο αποτυχημένος πρώην μαθητής του Γουόλτερ Γουάιτ, που ο δάσκαλός του τον μπλέκει στην παρασκευή μεθαμφεταμίνης και ακολουθεί τη δική του οδυνηρή πορεία. Παρά την αργκό και τα αφελή λάθη του, αυτός κρατά τα υπολείμματα συνείδησης καθώς ο συνεργάτης του βυθίζεται.","fact":"Στον αρχικό σχεδιασμό ο ήρωας θα έφευγε από την πλοκή μέσα στην πρώτη σεζόν, αλλά η ερμηνεία του Άαρον Πολ άλλαξε τα σχέδια.","wiki_en":"Jesse Pinkman"},{"name":"Τίριον Λάνιστερ","emoji":"🍷","meta":["«Game of Thrones»","ο ευφυολόγος νάνος των Λάνιστερ","1996"],"description":"Κυνικός και εξαιρετικά διαβασμένος γόνος του πανίσχυρου οίκου των Λάνιστερ, που όλη του τη ζωή παλεύει με την περιφρόνηση των δικών του για το ύψος του. Το κοφτερό μυαλό του και η ικανότητά του να βρίσκει διέξοδο σε αδιέξοδα τον έκαναν αγαπημένο ήρωα της σάγκα.","fact":"Ο ήρωας φημίζεται για την αγάπη του στο κρασί, ενώ ο Πίτερ Ντίνκλεϊτζ κέρδισε για τον ρόλο αρκετά βραβεία Emmy.","wiki_en":"Tyrion Lannister"},{"name":"Τζον Σνόου","emoji":"🐺","meta":["«Game of Thrones»","νόθος διοικητής της Νυχτερινής Φρουράς","1996"],"description":"Νόθος γιος του άρχοντα του Βορρά, που υπηρετεί στη Νυχτερινή Φρουρά στην άκρη του γνωστού κόσμου και αντιμετωπίζει την απειλή πέρα από το Τείχος. Το αυστηρό αίσθημα του καθήκοντος και η αντιφατική μοίρα του τον έκαναν κεντρικό ήρωα της σάγκα.","fact":"Η φράση «Δεν ξέρεις τίποτα, Τζον Σνόου» είναι από τις πιο πολυθρύλητες όλου του φραντσάιζ.","wiki_en":"Jon Snow (character)"},{"name":"Ντενέρις Ταργκάριεν","emoji":"🐉","meta":["«Game of Thrones»","εξόριστη πριγκίπισσα των δράκων","1996"],"description":"Η τελευταία μιας έκπτωτης βασιλικής δυναστείας, που μεγάλωσε στην εξορία και αποκτά εξουσία πάνω σε τρεις δράκους. Η πορεία της από ανήμπορο κορίτσι σε ισχυρή ηγεμόνα, αποφασισμένη να πάρει πίσω τον θρόνο των προγόνων της, είναι κεντρικός άξονας της σάγκα.","fact":"Οι τρεις δράκοι της εκκολάφθηκαν από απολιθωμένα αυγά, που για καιρό θεωρούνταν απλώς αρχαίο κειμήλιο.","wiki_en":"Daenerys Targaryen"},{"name":"Σέλντον Κούπερ","emoji":"🧮","meta":["«The Big Bang Theory»","εκκεντρική ιδιοφυΐα της φυσικής","2007"],"description":"Λαμπρός αλλά κοινωνικά αδέξιος θεωρητικός φυσικός, που ζει με αυστηρό πρόγραμμα και δικούς του ακλόνητους κανόνες συμπεριφοράς. Η αδυναμία του να πιάσει τον σαρκασμό, το πάθος του για τα κόμικς και η προσωπική του θέση στον καναπέ γεννούν τα περισσότερα αστεία της σειράς.","fact":"Το χαρακτηριστικό του τελετουργικό είναι να χτυπά τρεις φορές την πόρτα λέγοντας κάθε φορά το όνομα εκείνου που ζητά.","wiki_en":"Sheldon Cooper"},{"name":"Δόκτωρ Γκρέγκορι Χάουζ","emoji":"🦯","meta":["«House»","κυνικός γιατρός διαγνώστης","2004"],"description":"Ιδιοφυής αλλά ανυπόφορα κυνικός διαγνώστης, που κουτσαίνει από παλιό τραύμα στο πόδι και προτιμά τη βάναυση ειλικρίνεια από το ευγενικό ψέμα. Οι ανορθόδοξες μέθοδοί του και η περίφημη φράση ότι όλοι λένε ψέματα έκαναν τη σειρά εμβληματικό ιατρικό δράμα.","fact":"Ο ήρωας σχεδιάστηκε σε μεγάλο βαθμό ως ένας σύγχρονος Σέρλοκ Χολμς, μεταφερμένος σε νοσοκομείο.","wiki_en":"Gregory House"},{"name":"Μάικλ Σκοτ","emoji":"🗂️","meta":["«The Office» (ΗΠΑ)","αμήχανος διευθυντής υποκαταστήματος","2005"],"description":"Διευθυντής ενός ξεχασμένου υποκαταστήματος εταιρείας χαρτιού, που πασχίζει απεγνωσμένα να είναι φίλος με όλους τους υπαλλήλους και τα κάνει διαρκώς θάλασσα. Τα άστοχα αστεία και η αφελής ανάγκη του να τον αγαπούν τον κάνουν τον πιο αμήχανο και συνάμα πιο συγκινητικό αφεντικό της τηλεόρασης.","fact":"Ο ήρωας βασίζεται στη βρετανική εκδοχή της σειράς, όπου τον αντίστοιχο διευθυντή έπαιζε ο Ρίκι Τζερβέις.","wiki_en":"Michael Scott (The Office)"},{"name":"Τζόι Τριμπιάνι","emoji":"🍕","meta":["«Friends»","αγαθός και ωραίος ηθοποιός","1994"],"description":"Γοητευτικός αλλά όχι ιδιαίτερα οξυδερκής ηθοποιός της Νέας Υόρκης, έτοιμος για τα πάντα για έναν ρόλο και κατηγορηματικά ανίκανος να μοιραστεί το φαγητό του. Η ατάκα του για το φλερτ και η συγκινητική αφοσίωση στους φίλους του τον έκαναν αγαπημένο ήρωα της σειράς.","fact":"Μετά το φινάλε των «Friends» γυρίστηκε ξεχωριστή σειρά για τον ήρωα, το «Joey», που κράτησε δύο σεζόν.","wiki_en":"Joey Tribbiani"},{"name":"Ντέξτερ Μόργκαν","emoji":"🔪","meta":["«Dexter»","κατά συρροή δολοφόνος και ιατροδικαστής","2006"],"description":"Αναλυτής αίματος στην αστυνομία του Μαϊάμι, που κάτω από τους καλούς τρόπους κρύβει προσεκτικά ελεγχόμενες δολοφονικές τάσεις. Ακολουθώντας τον αυστηρό «κώδικα» του θετού πατέρα του, σκοτώνει μόνο άλλους δολοφόνους που ξέφυγαν από τη δικαιοσύνη, ισορροπώντας σε δύο ζωές.","fact":"Ο ήρωας πρωτοεμφανίστηκε σε σειρά βιβλίων του συγγραφέα Τζεφ Λίντσεϊ και δεν επινοήθηκε για την τηλεόραση.","wiki_en":"Dexter Morgan"},{"name":"Τόμας Σέλμπι","emoji":"🎩","meta":["«Peaky Blinders»","αρχηγός συμμορίας του Μπέρμιγχαμ","2013"],"description":"Χαρισματικός και ψύχραιμος υπολογιστής, αρχηγός της εγκληματικής οικογένειας Σέλμπι, που πέρασε από τα χαρακώματα του Α΄ Παγκοσμίου Πολέμου και μετέτρεψε μια συμμορία του δρόμου σε αληθινή αυτοκρατορία. Τα χαρακτηριστικά τουίντ κασκέτα της συμμορίας έδωσαν το όνομα σε όλο το φραντσάιζ.","fact":"Τον ρόλο έπαιξε ο Κίλιαν Μέρφι, ενώ συμμορία με αυτό το παρατσούκλι υπήρξε πραγματικά στο Μπέρμιγχαμ γύρω στο 1900.","wiki_en":"Thomas Shelby"},{"name":"Eleven","emoji":"🧇","meta":["«Stranger Things»","κορίτσι με τηλεκίνηση","2016"],"description":"Μυστηριώδες κορίτσι με ξυρισμένο κεφάλι και έναν αριθμό στον καρπό, που ξέφυγε από μυστικό εργαστήριο και διαθέτει ισχυρές τηλεκινητικές ικανότητες. Η φιλία της με μια παρέα εφήβων στην κωμόπολη Χόκινς και η αγάπη της για τις βάφλες είναι το κέντρο της σειράς.","fact":"Τον ρόλο έπαιξε η νεαρή ηθοποιός Μίλι Μπόμπι Μπράουν, που για αυτόν ξύρισε εντελώς το κεφάλι της.","wiki_en":"Eleven (Stranger Things)"},{"name":"Γουένσντεϊ Άνταμς","emoji":"🖤","meta":["«Η Οικογένεια Άνταμς»","σκυθρωπό γοτθικό κορίτσι","1938"],"description":"Το χλωμό και ατάραχο κορίτσι μιας οικογένειας που λατρεύει καθετί μακάβριο, και αντιμετωπίζει τα βασανιστήρια και τις κηδείες ως συνηθισμένη διασκέδαση. Ο παγερός σαρκασμός και το εντελώς ανέκφραστο πρόσωπό της την έκαναν εμβληματική γοτθική ηρωίδα της ποπ κουλτούρας.","fact":"Πρωτοεμφανίστηκε στα σκίτσα του Τσαρλς Άνταμς σε εφημερίδες, όπου αρχικά δεν είχε καν όνομα.","wiki_en":"Wednesday Addams"},{"name":"Μίστερ Μπιν","emoji":"🧸","meta":["«Mr. Bean»","αδέξιος σιωπηλός παράξενος","1990"],"description":"Παράλογος και σχεδόν πάντα σιωπηλός τύπος, που μπλέκει διαρκώς σε κωμικές καταστάσεις εξαιτίας της αδεξιότητας και της παράξενης λογικής του. Πιστός σύντροφός του είναι ένα λούτρινο αρκουδάκι, ο Τέντι, ενώ το κιτρινάκι αυτοκίνητό του συμπληρώνει την εικόνα.","fact":"Ο Ρόουαν Άτκινσον έπλασε τον ήρωα έτσι ώστε τα αστεία να λειτουργούν σε κάθε χώρα χωρίς μετάφραση.","wiki_en":"Mr. Bean"},{"name":"Μπάρμπι","emoji":"👱‍♀️","meta":["Mattel","κούκλα-είδωλο της μόδας","1959"],"description":"Λεπτή κούκλα με άψογη γκαρνταρόμπα και δεκάδες επαγγέλματα, από αστροναύτης μέχρι πρόεδρος, δημιούργημα της αμερικανικής εταιρείας Mattel. Μέσα στις δεκαετίες έγινε το πιο εμπορικό παιχνίδι του κόσμου, αλλά και αντικείμενο διαμάχης για τα πρότυπα γυναικείας ομορφιάς.","fact":"Κατά τη μυθολογία της μάρκας, το πλήρες όνομα της κούκλας είναι Μπάρμπαρα Μίλισεντ Ρόμπερτς.","wiki_en":"Barbie"},{"name":"Optimus Prime","emoji":"🚛","meta":["«Transformers»","αρχηγός των ρομπότ Autobots","1984"],"description":"Ο ευγενής αρχηγός των Autobots, μιας φυλής ρομπότ που μετατρέπονται σε οχήματα, και εμφανίζεται συνήθως ως ένα μπλε φορτηγό. Ο πολυετής πόλεμός του με τον κακό Megatron και τους Decepticons έγινε η βάση ενός από τα πιο μακρόβια φραντσάιζ παιχνιδιών.","fact":"Η κλασική φωνή του ήρωα στη σειρά κινουμένων και στις πρώτες ταινίες ανήκε στον ηθοποιό Πίτερ Κάλεν.","wiki_en":"Optimus Prime"},{"name":"Χελωνονιντζάκια","emoji":"🐢","meta":["TMNT","μεταλλαγμένοι πολεμιστές των τεχνών","1984"],"description":"Τέσσερις ανθρωπόμορφες μεταλλαγμένες χελώνες, εκπαιδευμένες στις πολεμικές τέχνες από έναν σοφό ποντικό δάσκαλο, που ζουν στους υπονόμους της Νέας Υόρκης. Με ονόματα ζωγράφων της Αναγέννησης, πολεμούν το έγκλημα λατρεύοντας παράλληλα την απλή πίτσα.","fact":"Πρωτοεμφανίστηκαν σε ένα ανεξάρτητο ασπρόμαυρο κόμικ, που είχε συλληφθεί ως παρωδία άλλων ομάδων υπερηρώων.","wiki_en":"Teenage Mutant Ninja Turtles"},{"name":"Τσεμπουράσκα","emoji":"🧸","meta":["Εντουάρντ Ουσπένσκι","ζωάκι άγνωστο στην επιστήμη","1966"],"description":"Παράξενο πλάσμα με μεγάλα αυτιά, είδους άγνωστου στην επιστήμη, που βρέθηκε μέσα σε ένα κασόνι με πορτοκάλια και εγκαταστάθηκε σε έναν τηλεφωνικό θάλαμο. Η φιλία του με τον κροκόδειλο Γκένα και το Σπίτι της Φιλίας που φτιάχνουν αγαπήθηκαν από γενιές παιδιών.","fact":"Το όνομά του βγαίνει από ένα ρωσικό ρήμα για την τούμπα: το πλάσμα έπεφτε συνεχώς από αδεξιότητα.","wiki_en":"Cheburashka"},{"name":"Γκένα ο Κροκόδειλος","emoji":"🐊","meta":["Εντουάρντ Ουσπένσκι","κροκόδειλος που δουλεύει στον ζωολογικό","1966"],"description":"Ευγενικός κροκόδειλος, που έπιασε δουλειά στον ζωολογικό κήπο ως κροκόδειλος και τα βράδια παίζει ακορντεόν από μοναξιά. Η αγγελία του για εύρεση φίλων είναι αυτή που τον φέρνει στην Τσεμπουράσκα και ξεκινά τη μακρόχρονη φιλία τους.","fact":"Το τραγούδι του Γκένα, ότι τα γενέθλια έρχονται μόνο μια φορά τον χρόνο, είναι από τις πιο γνωστές μελωδίες του σοβιετικού κινουμένου σχεδίου.","wiki_en":"Gena the Crocodile"},{"name":"Ο Λύκος από το «Nu, Pogodi!»","emoji":"🚬","meta":["«Nu, Pogodi!»","άτυχος αλήτης λύκος","1969"],"description":"Αλητάκος λύκος με ριγέ ναυτική φανέλα, που κυνηγά ατέρμονα και πάντα ανεπιτυχώς έναν γρήγορο και πανούργο λαγό. Χωρίς σχεδόν καθόλου διάλογο, η σειρά έγινε ένα από τα πιο γνωστά κλασικά έργα του σοβιετικού κινουμένου σχεδίου.","fact":"Η ατάκα του «Λαγέ, κάτσε να σε πιάσω!» ακούγεται σχεδόν σε κάθε επεισόδιο και έδωσε τον τίτλο σε όλη τη σειρά.","wiki_en":"Nu, Pogodi!"},{"name":"Ο γάτος Ματρόσκιν","emoji":"🐄","meta":["Εντουάρντ Ουσπένσκι","νοικοκύρης γάτος του χωριού","1974"],"description":"Λογικός και πρακτικός γάτος που μιλά, ο οποίος εγκαθίσταται στο χωριό Προστοκβάσινο μαζί με ένα αγόρι, τον θείο Φιόντορ, και τους γονείς του. Η νοικοκυροσύνη του, η αγάπη του για την αγελάδα Μούρκα και η περίφημη ατάκα του για την κοινή δουλειά τον έκαναν αγαπημένο ήρωα.","fact":"Στις ταινίες για το Προστοκβάσινο τη φωνή του Ματρόσκιν δίνει ο ηθοποιός Ολέγκ Ταμπακόφ.","wiki_en":"Three from Prostokvashino"},{"name":"Ο Ανήξερος","emoji":"🎩","meta":["Νικολάι Νόσοφ","καυχησιάρης κοντούλης","1954"],"description":"Άτυχος και καυχησιάρης κοντούλης από την Ανθούπολη, που πιάνει διαρκώς δουλειές για τις οποίες δεν ξέρει απολύτως τίποτα. Οι πολλές αποτυχίες και περιπέτειές του στην τριλογία του Νικολάι Νόσοφ διδάσκουν τους μικρούς αναγνώστες μέσα από τα λάθη του ήρωα.","fact":"Στο τελευταίο μέρος της τριλογίας οι κοντούληδες φεύγουν για το φεγγάρι και βρίσκονται σε έναν κόσμο χρήματος και κέρδους.","wiki_en":"Dunno"},{"name":"Μπουρατίνο","emoji":"🪵","meta":["Αλεξέι Τολστόι","ξύλινο αγόρι με μακριά μύτη","1936"],"description":"Σκανταλιάρικο ξύλινο αγόρι με μακριά μύτη, σκαλισμένο από τον γερο-λατερνατζή Πάπα Κάρλο μέσα από ένα κούτσουρο που μιλούσε. Το χρυσό κλειδάκι του και οι περιπέτειές του με τον γάτο Βασίλιο και την αλεπού Αλίκη έγιναν κλασικά της σοβιετικής παιδικής λογοτεχνίας.","fact":"Το βιβλίο του Αλεξέι Τολστόι είναι μια ρωσική επανεγγραφή του ιταλικού παραμυθιού του Πινόκιο.","wiki_en":"Buratino"},{"name":"Ο γιατρός Άιμπολιτ","emoji":"🩹","meta":["Κορνέι Τσουκόφσκι","καλός γιατρός των ζώων","1929"],"description":"Ο πιο καλόκαρδος γιατρός, που θεραπεύει ζώα από όλο τον κόσμο και ξεκινά για την Αφρική να σώσει άρρωστους ελέφαντες, ιπποπόταμους και τσακάλια. Η ετοιμότητά του να βοηθήσει οποιοδήποτε πλάσμα τον έκανε σύμβολο ανιδιοτελούς καλοσύνης στην παιδική λογοτεχνία.","fact":"Ως πρότυπο του καλού γιατρού θεωρείται γνωστός του Τσουκόφσκι, ο γιατρός Τσεμάχ Σαμπάντ από το Βίλνιους, που περιέθαλπε δωρεάν τους φτωχούς.","wiki_en":"Aybolit"},{"name":"Μπάμπα Γιάγκα","emoji":"🧙‍♀️","meta":["ρωσική λαϊκή παράδοση","μάγισσα του δάσους","πριν τον 18ο αιώνα"],"description":"Μυστηριώδης γερόντισσα μάγισσα, που ζει στα βάθη του δάσους σε μια καλύβα πάνω σε πόδια κότας και πετά μέσα σε ένα γουδί με μια σκούπα. Ανάλογα με το παραμύθι, άλλοτε βοηθά τον ήρωα με σοφή συμβουλή και άλλοτε γίνεται η βασική απειλή που πρέπει να ξεγελάσει.","fact":"Στα παραμύθια η καλύβα με τα πόδια κότας γυρίζει προς τον ήρωα μόνο αφού αυτός πει ένα ειδικό ξόρκι.","wiki_en":"Baba Yaga"},{"name":"Κοστσέι ο Αθάνατος","emoji":"🥚","meta":["ρωσική λαϊκή παράδοση","αθάνατος κακός μάγος","πριν τον 18ο αιώνα"],"description":"Κοκαλιάρης και μοχθηρός μάγος των ρωσικών παραμυθιών, που ο θάνατός του κρύβεται στη μύτη μιας βελόνας μέσα σε αυγό, μέσα σε πάπια, μέσα σε λαγό. Απαγωγέας βασιλοπούλων και αιώνιος αντίπαλος των ηρώων, συμβολίζει το κακό που δεν νικιέται με τον συνηθισμένο τρόπο.","fact":"Η παλιά ρωσική λέξη πίσω από το όνομά του σήμαινε τον αδύνατο, κοκαλιάρη άνθρωπο ή τον αιχμάλωτο.","wiki_en":"Koschei"},{"name":"Ίλια Μούρομετς","emoji":"🛡️","meta":["ρωσικά έπη","πολεμιστής υπερασπιστής της Ρωσίας","πριν τον 13ο αιώνα"],"description":"Ρωμαλέος γιος χωρικών, που έμεινε ακίνητος πάνω στο πέτρινο τζάκι τριάντα τρία χρόνια προτού αποκτήσει με θαυματουργό τρόπο δύναμη ήρωα. Κύριος υπερασπιστής του κράτους του Κιέβου στα ρωσικά έπη, παραμένει πρότυπο πολεμικής ανδρείας και δικαιοσύνης.","fact":"Ως πρότυπο του ήρωα των επών θεωρείται ένας πραγματικός μοναχός, ο Ίλια των Σπηλαίων, του οποίου τα λείψανα φυλάσσονται στη Λαύρα του Κιέβου.","wiki_en":"Ilya Muromets"},{"name":"Κολομπόκ","emoji":"🟡","meta":["ρωσικό παραμύθι","στρογγυλός φυγάς από ζύμη","πριν τον 19ο αιώνα"],"description":"Στρογγυλό ροδοκόκκινο ψωμάκι, που το έπλασε μια γερόντισσα από το τελευταίο της αλεύρι και έφυγε αμέσως από το περβάζι, αφήνοντας πίσω τον παππού και τη γιαγιά. Στον δρόμο ξεγλιστρά από τον λαγό, τον λύκο και την αρκούδα με ένα καυχησιάρικο τραγουδάκι, ώσπου το πιάνει η πονηρή αλεπού.","fact":"Ιστορίες για ένα φαγώσιμο πλάσμα που το σκάει υπάρχουν στη λαϊκή παράδοση πολλών λαών, όπως ο διάσημος αγγλικός ανθρωπάκος από μελόψωμο.","wiki_en":"Kolobok"},{"name":"Οστάπ Μπέντερ","emoji":"🕶️","meta":["Ιλφ και Πετρόφ","ο μεγάλος κομπιναδόρος","1928"],"description":"Γοητευτικός απατεώνας και μεγάλος κομπιναδόρος, που κατά τα λεγόμενά του ξέρει τετρακόσιους σχετικά έντιμους τρόπους να παίρνει τα λεφτά των άλλων. Το κυνήγι των διαμαντιών που κρύβονται σε μία από δώδεκα καρέκλες έγινε αγαπημένη σατιρική ιστορία της σοβιετικής λογοτεχνίας.","fact":"Πολλά από τα αποφθέγματα του ήρωα ζουν εδώ και δεκαετίες στα ρωσικά ως αυτοτελείς παροιμιώδεις φράσεις.","wiki_en":"Ostap Bender"},{"name":"Στίρλιτς","emoji":"🕵️","meta":["Γιούλιαν Σεμιόνοφ","σοβιετικός κατάσκοπος στο Ράιχ","1969"],"description":"Σοβιετικός μυστικός πράκτορας, που για χρόνια δρα στη ναζιστική Γερμανία με την ταυτότητα ανώτερου αξιωματικού των SS. Η ψυχραιμία του και η ικανότητά του να προβλέπει τις κινήσεις του αντιπάλου τον έκαναν τον πιο γνωστό κατάσκοπο της σοβιετικής κουλτούρας.","fact":"Ο ήρωας έγινε πρόσωπο σε αμέτρητα ανέκδοτα, που όλα παίζουν με το πόσο ατάραχος μένει σε κάθε περίπτωση.","wiki_en":"Stierlitz"},{"name":"Ντανίλα Μπαγκρόφ","emoji":"🎧","meta":["«Ο Αδελφός»","μοναχικός βετεράνος στην Πετρούπολη","1997"],"description":"Νέος άντρας που γυρίζει από τον στρατό και μπλέκει στους εγκληματικούς λογαριασμούς του μεγάλου αδελφού του, στην Πετρούπολη της δεκαετίας του 1990. Η λιγομίλητη φύση του, η δική του αντίληψη της δικαιοσύνης και το κασετόφωνο στην τσέπη τον έκαναν σύμβολο του μετασοβιετικού σινεμά.","fact":"Η ατάκα του για το πού βρίσκεται η αληθινή δύναμη έχει γίνει παροιμιώδης και ζει ανεξάρτητα από την ταινία.","wiki_en":"Brother (1997 film)"},{"name":"Σούρικ","emoji":"📸","meta":["κωμωδίες του Λεονίντ Γκαϊντάι","αφελής φοιτητής με γυαλιά","1965"],"description":"Μετρημένος και περίεργος φοιτητής με γυαλιά, που βρίσκεται σε αλλεπάλληλες κωμικές καταστάσεις, από μια ομάδα οικοδόμων μέχρι μια τυχαία γνωριμία με απαγωγείς νύφης. Η αφελής του ειλικρίνεια μέσα σε έναν κόσμο κατεργάρηδων έγινε σήμα κατατεθέν σοβιετικών κωμωδιών.","fact":"Ο ίδιος ηθοποιός, ο Αλεξάντρ Ντεμιανένκο, έπαιξε τον ήρωα με αυτό το όνομα σε αρκετές διαφορετικές ταινίες του Γκαϊντάι.","wiki_en":"Operation Y and Other Shurik's Adventures"},{"name":"Ο σύντροφος Σουχόφ","emoji":"🏜️","meta":["«Ο λευκός ήλιος της ερήμου»","στρατιώτης του Κόκκινου Στρατού στην έρημο","1970"],"description":"Αποστρατευμένος στρατιώτης του Κόκκινου Στρατού, που ονειρεύεται να γυρίσει στη γυναίκα του αλλά αναγκάζεται καθ' οδόν να προσέχει το χαρέμι ενός φυγάδα οπλαρχηγού. Η ήρεμη λογική του και τα γράμματα προς τη μακρινή Κατερίνα Ματβέγεβνα έγιναν από τις πιο πολυθρύλητες εικόνες του σοβιετικού σινεμά.","fact":"Οι Ρώσοι κοσμοναύτες παραδοσιακά βλέπουν την ταινία πριν από κάθε εκτόξευση, ως μέρος του τελετουργικού τους.","wiki_en":"White Sun of the Desert"},{"name":"Γκλεμπ Ζεγκλόφ","emoji":"🚔","meta":["«Ο τόπος συνάντησης δεν αλλάζει»","σκληρός αστυνομικός της Μόσχας","1979"],"description":"Ασυμβίβαστος αστυνομικός της Μόσχας στα μεταπολεμικά χρόνια, έτοιμος να προσπεράσει τις τυπικότητες του νόμου για να πιάσει τον εγκληματία. Η διαμάχη του με τον νέο συνεργάτη του για το αν ο σκοπός αγιάζει τα μέσα είναι το κεντρικό θέμα μιας θρυλικής τηλεοπτικής ταινίας.","fact":"Τον Ζεγκλόφ έπαιξε ο Βλαντίμιρ Βισότσκι, για τον οποίο ο ρόλος ήταν ένας από τους τελευταίους της ζωής του.","wiki_en":"The Meeting Place Cannot Be Changed"},{"name":"Ευγένιος Ονέγκιν","emoji":"🎭","meta":["Αλεξάντρ Πούσκιν","κορεσμένος δανδής της υψηλής κοινωνίας","1833"],"description":"Νέος αριστοκράτης απογοητευμένος από τη ζωή, που απορρίπτει την ειλικρινή αγάπη μιας επαρχιώτισσας, της Τατιάνας, για χάρη της παγερής κοσμικής πλήξης. Η εσωτερική του κενότητα και η καθυστερημένη μεταμέλειά του τον έκαναν πρότυπο του «περιττού ανθρώπου» της ρωσικής λογοτεχνίας.","fact":"Ο Πούσκιν δούλεψε το έμμετρο μυθιστόρημα πάνω από επτά χρόνια, αλλάζοντας σταδιακά τον αρχικό σχεδιασμό της πλοκής.","wiki_en":"Eugene Onegin"},{"name":"Ροντιόν Ρασκόλνικοφ","emoji":"🪓","meta":["Ντοστογιέφσκι","φοιτητής θεωρητικός και φονιάς","1866"],"description":"Φτωχός φοιτητής της Πετρούπολης, που αποφασίζει να σκοτώσει μια γριά τοκογλύφο για να δοκιμάσει τη δική του θεωρία περί δικαιώματος της ισχυρής προσωπικότητας. Τα βασανιστικά του εσωτερικά μαρτύρια μετά το έγκλημα είναι ο ψυχολογικός πυρήνας του μυθιστορήματος.","fact":"Η θεωρία του για τον διαχωρισμό των ανθρώπων σε «κοινούς» και σε όσους «έχουν δικαίωμα» τροφοδότησε αμέτρητες φιλοσοφικές διαμάχες.","wiki_en":"Rodion Raskolnikov"},{"name":"Άννα Καρένινα","emoji":"🚂","meta":["Λέων Τολστόι","κοσμική κυρία σε τραγικό έρωτα","1877"],"description":"Παντρεμένη αριστοκράτισσα της υψηλής κοινωνίας της Πετρούπολης, που ο παράφορος έρωτάς της για τον αξιωματικό Βρόνσκι τη φέρνει σε σύγκρουση με την οικογένεια και υπό την καταδίκη του κόσμου. Η τραγική της μοίρα είναι μία από τις πιο γνωστές μελέτες του έρωτα και της ηθικής.","fact":"Η περίφημη πρώτη φράση του μυθιστορήματος για τις ευτυχισμένες και τις δυστυχισμένες οικογένειες έχει γίνει αυτοτελές απόφθεγμα.","wiki_en":"Anna Karenina"},{"name":"Βόλαντ","emoji":"🐾","meta":["«Ο Μαιτρ και η Μαργαρίτα»","αινιγματικός διάβολος καθηγητής","1966"],"description":"Μυστηριώδης ξένος καθηγητής της μαύρης μαγείας, που φτάνει στη Μόσχα της δεκαετίας του 1930 με μια ακολουθία δαιμόνων για να αποδώσει τη δική του ιδιότυπη δικαιοσύνη. Η περίφημη φράση του ότι τα χειρόγραφα δεν καίγονται είναι από τις πιο γνωστές της ρωσικής λογοτεχνίας.","fact":"Το μυθιστόρημα του Μπουλγκάκοφ εκδόθηκε δεκαετίες μετά τον θάνατο του συγγραφέα, αρχικά σε πολύ περικομμένη μορφή.","wiki_en":"Woland"},{"name":"Ο γάτος Μπεγκεμότ","emoji":"🐱","meta":["«Ο Μαιτρ και η Μαργαρίτα»","δαίμονας γάτος που αλλάζει μορφή","1966"],"description":"Πελώριος μαύρος γάτος από την ακολουθία του Βόλαντ, που μπορεί να γίνεται ένας παχουλός άντρας και λατρεύει το σκάκι και τα θρασύτατα αστεία. Οι σκανδαλιές του στη σοβιετική Μόσχα, από τη βόλτα με το τραμ ως τις πιστολιές, είναι από τις πιο αξέχαστες σκηνές του βιβλίου.","fact":"Το όνομά του παραπέμπει στο βιβλικό τέρας Βεεμώθ, που αναφέρεται στο Βιβλίο του Ιώβ.","wiki_en":"Behemoth (The Master and Margarita)"},{"name":"Μάσα","emoji":"🐻","meta":["«Μάσα και Αρκούδος»","ασταμάτητη σκανταλιάρα","2009"],"description":"Ενεργητικό και ασταμάτητο κοριτσάκι, που εγκαθίσταται δίπλα σε έναν καλόκαρδο Αρκούδο του τσίρκου, κατάκοπο από τις σκανταλιές της. Η ατελείωτη ενέργειά της και η ικανότητά της να μετατρέπει κάθε κατάσταση σε χάος έκαναν τη ρωσική σειρά επιτυχία και εκτός συνόρων.","fact":"Μεμονωμένα επεισόδια μάζεψαν δισεκατομμύρια προβολές στο YouTube, ενώ η σειρά έχει μεταφραστεί σε δεκάδες γλώσσες.","wiki_en":"Masha and the Bear"},{"name":"Κρας","emoji":"🐰","meta":["«KikoRiki»","ενεργητικός λαγός που δεν κάθεται","2004"],"description":"Παρορμητικός στρογγυλός λαγός, πάντα βιαστικός κάπου, που προτιμά πολύ περισσότερο τον αθλητισμό και τα ριψοκίνδυνα σχέδια από τον ήρεμο στοχασμό. Είναι από τους βασικούς ήρωες μιας ρωσικής σειράς για στρογγυλά ζωάκια, σταθμό της ρωσικής κινούμενης εικόνας των δεκαετιών μετά το 2000.","fact":"Τα σχέδια όλων των ηρώων στηρίζονται στον κύκλο, ενώ ο ρωσικός τίτλος ενώνει τις λέξεις «αστεία» και «μπαλάκια».","wiki_en":"KikoRiki","wiki_ru":"Смешарики"},{"name":"Λούντικ","emoji":"🌕","meta":["«Λούντικ»","μικρό πλάσμα που έπεσε από τη Σελήνη","2006"],"description":"Χνουδωτό πλασματάκι, γεννημένο στη Σελήνη, που έπεσε κατά λάθος στη Γη, μέσα σε μια λιμνούλα του δάσους, όπου το βρίσκουν και το μεγαλώνουν έντομα. Η καλόκαρδη έκπληξή του για κάθε καινούργιο έκανε τη σειρά μία από τις πιο δημοφιλείς ρωσικές για μικρά παιδιά.","fact":"Το όνομά του βγαίνει κατευθείαν από τη ρωσική λέξη για τη Σελήνη, λούνα, από όπου και προέρχεται κατά την ιστορία.","wiki_en":"Luntik and His Friends","wiki_ru":"Лунтик и его друзья"},{"name":"Ο θείος Στιόπα","emoji":"📏","meta":["Σεργκέι Μιχαλκόφ","καλόκαρδος γίγαντας τροχονόμος","1935"],"description":"Απίστευτα ψηλός και καλόκαρδος γίγαντας από τα ποιήματα του Σεργκέι Μιχαλκόφ, που στις συνέχειες γίνεται τροχονόμος. Η ετοιμότητά του να βοηθήσει, από τη διάσωση πνιγμένων μέχρι την κατάσβεση πυρκαγιών, τον έκανε πρότυπο ήρωα της σοβιετικής παιδικής ποίησης.","fact":"Ο Μιχαλκόφ έγραφε για τον θείο Στιόπα σχεδόν μισό αιώνα, από το πρώτο ποίημα της δεκαετίας του 1930 ως ένα όψιμο για τον ήρωα βετεράνο.","wiki_en":"Uncle Styopa"},{"name":"Ο γέρο-Χοτάμπιτς","emoji":"🧞","meta":["Λαζάρ Λάγκιν","αρχαίο τζίνι μέσα σε σταμνί","1938"],"description":"Πανίσχυρο τζίνι, που πέρασε χιλιάδες χρόνια φυλακισμένο σε ένα πήλινο σταμνί και ελευθερώνεται από τον σοβιετικό μαθητή Βόλκα. Η παλιομοδίτικη ανατολίτικη ομιλία του και οι αφελείς προσπάθειές του να καταλάβει τη σοβιετική ζωή γεννούν αμέτρητες κωμικές σκηνές.","fact":"Το βιβλίο οφείλει πολλά σε ένα αγγλικό μυθιστόρημα για ένα τζίνι, με τη δράση μεταφερμένη στη σοβιετική Μόσχα.","wiki_en":"Old Man Hottabych"},{"name":"Ελεκτρόνικ","emoji":"🔌","meta":["Γιεβγκένι Βελτίστοφ","αγόρι-ρομπότ και σωσίας","1964"],"description":"Ρομπότ σε σχήμα αγοριού, φτιαγμένο από τη φωτογραφία του μαθητή Σεριόζα Συροέζκιν και απαράλλακτο από αυτόν, κάτι που επιτρέπει στους δύο να αλλάξουν θέσεις. Η φιλία του με τα παιδιά και η σταδιακή απόκτηση σχεδόν ανθρώπινων συναισθημάτων στηρίζουν ένα διάσημο σοβιετικό βιβλίο και φιλμ.","fact":"Το τραγούδι «Φτερωτές κούνιες» από την τηλεοπτική ταινία για τον ήρωα έγινε ένα από τα πιο γνωστά σοβιετικά παιδικά τραγούδια.","wiki_en":"The Adventures of Elektronik"},{"name":"Όμπι-Ουάν Κενόμπι","emoji":"🧙","meta":["«Πόλεμος των Άστρων»","μέντορας Τζεντάι","1977"],"description":"Δάσκαλος Τζεντάι, μέντορας πρώτα του Άνακιν Σκαϊγουόκερ και αργότερα του γιου του, του Λουκ. Σοφός και συγκρατημένος, προτιμά τη διαπραγμάτευση από τη μάχη, αλλά όταν χρειαστεί χειρίζεται αριστοτεχνικά το φωτόσπαθο. Από τους λίγους Τζεντάι που επέζησαν της πτώσης του Τάγματος.","fact":"Ο Άλεκ Γκίνες, που έπαιξε τον Όμπι-Ουάν στην αρχική τριλογία, αντιμετώπισε στην αρχή μάλλον ψυχρά τον ρόλο σε ταινία φαντασίας.","wiki_en":"Obi-Wan Kenobi"},{"name":"Αυτοκράτορας Παλπατίν","emoji":"⚡","meta":["«Πόλεμος των Άστρων»","σκοτεινός άρχοντας των Σιθ","1980"],"description":"Μυστικοπαθής πολιτικός, που για χρόνια ύφαινε τη συνωμοσία του πίσω από το προσωπείο του καγκελαρίου της Δημοκρατίας, ώσπου αυτοανακηρύχθηκε Αυτοκράτορας. Πανίσχυρος σκοτεινός άρχοντας των Σιθ, που εξαπολύει τους καταστροφικούς κεραυνούς της Δύναμης, ενσαρκώνει την πανουργία και την απόλυτη εξουσία.","fact":"Ο Αυτοκράτορας εμφανίστηκε στην οθόνη πρώτη φορά στην «Αυτοκρατορία αντεπιτίθεται», με ένα σύντομο ολογραφικό μήνυμα στον Νταρθ Βέιντερ.","wiki_en":"Palpatine"},{"name":"Μπόμπα Φετ","emoji":"🚀","meta":["«Πόλεμος των Άστρων»","κυνηγός επικηρυγμένων","1978"],"description":"Λιγομίλητος κυνηγός επικηρυγμένων με αναγνωρίσιμη πανοπλία, από τους πιο λατρεμένους δευτερεύοντες ήρωες της σάγκα. Δουλεύει για την Αυτοκρατορία και καταδιώκει τον Χαν Σόλο, αλλά είναι πιστός πρώτα στο δικό του συμφέρον. Η μυστηριακή αύρα του του χάρισε πολλά σπιν-οφ.","fact":"Ο Μπόμπα Φετ δεν πρωτοεμφανίστηκε στο σινεμά αλλά σε κινούμενο ένθετο του τηλεοπτικού «Star Wars Holiday Special» του 1978.","wiki_en":"Boba Fett"},{"name":"Νταρθ Μολ","emoji":"😈","meta":["«Πόλεμος των Άστρων»","πολεμιστής Σιθ","1999"],"description":"Κερασφόρος πολεμιστής των Σιθ με πολεμική βαφή στο πρόσωπο και διπλό φωτόσπαθο, σιωπηλός και θανατηφόρος. Μαθητής του Νταρθ Σίντιους, δρα ως το κρυφό ξίφος του δασκάλου του στη σκιά των πολιτικών ιντριγκών. Η σύντομη εμφάνισή του τον έκανε εμβληματικό κακό.","fact":"Ο Νταρθ Μολ είχε σχεδιαστεί ως περαστικός ήρωας, αλλά η αγάπη του κοινού ανάγκασε τους δημιουργούς να τον επαναφέρουν σε νέες ιστορίες.","wiki_en":"Darth Maul"},{"name":"Κάιλο Ρεν","emoji":"⚔️","meta":["«Πόλεμος των Άστρων»","ιππότης των Ρεν","2015"],"description":"Εσωτερικά διχασμένος ιππότης της σκοτεινής πλευράς της Δύναμης, που πασχίζει να αποδείξει την πίστη του στο νέο Τάγμα. Φοράει μάσκα και κρατά τροποποιημένο φωτόσπαθο με φυλακτήρα, και μάχεται οξύθυμα και παρορμητικά. Η μοίρα του δένεται στενά με την κληρονομιά των Σκαϊγουόκερ.","fact":"Το τρίξιμο και το ανώμαλο βουητό του φωτόσπαθου του Κάιλο Ρεν σχεδιάστηκαν ειδικά για να δείχνουν την αστάθεια του κρυστάλλου του.","wiki_en":"Kylo Ren"},{"name":"Ρέι Σκαϊγουόκερ","emoji":"🌵","meta":["«Πόλεμος των Άστρων»","Τζεντάι","2015"],"description":"Μοναχική συλλέκτρια παλιοσίδερων από τον ερημικό πλανήτη Τζάκου, μέσα στην οποία ξυπνά απρόσμενα ένα τεράστιο δυναμικό της Δύναμης. Μαθαίνει το φωτόσπαθο και τον δρόμο των Τζεντάι, ψάχνοντας τη θέση της στον γαλαξία και τη σύνδεσή της με το παρελθόν.","fact":"Προτού πιάσει φωτόσπαθο, η Ρέι χειρίζεται σε μεγάλο μέρος της ταινίας με δεξιοτεχνία ένα κοινό ραβδί.","wiki_en":"Rey (Star Wars)"},{"name":"Τζαρ Τζαρ Μπινκς","emoji":"🐸","meta":["«Πόλεμος των Άστρων»","Γκάνγκαν","1999"],"description":"Αδέξιος και φλύαρος κάτοικος της υποβρύχιας πόλης των Γκάνγκαν στον πλανήτη Νάμπου, που μπλέκει τυχαία σε μεγάλα πολιτικά γεγονότα. Η κωμική συμπεριφορά και η στραβή του ομιλία έρχονται σε κραυγαλέα αντίθεση με τον σοβαρό τόνο της υπόλοιπης σάγκα.","fact":"Ήταν από τους πρώτους εξ ολοκλήρου ψηφιακούς ήρωες με μεγάλο ρόλο σε ταινία με ζωντανούς ηθοποιούς· στα γυρίσματα τον έπαιζε ο Άχμεντ Μπεστ.","wiki_en":"Jar Jar Binks"},{"name":"Magneto","emoji":"🧲","meta":["«X-Men»","κυρίαρχος του μαγνητισμού","1963"],"description":"Ένας από τους ισχυρότερους μεταλλαγμένους της Marvel, που κυβερνά το μέταλλο με τη σκέψη του μόνο. Επιζών του Ολοκαυτώματος, έγινε πεπεισμένος αγωνιστής για τα δικαιώματα των μεταλλαγμένων, με μεθόδους που τον κάνουν ιδεολογικό αντίπαλο του Professor X παρά κλασικό κακό.","fact":"Το αληθινό όνομα του Magneto είναι Μαξ Άιζενχαρτ, αν και η βιογραφία του έχει ξαναγραφτεί πολλές φορές σε διαφορετικές εκδοχές.","wiki_en":"Magneto (Marvel Comics)"},{"name":"Professor X","emoji":"🧠","meta":["«X-Men»","τηλεπαθητικός μεταλλαγμένος","1963"],"description":"Ένας από τους ισχυρότερους τηλεπαθητικούς του πλανήτη, που χρησιμοποιεί το χάρισμά του όχι για εξουσία αλλά για την προστασία των μεταλλαγμένων και την ειρηνική συμβίωση με τους ανθρώπους. Ίδρυσε σχολή για χαρισματικά παιδιά, που έγινε το σπίτι των X-Men, και ηγείται από αναπηρικό αμαξίδιο.","fact":"Ο Professor X και ο Magneto συλλήφθηκαν ως δύο αντίπαλες φιλοσοφίες στον αγώνα για τα δικαιώματα των μειονοτήτων.","wiki_en":"Professor X"},{"name":"Mystique","emoji":"🔵","meta":["«X-Men»","μεταλλαγμένη που αλλάζει μορφή","1978"],"description":"Μεταλλαγμένη με γαλάζιο δέρμα, που μπορεί να παίρνει τη μορφή οποιουδήποτε ανθρώπου, κάτι που την κάνει ασυναγώνιστη κατάσκοπο και εκτελέστρια. Η πίστη της ταλαντεύεται διαρκώς ανάμεσα στον Magneto και στους δικούς της στόχους, και είναι από τις πιο απρόβλεπτες φιγούρες του σύμπαντος των X-Men.","fact":"Στις ταινίες οι ηθοποιοί περνούσαν ώρες στο μακιγιάζ για να αποκτήσουν το χαρακτηριστικό γαλάζιο, φολιδωτό δέρμα της Mystique.","wiki_en":"Mystique (Marvel Comics)"},{"name":"Doctor Doom","emoji":"🎭","meta":["«Fantastic Four»","επιστήμονας δικτάτορας","1962"],"description":"Ιδιοφυής επιστήμονας και μάγος, που έγινε απόλυτος ηγεμόνας της φανταστικής χώρας Λατβέρια. Ένα ατύχημα έκρυψε για πάντα το πρόσωπό του πίσω από μεταλλική μάσκα, και η υπεροψία του δεν τον αφήνει να παραδεχτεί την ανωτερότητα κανενός, ούτε στην επιστήμη ούτε στη μαγεία.","fact":"Ο Doctor Doom είναι τυπικά μονάρχης κυρίαρχου κράτους, κάτι που τον κάνει σπάνιο κακό των κόμικς με διπλωματική ασυλία.","wiki_en":"Doctor Doom"},{"name":"Doctor Strange","emoji":"🔮","meta":["Marvel","ύπατος μάγος της Γης","1963"],"description":"Λαμπρός αλλά αλαζονικός νευροχειρουργός, που μετά τον τραυματισμό των χεριών του ξεκίνησε να ψάχνει θεραπεία και βρήκε τη μαεστρία των μυστικιστικών τεχνών. Ως ύπατος μάγος υπερασπίζεται την πραγματικότητα από διαστασιακές απειλές με το Μάτι του Αγκαμότο και τον μανδύα της αιώρησης.","fact":"Ο σχεδιαστής Στιβ Ντίτκο πειραματίστηκε με ψυχεδελικά οπτικά εφέ, που έγιναν αργότερα η υπογραφή της μαγείας στα κόμικς.","wiki_en":"Doctor Strange"},{"name":"Ant-Man","emoji":"🐜","meta":["Marvel","ήρωας που αλλάζει μέγεθος","1962"],"description":"Υπερήρωας με ειδική στολή που φέρει τα σωματίδια Πιμ, χάρη στα οποία αλλάζει ακαριαία μέγεθος, από γιγάντιος έως μικροσκοπικός. Το όνομα το έχουν φορέσει διάφοροι ήρωες, όπως ο επιστήμονας Χανκ Πιμ και ο πρώην κλέφτης Σκοτ Λανγκ, ενώ ένα κράνος τον αφήνει να διοικεί στρατιές μυρμηγκιών.","fact":"Τα ίδια σωματίδια Πιμ λειτουργούν και αντίστροφα: στα κόμικς ο Χανκ Πιμ έδρασε με το όνομα Giant-Man.","wiki_en":"Ant-Man"},{"name":"Star-Lord","emoji":"🎧","meta":["Marvel","διαστημικός τυχοδιώκτης","1976"],"description":"Ο Πίτερ Κουίλ, γήινος που μεγάλωσε ανάμεσα σε διαστημικούς λαθρεμπόρους αφότου τον απήγαγαν παιδί από τη Γη. Ηγείται του ανομοιογενούς πληρώματος των «Φυλάκων του Γαλαξία», συνδυάζοντας την παλικαριά με γνήσια αφοσίωση στους νέους φίλους του, και δεν αποχωρίζεται ποτέ το παλιό του κασετόφωνο.","fact":"Το κασετόφωνο του Star-Lord με γήινες επιτυχίες γέννησε τα άλμπουμ «Awesome Mix», που έγιναν επιτυχίες και στην πραγματική ζωή.","wiki_en":"Star-Lord"},{"name":"Rocket Raccoon","emoji":"🦝","meta":["Marvel","ρακούν μισθοφόρος","1976"],"description":"Αποτέλεσμα σκληρών γενετικών πειραμάτων, που μετέτρεψαν ένα κοινό ρακούν σε κυνικό και οξύθυμο δεξιοτέχνη των όπλων και της τεχνολογίας. Παρά το μικρό του ύψος, είναι από τους πιο επικίνδυνους μαχητές των «Φυλάκων του Γαλαξία», και πίσω από την αγένειά του κρύβει βαθύ τραύμα.","fact":"Το όνομά του το υπαγόρευσε το τραγούδι «Rocky Raccoon» των The Beatles, που αγαπούσε ο δημιουργός του, ο σεναριογράφος Μπιλ Μάντλο.","wiki_en":"Rocket Raccoon"},{"name":"Venom","emoji":"🖤","meta":["Marvel","αντιήρωας συμβιωτής","1988"],"description":"Εξωγήινος συμβιωτής, που όταν ενώνεται με έναν ανθρώπινο ξενιστή του χαρίζει τεράστια δύναμη, αναγέννηση και ικανότητα να αλλάζει μορφή. Για καιρό εχθρός του Spider-Man, εξελίχθηκε σε πιο σύνθετο αντιήρωα με δικούς του κανόνες. Το μαύρο κολλώδες σώμα και τα γυμνωμένα δόντια είναι αναγνωρίσιμα παντού.","fact":"Ο συμβιωτής Venom πρωτοεμφανίστηκε ως η νέα μαύρη στολή του Spider-Man, προτού γίνει ξεχωριστός ήρωας.","wiki_en":"Venom (character)"},{"name":"Green Goblin","emoji":"🎃","meta":["«Spider-Man»","κακός εφευρέτης","1964"],"description":"Ο πλούσιος βιομήχανος Νόρμαν Όσμπορν, που ένα δικό του πείραμα τον μετέτρεψε σε παράφρονα κακό με ιπτάμενη σανίδα και οπλοστάσιο από βόμβες-κολοκύθες. Είναι από τους βασικούς και πιο προσωπικούς εχθρούς του Spider-Man, και η φρικιαστική πρασινοβιολετί μάσκα του είναι εμβληματική στα κόμικς.","fact":"Μέσα στις δεκαετίες αρκετοί «διάδοχοι» φόρεσαν τη μάσκα του Green Goblin, ακόμη και ο γιος του Όσμπορν.","wiki_en":"Green Goblin"},{"name":"The Penguin","emoji":"🐧","meta":["«Batman»","αρχηγός του εγκλήματος στο Γκόθαμ","1941"],"description":"Ο Όσβαλντ Κόμπλποτ, εκκεντρικός μεγιστάνας του εγκλήματος στο Γκόθαμ, κρύβει κοφτερό μυαλό πίσω από τη μορφή ενός γελοίου κοντούλη με ομπρέλα-μπαστούνι. Έχει το νυχτερινό κλαμπ «Iceberg Lounge» και μέσα από αυτό ζει διπλή ζωή, ανάμεσα σε νόμιμες δουλειές και έγκλημα.","fact":"Παρά το παρατσούκλι, ο Penguin δεν έχει καμία ικανότητα πουλιού, μόνο αγάπη για τις ομπρέλες και τα θεατρικά εφέ.","wiki_en":"Penguin (character)"},{"name":"Two-Face","emoji":"🪙","meta":["«Batman»","πρώην εισαγγελέας που έγινε κακός","1942"],"description":"Ο Χάρβι Ντεντ, κάποτε ασυμβίβαστος εισαγγελέας του Γκόθαμ, μετά από επίθεση με οξύ απέκτησε εμμονή με την τύχη και ρίχνει ένα νόμισμα για να αποφασίσει μοίρες ανθρώπων. Το μισό πρόσωπό του είναι παραμορφωμένο, εικόνα του διχασμού του καλού και του κακού μέσα του.","fact":"Το ειδικό νόμισμα του Two-Face, καθαρό από τη μία πλευρά και χαραγμένο από την άλλη, έγινε το βασικό του σύμβολο.","wiki_en":"Two-Face"},{"name":"Riddler","emoji":"❓","meta":["«Batman»","ο κακός των αινιγμάτων","1948"],"description":"Ο Έντουαρντ Νίγκμα, ματαιόδοξη εγκληματική ιδιοφυΐα με εμμονή στους γρίφους, στα λογοπαίγνια και στις πνευματικές μονομαχίες με τον Batman. Αφήνει αινίγματα στους τόπους των εγκλημάτων, σαν να μην μπορεί να αντισταθεί στην επίδειξη της εξυπνάδας του. Το πράσινο κοστούμι με τα ερωτηματικά είναι η υπογραφή του.","fact":"Το όνομα Edward Nigma είναι το ίδιο λογοπαίγνιο: ακούγεται σαν το αγγλικό enigma, δηλαδή «αίνιγμα».","wiki_en":"Riddler"},{"name":"Bane","emoji":"😷","meta":["«Batman»","εγκληματίας με υπεράνθρωπη δύναμη","1993"],"description":"Μεγαλωμένος στη σκληρή φυλακή Πένια Ντούρο, ο Bane είναι από τους λίγους αντιπάλους που μπορούν να λυγίσουν τον Batman όχι μόνο με το μυαλό αλλά και με ωμή σωματική δύναμη. Χρησιμοποιεί το διεγερτικό Venom, που πολλαπλασιάζει τη μυϊκή του ισχύ. Στρατηγός και τακτικιστής, όχι απλός μπράβος.","fact":"Ο Bane ήταν αυτός που, στα κόμικς της δεκαετίας του 1990, έσπασε για πρώτη φορά κυριολεκτικά τη μέση του Batman.","wiki_en":"Bane (DC Comics)"},{"name":"Άλφρεντ Πένιγουορθ","emoji":"🫖","meta":["«Batman»","υπηρέτης και μέντορας","1943"],"description":"Ο πιστός οικονόμος του αρχοντικού των Γουέιν, που στάθηκε πατέρας στον μικρό Μπρους μετά τον θάνατο των γονιών του. Βοηθά τον Batman και στο σπίτι και στον εξοπλισμό της σπηλιάς, παραμένοντας η φωνή της συνείδησης και της λογικής. Το στεγνό αγγλικό χιούμορ του φωτίζει το σκοτεινό Γκόθαμ.","fact":"Στα πρώτα κόμικς ο Άλφρεντ ήταν μάλλον κωμική, παχουλή φιγούρα· η γνωστή λεπτή μορφή ήρθε αργότερα.","wiki_en":"Alfred Pennyworth"},{"name":"Aquaman","emoji":"🔱","meta":["DC Comics","βασιλιάς της Ατλαντίδας","1941"],"description":"Ο Άρθουρ Κάρι, μισός άνθρωπος και μισός Ατλάντιος, αναπνέει κάτω από το νερό, διατάζει τα θαλάσσια πλάσματα και διαθέτει υπεράνθρωπη δύναμη. Νόμιμος ηγεμόνας του υποβρύχιου βασιλείου της Ατλαντίδας, διχάζεται ανάμεσα σε δύο κόσμους, τη στεριά και τον ωκεανό.","fact":"Για χρόνια ο Aquaman υποτιμούνταν ως «αστείος» ήρωας, ώσπου οι ταινίες έδειξαν τι μπορεί πραγματικά στη μάχη.","wiki_en":"Aquaman"},{"name":"The Flash","emoji":"🏃","meta":["DC Comics","υπερήρωας της ταχύτητας","1940"],"description":"Ήρωας που απέκτησε την ικανότητα να κινείται πιο γρήγορα από τον ήχο μετά από ατύχημα με χημικά και έναν κεραυνό. Το όνομα το έχουν φορέσει διάφοροι ήρωες, με πιο γνωστό τον εγκληματολόγο Μπάρι Άλεν. Η σύνδεσή του με τη Δύναμη της Ταχύτητας τον αφήνει να ταξιδεύει και στον χρόνο.","fact":"Ο αρχικός Flash της δεκαετίας του 1940, ο Τζέι Γκάρικ, φορούσε φτερωτό κράνος, νεύμα στο κράνος του αρχαίου Ερμή.","wiki_en":"Flash (comics)"},{"name":"Green Lantern","emoji":"💍","meta":["DC Comics","φύλακας του διαστήματος","1940"],"description":"Κάτοχος ενός δαχτυλιδιού δύναμης, που υλοποιεί οποιοδήποτε αντικείμενο με τη θέληση, και μέλος του διαγαλαξιακού Σώματος των Green Lanterns που φυλάει την τάξη στο σύμπαν. Ο πιο γνωστός φορέας του ονόματος στη Γη είναι ο πιλότος Χαλ Τζόρνταν. Μοναδική αδυναμία του δαχτυλιδιού είναι το κίτρινο χρώμα.","fact":"Στο σύμπαν της DC μετρήθηκαν χιλιάδες Green Lanterns, με τον καθένα να φυλάει τον δικό του τομέα του διαστήματος.","wiki_en":"Green Lantern"},{"name":"Λεξ Λούθορ","emoji":"💼","meta":["DC Comics","μεγιστάνας κακός","1940"],"description":"Ιδιοφυής επιστήμονας και δισεκατομμυριούχος της Μετρόπολις, που το μίσος του για τον Superman στηρίζεται στην πεποίθηση ότι η ανθρωπότητα δεν χρειάζεται εξωγήινο σωτήρα. Δρα μέσα από νόμιμες επιχειρήσεις και την πολιτική όσο και μέσα από εγκληματικά σχέδια. Από τους πιο έξυπνους και επικίνδυνους ανθρώπους της DC.","fact":"Στα κόμικς ο Λεξ Λούθορ κάποια στιγμή κατέλαβε ακόμη και επίσημα τη θέση του προέδρου των ΗΠΑ.","wiki_en":"Lex Luthor"},{"name":"Darkseid","emoji":"🪐","meta":["DC Comics","διαγαλαξιακός τύραννος","1970"],"description":"Ο παντοδύναμος άρχοντας του ζοφερού πλανήτη Απόκολιπς, με εμμονή στην αναζήτηση της Εξίσωσης της Αντιζωής, που θα στερούσε από κάθε νοήμον ον την ελεύθερη βούληση. Από τους ισχυρότερους και πιο ψυχρούς κακούς της DC, αντίπαλος της Λέγκας της Δικαιοσύνης και των Νέων Θεών.","fact":"Τον Darkseid επινόησε ο θρυλικός σχεδιαστής Τζακ Κίρμπι, ως μέρος του μεγαλόπνοου έπους του για τους Νέους Θεούς.","wiki_en":"Darkseid"},{"name":"Deadshot","emoji":"🎯","meta":["DC Comics","πληρωμένος δολοφόνος","1950"],"description":"Ο Φλόιντ Λότον, ο πιο εύστοχος σκοπευτής του σύμπαντος της DC, πληρωμένος δολοφόνος που υποστηρίζει ότι δεν αστοχεί ποτέ. Δουλεύει για χρήμα, αλλά και μέσα στην καταναγκαστική ομάδα «Suicide Squad» με αντάλλαγμα μείωση της ποινής. Πίσω από την κυνική μάσκα κρύβει μια δύσκολη σχέση με την κόρη του.","fact":"Το παρατσούκλι Deadshot σημαίνει στα αγγλικά τον αλάνθαστο σκοπευτή, και ο ήρωας πρωτοεμφανίστηκε σε κόμικ του Batman.","wiki_en":"Deadshot"},{"name":"Άτικους Φιντς","emoji":"⚖️","meta":["«Όταν σκοτώνουν τα κοτσύφια»","δικηγόρος","1960"],"description":"Μεσήλικας δικηγόρος σε μια επαρχιακή πόλη του αμερικανικού Νότου, που μεγαλώνει μόνος δύο παιδιά και αναλαμβάνει την υπεράσπιση ενός μαύρου άντρα μπροστά σε ένα ρατσιστικό δικαστήριο. Είναι η ενσάρκωση της ήρεμης αξιοπρέπειας και της ηθικής αντοχής απέναντι στην κοινωνική πίεση.","fact":"Σε δημοσκοπήσεις αναγνωστών ο Άτικους Φιντς έχει ανακηρυχθεί πολλές φορές από τους μεγαλύτερους ήρωες της αμερικανικής λογοτεχνίας.","wiki_en":"Atticus Finch"},{"name":"Τζέι Γκάτσμπι","emoji":"🥂","meta":["«Ο Υπέροχος Γκάτσμπι»","μυστηριώδης πλούσιος","1925"],"description":"Αινιγματικός νεόπλουτος, που διοργανώνει θορυβώδη πάρτι στο αρχοντικό του στο Λονγκ Άιλαντ για έναν και μόνο σκοπό: να ξανακερδίσει μια χαμένη αγάπη της νιότης του. Πίσω από τη λάμψη και την επιδεικτική πολυτέλεια κρύβεται ένας άνθρωπος εγκλωβισμένος σε ένα εξιδανικευμένο παρελθόν.","fact":"Στα δικά του θορυβώδη πάρτι ο Γκάτσμπι σχεδόν δεν εμφανίζεται ανάμεσα στους καλεσμένους, παρακολουθώντας από μακριά.","wiki_en":"Jay Gatsby"},{"name":"Σκάρλετ Ο'Χάρα","emoji":"👗","meta":["«Όσα παίρνει ο άνεμος»","αριστοκράτισσα του Νότου","1936"],"description":"Η πεισματάρα και πραγματίστρια κόρη ενός γαιοκτήμονα της Τζόρτζια πριν τον πόλεμο, της οποίας η ζωή ανατρέπεται με τον Εμφύλιο. Είναι πρόθυμη για κάθε τέχνασμα και κάθε θυσία για να σώσει το πατρικό κτήμα Τάρα και τον εαυτό της. Από τις πιο έντονες και αντιφατικές ηρωίδες της αμερικανικής λογοτεχνίας.","fact":"Η περίφημη φράση της «Θα το σκεφτώ αύριο» επανέρχεται στο μυθιστόρημα, καθώς αναβάλλει τις δύσκολες αποφάσεις.","wiki_en":"Scarlett O'Hara"},{"name":"Ρετ Μπάτλερ","emoji":"🎩","meta":["«Όσα παίρνει ο άνεμος»","κυνικός τυχοδιώκτης","1936"],"description":"Γοητευτικός έμπορος και λαθρέμπορος, που στον Εμφύλιο πλουτίζει από τις συμφορές των άλλων, αλλά κρυφά είναι ικανός για αληθινό πάθος. Το πνεύμα και η νηφάλια ματιά του έρχονται σε έντονη αντίθεση με τις ρομαντικές αυταπάτες των γύρω του. Από τους πιο γνωστούς ρομαντικούς ήρωες της αμερικανικής κουλτούρας.","fact":"Η τελευταία ατάκα του Ρετ Μπάτλερ στην ταινία του 1939 έγινε μία από τις πιο πολυθρύλητες στην ιστορία του Χόλιγουντ.","wiki_en":"Rhett Butler"},{"name":"Τζέιν Έιρ","emoji":"📖","meta":["«Τζέιν Έιρ»","γκουβερνάντα","1847"],"description":"Ορφανή που μεγάλωσε σε ένα σκληρό ορφανοτροφείο και γίνεται γκουβερνάντα στο ζοφερό αρχοντικό Θόρνφιλντ, όπου την περιμένει ένας δύσκολος έρωτας με τον οικοδεσπότη. Παρά τη φτώχεια και τη ταπεινή της θέση, έχει ακλόνητη αίσθηση της αξίας της. Από τις πρώτες δυνατές ηρωίδες της αγγλικής λογοτεχνίας.","fact":"Το μυθιστόρημα της Σαρλότ Μπροντέ εκδόθηκε αρχικά με αντρικό ψευδώνυμο, Κάρερ Μπελ.","wiki_en":"Jane Eyre (character)"},{"name":"Ο κύριος Ντάρσι","emoji":"🕴️","meta":["«Περηφάνια και Προκατάληψη»","πλούσιος αριστοκράτης","1813"],"description":"Περήφανος και συγκρατημένος Άγγλος γαιοκτήμονας, που η ψυχρότητά του στους χορούς κρύβει συστολή και βαθιά αισθήματα. Η δύσκολη σχέση του με την Ελίζαμπεθ Μπένετ στηρίζεται στην υπέρβαση των αμοιβαίων προκαταλήψεων και της πληγωμένης περηφάνιας. Από τους πιο διάσημους ρομαντικούς ήρωες της αγγλικής λογοτεχνίας.","fact":"Η σκηνή με το βρεγμένο πουκάμισο στη σειρά του BBC το 1995 έγινε μία από τις πιο θρυλικές της βρετανικής τηλεόρασης.","wiki_en":"Mr Darcy"},{"name":"Ελίζαμπεθ Μπένετ","emoji":"🌸","meta":["«Περηφάνια και Προκατάληψη»","ευφυολόγος ηρωίδα","1813"],"description":"Η δεύτερη από τις πέντε κόρες ενός όχι πλούσιου Άγγλου γαιοκτήμονα, με κοφτερό μυαλό, ανεξάρτητο χαρακτήρα και κλίση στην ειρωνεία. Δεν φοβάται να προκαλέσει τις κοινωνικές συμβάσεις, ούτε τις δικές της προκαταλήψεις, για χάρη των αληθινών αισθημάτων.","fact":"Η ίδια η Τζέιν Όστεν έγραφε σε γράμματά της ότι η Ελίζαμπεθ Μπένετ είναι το πιο χαριτωμένο πρόσωπο που μπόρεσε να πλάσει.","wiki_en":"Elizabeth Bennet"},{"name":"Όλιβερ Τουίστ","emoji":"🥣","meta":["«Όλιβερ Τουίστ»","ορφανό αγόρι","1837"],"description":"Ορφανό αγόρι από πτωχοκομείο, που το μετρημένο αίτημά του για λίγο περισσότερο χυλό έγινε μία από τις πιο διάσημες σκηνές της αγγλικής λογοτεχνίας. Στους δρόμους του Λονδίνου πέφτει σε μια συμμορία νεαρών πορτοφολάδων υπό τον πονηρό Φέιγκιν. Ιστορία φτώχειας και επιβίωσης ενός παιδιού.","fact":"Ο Ντίκενς δημοσίευε το μυθιστόρημα σε μηνιαίες συνέχειες, κρατώντας τους αναγνώστες σε αγωνία για μήνες.","wiki_en":"Oliver Twist"},{"name":"Εμπενίζερ Σκρουτζ","emoji":"💰","meta":["«Χριστουγεννιάτικη Ιστορία»","τσιγκούνης επιχειρηματίας","1843"],"description":"Σκληρός και άπληστος γερο-τοκογλύφος, που περιφρονεί τα Χριστούγεννα και κάθε εκδήλωση καλοσύνης, ώσπου την παραμονή τον επισκέπτονται τρία πνεύματα. Οι επισκέψεις τους τον αναγκάζουν να ξανακοιτάξει όλη του τη ζωή και τη στάση του προς τους ανθρώπους.","fact":"Το όνομα Scrooge έχει γίνει στα αγγλικά κοινή λέξη για τον τσιγκούνη.","wiki_en":"Ebenezer Scrooge"},{"name":"Ντόριαν Γκρέι","emoji":"🖼️","meta":["«Το πορτρέτο του Ντόριαν Γκρέι»","αιώνια νέος καλλονός","1890"],"description":"Ωραίος νέος, που το ζωγραφισμένο πορτρέτο του γερνά και ασχημαίνει στη θέση του, ενώ ο ίδιος μένει αιώνια νέος. Η ελευθερία από τις συνέπειες τον σπρώχνει σε μια όλο και πιο ακόλαστη ζωή. Το μυθιστόρημα του Όσκαρ Ουάιλντ για το τίμημα της ματαιοδοξίας και της αιώνιας ομορφιάς.","fact":"Το μόνο μυθιστόρημα του Ουάιλντ προκάλεσε τόσο σκάνδαλο όσο ζούσε, ώστε ο συγγραφέας άμβλυνε κάποια επεισόδια για την επανέκδοση.","wiki_en":"Dorian Gray"},{"name":"Ο δόκτωρ Τζέκιλ και ο κύριος Χάιντ","emoji":"🧪","meta":["νουβέλα του Ρ. Λ. Στίβενσον","επιστήμονας με δύο προσωπικότητες","1886"],"description":"Ευυπόληπτος γιατρός του Λονδίνου, που επινοεί ένα φίλτρο το οποίο απελευθερώνει τη σκοτεινή πλευρά της προσωπικότητάς του με τη μορφή του βάναυσου κυρίου Χάιντ. Η ιστορία του διχασμού της ανθρώπινης φύσης σε λογική και πρωτόγονο ένστικτο είναι κλασικό δείγμα γοτθικής πεζογραφίας.","fact":"Η έκφραση «Τζέκιλ και Χάιντ» χρησιμοποιείται ακόμη για κάποιον με δύο εντελώς αντίθετες πλευρές χαρακτήρα.","wiki_en":"Henry Jekyll"},{"name":"Καπετάνιος Νέμο","emoji":"🐙","meta":["μυθιστορήματα του Ιουλίου Βερν","κυβερνήτης του υποβρυχίου «Ναυτίλος»","1870"],"description":"Μυστηριώδης επιστήμονας σε αυτοεξορία, που έκοψε κάθε δεσμό με την ανθρώπινη κοινωνία και έφτιαξε το υποβρύχιο «Ναυτίλος», με το οποίο περιπλανιέται στους ωκεανούς. Ιδιοφυής μηχανικός και μισάνθρωπος, τα αληθινά κίνητρα και η καταγωγή του μένουν για καιρό μυστικό.","fact":"Σε μεταγενέστερο μυθιστόρημα του Ιουλίου Βερν, «Το μυστηριώδες νησί», αποκαλύπτονται το αληθινό όνομα και το παρελθόν του καπετάν Νέμο.","wiki_en":"Captain Nemo"},{"name":"Ροβινσώνας Κρούσος","emoji":"🏝️","meta":["«Ροβινσώνας Κρούσος»","ναυαγός ναυτικός","1719"],"description":"Άγγλος ναυτικός, ο μόνος που επέζησε από ναυάγιο σε ένα ερημικό νησί, όπου θα περάσει πολλά χρόνια. Με δουλειά και εφευρετικότητα μετατρέπει την άγρια φύση σε κάτι σαν πολιτισμένο νοικοκυριό. Το βιβλίο του Ντάνιελ Ντεφόε θεωρείται από τα πρώτα αγγλικά μυθιστορήματα και γέννησε ένα ολόκληρο είδος.","fact":"Ως βάση της ιστορίας θεωρείται ο πραγματικός ναυτικός Αλεξάντερ Σέλκερκ, που έζησε χρόνια μόνος σε ένα νησί.","wiki_en":"Robinson Crusoe"},{"name":"Γκιούλιβερ","emoji":"📏","meta":["«Τα ταξίδια του Γκιούλιβερ»","γιατρός ταξιδευτής","1726"],"description":"Γιατρός πλοίου, που τα φανταστικά του ταξίδια τον φέρνουν άλλοτε στη χώρα των μικροσκοπικών Λιλιπούτειων, άλλοτε στους γίγαντες του Μπρόμπντινγκναγκ και άλλοτε σε ακόμη παράξενους λαούς. Μέσα από την έκπληξή του ο Τζόναθαν Σουίφτ σατιρίζει καυστικά τα ελαττώματα της εποχής του.","fact":"Στη χώρα των Λιλιπούτειων δένουν τον Γκιούλιβερ στο έδαφος με χιλιάδες λεπτά νήματα, όσο κοιμάται μετά το ναυάγιο.","wiki_en":"Lemuel Gulliver"},{"name":"Ντ' Αρτανιάν","emoji":"🤺","meta":["«Οι Τρεις Σωματοφύλακες»","ευγενής από τη Γασκώνη","1844"],"description":"Νέος και φιλόδοξος Γασκώνος, που φτάνει στο Παρίσι για να γίνει σωματοφύλακας του βασιλιά και σύντομα γίνεται στενός φίλος τριών θρυλικών ξιφομάχων. Γενναίος, οξύθυμος και αφοσιωμένος στη φιλία όσο και στην τιμή. Από τους πιο διάσημους ήρωες της περιπετειώδους λογοτεχνίας.","fact":"Ο Ντ' Αρτανιάν είχε πραγματικό ιστορικό πρότυπο: έναν Γασκώνο ευγενή και αξιωματικό των σωματοφυλάκων του 17ου αιώνα.","wiki_en":"D'Artagnan"},{"name":"Άθος","emoji":"⚔️","meta":["«Οι Τρεις Σωματοφύλακες»","ο ευγενής σωματοφύλακας","1844"],"description":"Ο μεγαλύτερος και πιο σιωπηλός από τους τρεις σωματοφύλακες, που πίσω από την αριστοκρατική του συγκράτηση κρύβει ένα βαρύ μυστικό του παρελθόντος. Σοφός μέντορας για τον νεαρό Ντ' Αρτανιάν και ασυναγώνιστος ξιφομάχος. Η ενσάρκωση της τιμής στα μυθιστορήματα του Δουμά.","fact":"Το αληθινό όνομά του αποκαλύπτεται μέσα στο μυθιστόρημα: είναι ο κόμης ντε λα Φερ, με δύσκολη προσωπική ιστορία.","wiki_en":"Athos (The Three Musketeers)","wiki_ru":"Атос"},{"name":"Πόρθος","emoji":"🍖","meta":["«Οι Τρεις Σωματοφύλακες»","ο δυνατός σωματοφύλακας","1844"],"description":"Ο πιο ψηλός και σωματικά δυνατός των τεσσάρων σωματοφυλάκων, αγαθός και λάτρης του καλού φαγητού και των επιδεικτικών ρούχων. Η ευθύτητα και η καλοσύνη του έρχονται σε έντονη αντίθεση με τις ίντριγκες της αυλής. Πιστός σύντροφος, έτοιμος να καλύψει τους φίλους του σε κάθε συμπλοκή.","fact":"Ο Πόρθος είναι ο μόνος από τους τέσσερις που καμαρώνει ειλικρινά όχι για το μυαλό αλλά για τη σωματική του δύναμη.","wiki_en":"Porthos"},{"name":"Αραμίς","emoji":"✝️","meta":["«Οι Τρεις Σωματοφύλακες»","σωματοφύλακας και υποψήφιος κληρικός","1844"],"description":"Ο πιο εκλεπτυσμένος και αινιγματικός των σωματοφυλάκων, που ονειρεύεται να αφήσει κάποτε τα όπλα για μια εκκλησιαστική καριέρα. Συνδυάζει τους εξαίσιους τρόπους του αριστοκράτη με υπολογιστικό μυαλό και δεξιοτεχνία στο ξίφος. Με τον καιρό γίνεται ο πιο ισχυρός πολιτικά των τεσσάρων.","fact":"Στα μεταγενέστερα μυθιστορήματα του Δουμά ο Αραμίς κάνει την πιο εντυπωσιακή καριέρα των τεσσάρων, φτάνοντας ψηλά στην Εκκλησία.","wiki_en":"Aramis"},{"name":"Ο Κόμης Μοντεχρήστος","emoji":"💎","meta":["«Ο Κόμης Μοντεχρήστος»","εκδικητής","1844"],"description":"Ο νέος ναυτικός Εδμόνδος Δαντές, άδικα καταδικασμένος και έγκλειστος στο κάστρο του Ιφ, δραπετεύει, βρίσκει αμύθητο θησαυρό και επιστρέφει με νέο όνομα. Για χρόνια χτίζει μεθοδικά το σχέδιο εκδίκησής του απέναντι σε όσους κατέστρεψαν τη ζωή του.","fact":"Ο Δουμά πήρε την πλοκή από την αληθινή ιστορία ενός Γάλλου τσαγκάρη, θύματος συνωμοσίας από φθονερούς γνωστούς.","wiki_en":"Edmond Dantès"},{"name":"Κουασιμόδος","emoji":"🔔","meta":["«Η Παναγία των Παρισίων»","καμπουριασμένος καμπανοκρούστης","1831"],"description":"Ο κουφός και παραμορφωμένος καμπανοκρούστης της Νοτρ Νταμ, κρυμμένος από παιδί μέσα στους τοίχους του ναού, μακριά από τον σκληρό κόσμο. Πίσω από τη τρομακτική όψη κρύβεται μια τρυφερή, αφοσιωμένη ψυχή, ικανή για την πιο ειλικρινή αγάπη.","fact":"Πήρε το όνομά του από τη μέρα που τον άφησαν στον ναό: την Κυριακή Quasimodo, την πρώτη μετά το Πάσχα.","wiki_en":"Quasimodo"},{"name":"Εσμεράλδα","emoji":"💃","meta":["«Η Παναγία των Παρισίων»","τσιγγάνα χορεύτρια","1831"],"description":"Νεαρή χορεύτρια του δρόμου από τσιγγάνικο θίασο, που η ομορφιά και η καλοσύνη της τραβούν ταυτόχρονα το βλέμμα αρκετών αντρών του Παρισιού, από τον καμπανοκρούστη ως τον αρχιδιάκονο. Αγαπά την ελευθερία της και είναι καλή με τους απόκληρους, ακόμη και με τον Κουασιμόδο.","fact":"Η Εσμεράλδα έχει μια πιστή ήμερη κατσικούλα, την Τζαλί, που εμφανίζεται δίπλα της σχεδόν σε κάθε σκηνή του βιβλίου.","wiki_en":"Esmeralda (The Hunchback of Notre-Dame)"},{"name":"Δον Κιχώτης","emoji":"🐴","meta":["«Δον Κιχώτης»","ονειροπόλος ιππότης","1605"],"description":"Ηλικιωμένος Ισπανός ευπατρίδης, που τρελάθηκε από τα ιπποτικά μυθιστορήματα και φαντάστηκε τον εαυτό του περιπλανώμενο ιππότη της δικαιοσύνης. Μαζί με τον πιστό του υπασπιστή Σάντσο Πάντσα παίρνει τους δρόμους, παίρνοντας τους ανεμόμυλους για γίγαντες.","fact":"Το βιβλίο του Θερβάντες θεωρείται από τα πρώτα και πιο επιδραστικά μυθιστορήματα στην ιστορία της νεότερης ευρωπαϊκής λογοτεχνίας.","wiki_en":"Don Quixote"},{"name":"Σάντσο Πάντσα","emoji":"🫏","meta":["«Δον Κιχώτης»","χωρικός υπασπιστής","1605"],"description":"Αγαθός χωρικός, που γίνεται υπασπιστής του Δον Κιχώτη με την υπόσχεση ενός νησιού για να το κυβερνήσει. Η γήινη λογική και η λαϊκή σοφία του λειτουργούν ως διαρκής αντίστιξη στις τρελές φαντασιώσεις του αφέντη του. Με τον καιρό γεννιέται ανάμεσά τους αληθινή, συγκινητική φιλία.","fact":"Παρά τα συνεχή πειράγματα για την αφέλεια του αφέντη του, ο Σάντσο Πάντσα δένεται ειλικρινά με τον Δον Κιχώτη και μένει μαζί του ως το τέλος.","wiki_en":"Sancho Panza"},{"name":"Ρωμαίος","emoji":"🌹","meta":["«Ρωμαίος και Ιουλιέτα»","ερωτευμένος νέος","1597"],"description":"Ο νεαρός γόνος του οίκου των Μοντέγων στη Βερόνα, που ο φλογερός έρωτάς του για την Ιουλιέτα της αντίπαλης οικογένειας των Καπουλέτων γίνεται δοκιμασία για τα δύο γένη. Παρορμητικός, ρομαντικός και έτοιμος για κάθε ακρότητα για χάρη του αισθήματος.","fact":"Το όνομα «Ρωμαίος» έχει γίνει στην καθομιλουμένη συνώνυμο του φλογερού ρομαντικού θαυμαστή.","wiki_en":"Romeo Montague"},{"name":"Ιουλιέτα","emoji":"🌙","meta":["«Ρωμαίος και Ιουλιέτα»","νεαρή ηρωίδα της Βερόνας","1597"],"description":"Η δεκατριάχρονη κόρη των Καπουλέτων, που ο πρώτος της έρωτας για τον Ρωμαίο των αντίπαλων Μοντέγων γίνεται αιτία τραγωδίας για δύο οικογένειες. Αποφασιστική και πιστή στα αισθήματά της, παρά τη θέληση των γονιών και την έχθρα των γενών.","fact":"Στη περίφημη σκηνή του μπαλκονιού, όπου η Ιουλιέτα λέει τον μονόλογό της, το αρχικό κείμενο δεν αναφέρει καθόλου μπαλκόνι.","wiki_en":"Juliet"},{"name":"Άμλετ","emoji":"💀","meta":["«Άμλετ»","πρίγκιπας της Δανίας","1600"],"description":"Ο πρίγκιπας της Δανίας, που μαθαίνει από το φάντασμα του πατέρα του πως εκείνος δολοφονήθηκε και διχάζεται ανάμεσα στη δίψα της εκδίκησης και σε βασανιστικές φιλοσοφικές αμφιβολίες. Οι μονόλογοί του για τη ζωή και τον θάνατο έκαναν το έργο ένα από τα πιο πολυθρύλητα της παγκόσμιας κουλτούρας.","fact":"Ο μονόλογος «Να ζει κανείς ή να μη ζει» θεωρείται από τα πιο αναγνωρίσιμα αποσπάσματα όλης της αγγλόφωνης λογοτεχνίας.","wiki_en":"Prince Hamlet"},{"name":"Μάκβεθ","emoji":"🗡️","meta":["«Μάκβεθ»","Σκωτσέζος σφετεριστής","1606"],"description":"Σκωτσέζος στρατηλάτης, που τη φιλοδοξία του ανάβουν οι προφητείες τριών μαγισσών και η παρακίνηση της γυναίκας του. Ο φόνος του βασιλιά για τον θρόνο τον ρίχνει σε μια όλο και πιο παράφρονη σπείρα βίας και παράνοιας. Μία από τις πιο σκοτεινές τραγωδίες του Σαίξπηρ.","fact":"Οι ηθοποιοί κρατούν ακόμη τη δεισιδαιμονία να μην προφέρουν τον τίτλο του έργου στα παρασκήνια, λέγοντάς το «το σκωτσέζικο έργο».","wiki_en":"Macbeth (character)"},{"name":"Οθέλλος","emoji":"🎭","meta":["«Οθέλλος»","Βενετός στρατηγός","1603"],"description":"Επιτυχημένος μαύρος στρατηγός της Βενετίας, που τον ευτυχισμένο γάμο του με τη Δεισδαιμόνα καταστρέφει η δόλια συκοφαντία του φθονερού αξιωματικού Ιάγου. Η ζήλια, επιδέξια υποδαυλισμένη, τον σπρώχνει σε ένα τραγικό σφάλμα.","fact":"Το όνομα του δόλιου Ιάγου από αυτό το έργο έχει γίνει συνώνυμο του υπολογισμένου συκοφάντη.","wiki_en":"Othello (character)"},{"name":"Τσιπολίνο","emoji":"🧅","meta":["παραμύθι του Τζάνι Ροντάρι","το αγόρι-κρεμμυδάκι","1951"],"description":"Θαρραλέο αγόρι-κρεμμυδάκι, που ηγείται του αγώνα των απλών λαχανικών και φρούτων απέναντι στην άδικη εξουσία του σινιόρ Ντομάτα και των υπεροπτικών αρχόντων. Πονηρός, επινοητικός και πάντα πρόθυμος να υπερασπιστεί τους αδύναμους.","fact":"Το παραμύθι του Τζάνι Ροντάρι αγαπήθηκε στη Σοβιετική Ένωση σχεδόν περισσότερο απ' ό,τι στην πατρίδα του συγγραφέα, την Ιταλία.","wiki_en":"Cipollino"},{"name":"Μαλβίνα","emoji":"🎀","meta":["«Το χρυσό κλειδάκι»","το κορίτσι με τα γαλάζια μαλλιά","1936"],"description":"Κούκλα με γαλάζια μαλλιά και άψογους τρόπους, που ζει στο δάσος και προσπαθεί να αναθρέψει τον άτακτο Μπουρατίνο με όλους τους κανόνες της καλής συμπεριφοράς. Τα μαθήματα αριθμητικής και καλλιγραφίας γίνονται διαρκής αφορμή σύγκρουσης με το σκανταλιάρικο ξύλινο αγόρι.","fact":"Τα γαλάζια μαλλιά της Μαλβίνας παραμένουν εδώ και δεκαετίες από τις πιο αναγνωρίσιμες λεπτομέρειες της σοβιετικής εικονογράφησης.","wiki_en":"The Golden Key, or the Adventures of Buratino","wiki_ru":"Мальвина (персонаж)"},{"name":"Ντουρεμάρ","emoji":"🎣","meta":["«Το χρυσό κλειδάκι»","έμπορος βδελλών","1936"],"description":"Ψηλόλιγνη και σκυθρωπή φιγούρα με μακριά ρεντιγκότα, που βιοπορίζεται πουλώντας βδέλλες και υπηρετεί τον Καραμπάς-Μπαραμπάς. Το θλιμμένο πρόσωπο και τα αδιάκοπα παράπονά του για τη ζωή έγιναν σήμα κατατεθέν του στα σοβιετικά κινούμενα σχέδια.","fact":"Στο ιταλικό πρωτότυπο, τις «Περιπέτειες του Πινόκιο», δεν υπάρχει κανένας Ντουρεμάρ: τον επινόησε ο Αλεξέι Τολστόι.","wiki_en":"The Golden Key, or the Adventures of Buratino","wiki_ru":"Дуремар"},{"name":"Πιερότος","emoji":"😢","meta":["«Το χρυσό κλειδάκι»","ο θλιμμένος ποιητής των κούκλων","1936"],"description":"Μελαγχολικός ποιητής-κούκλα από το θέατρο του Καραμπάς-Μπαραμπάς, που αναστενάζει αιώνια για τον ανεκπλήρωτο έρωτά του για τη Μαλβίνα. Με λευκό φαρδύ ρούχο και μακριά μανίκια απαγγέλλει θλιμμένους στίχους, σε κραυγαλέα αντίθεση με τον εύθυμο Μπουρατίνο.","fact":"Η μορφή του Πιερότου προέρχεται από παραδοσιακό πρόσωπο του ευρωπαϊκού θεάτρου: τον θλιμμένο ερωτευμένο κλόουν της κομέντια ντελ άρτε.","wiki_en":"The Golden Key, or the Adventures of Buratino","wiki_ru":"Буратино"},{"name":"Καραμπάς-Μπαραμπάς","emoji":"🎪","meta":["«Το χρυσό κλειδάκι»","ιδιοκτήτης του κουκλοθέατρου","1936"],"description":"Ο γενειοφόρος και σκληρός ιδιοκτήτης ενός κουκλοθέατρου, που τυραννά τους ηθοποιούς-μαριονέτες του και έχει εμμονή με την αναζήτηση του χρυσού κλειδιού. Η μακριά του γενειάδα, που σκαλώνει διαρκώς στις πόρτες, είναι από τα πιο αναγνωρίσιμα στοιχεία του.","fact":"Στο βιβλίο ο Καραμπάς-Μπαραμπάς κρατά τις κούκλες του σε τρόμο με ένα εφτάουρο μαστίγιο και τη γενειάδα του χωμένη στην τσέπη.","wiki_en":"The Golden Key, or the Adventures of Buratino","wiki_ru":"Карабас-Барабас"},{"name":"Πάπα Κάρλο","emoji":"🪵","meta":["«Το χρυσό κλειδάκι»","λατερνατζής και τεχνίτης","1936"],"description":"Φτωχός αλλά καλόκαρδος λατερνατζής, που σκάλισε από ένα κούτσουρο ένα ξύλινο αγόρι που μιλούσε και του στάθηκε πατέρας. Ανέχεται με υπομονή τις σκανταλιές του άτακτου Μπουρατίνο και συνεχίζει να τον φροντίζει σαν δικό του γιο.","fact":"Το δωματιάκι του Πάπα Κάρλο, με ένα τζάκι ζωγραφισμένο σε καμβά, κρύβει μια μυστική πόρτα προς ένα μαγικό κουκλοθέατρο.","wiki_en":"The Golden Key, or the Adventures of Buratino","wiki_ru":"Папа Карло"},{"name":"Η Κοκκινοσκουφίτσα","emoji":"🧺","meta":["λαϊκό παραμύθι","το κορίτσι με το καλάθι","1697"],"description":"Καλό κορίτσι, που η μητέρα του το στέλνει μέσα από το δάσος να πάει καλούδια στην άρρωστη γιαγιά και στον δρόμο πιάνει εμπιστευτικά κουβέντα με τον πονηρό λύκο. Ένα από τα πιο γνωστά παραμύθια για την αφέλεια και τους κινδύνους του δρόμου, με δεκάδες εκδοχές στην Ευρώπη.","fact":"Την πιο γνωστή λογοτεχνική καταγραφή του παραμυθιού έκανε ο Γάλλος παραμυθάς Σαρλ Περό στα τέλη του 17ου αιώνα.","wiki_en":"Little Red Riding Hood"},{"name":"Εμέλια","emoji":"🐟","meta":["ρωσικό λαϊκό παραμύθι","τεμπέλης τυχερός"],"description":"Ήρωας ρωσικού παραμυθιού, που έπιασε ένα λούτσο που μιλούσε και ως αμοιβή για την απελευθέρωσή του πήρε ένα μαγικό δώρο: κάθε ευχή του πραγματοποιείται με τη φράση «κατά την προσταγή του λούτσου». Η σόμπα τον κουβαλά μόνη της στο χωριό και οι κουβάδες πάνε για νερό χωρίς χέρια.","fact":"Η περίφημη σόμπα, πάνω στην οποία κυκλοφορεί ο Εμέλια, έγινε από τις πιο αναγνωρίσιμες εικόνες των ρωσικών παραμυθιών.","wiki_en":"Emelya","wiki_ru":"По щучьему веленью"},{"name":"Ιβάν ο Ανόητος","emoji":"🪄","meta":["ρωσικό λαϊκό παραμύθι","ο μικρότερος από τα αδέλφια"],"description":"Ο μικρότερος και φαινομενικά πιο κουτός από τα τρία αδέλφια των ρωσικών παραμυθιών, που οι δικοί του τον κοροϊδεύουν ώσπου αποδεικνύεται ο πιο καλός, ο πιο έντιμος και τελικά ο πιο τυχερός. Η φαινομενική απλότητά του αποδεικνύεται συχνά πρακτική σοφία.","fact":"Κάτω από το όνομα του Ιβάν του Ανόητου κρύβονται πολύ διαφορετικές ιστορίες, που τις ενώνει μόνο ο τύπος του ήρωα.","wiki_en":"Ivan the Fool","wiki_ru":"Иван-дурак"},{"name":"Βασιλίσα η Ωραία","emoji":"👸","meta":["ρωσικό λαϊκό παραμύθι","σοφή καλλονή"],"description":"Ηρωίδα των ρωσικών παραμυθιών, που συνδυάζει σπάνια ομορφιά με σοφία και μαγικές ικανότητες, κληρονομιά της νεκρής μητέρας της με τη μορφή μιας πολύτιμης κουκλίτσας-βοηθού. Περνά από δοκιμασίες στην καλύβα της Μπάμπα Γιάγκα και από τη κακία των κοριτσιών της μητριάς της.","fact":"Σε διαφορετικά παραμύθια το όνομα της Βασιλίσας της Ωραίας συνυπάρχει με μια παρόμοια μορφή, τη Βασιλίσα την Πάνσοφη.","wiki_en":"Vasilisa the Beautiful"},{"name":"Ζμέι Γκορίνιτς","emoji":"🐉","meta":["ρωσικό λαϊκό παραμύθι","τρικέφαλος δράκος"],"description":"Το πυρφόρο τρικέφαλο τέρας των ρωσικών επών και παραμυθιών, που αρπάζει ανθρώπους και κρατά ολόκληρα χωριά σε τρόμο. Η νίκη επάνω του είναι παραδοσιακά η μεγάλη δοκιμασία για τον ήρωα πολεμιστή. Μία από τις πιο αναγνωρίσιμες φανταστικές μορφές της σλαβικής λαϊκής παράδοσης.","fact":"Ο αριθμός των κεφαλιών αλλάζει από παραμύθι σε παραμύθι: υπάρχουν εκδοχές από τρία έως δώδεκα.","wiki_en":"Zmey Gorynych"},{"name":"Το πουλί της φωτιάς","emoji":"🐦‍🔥","meta":["ρωσικό λαϊκό παραμύθι","μαγικό φωτεινό πουλί"],"description":"Μυθικό πουλί με λαμπερό, χρυσό και πύρινο φτέρωμα, για ένα μόνο φτερό του οποίου οι ήρωες ξεκινούν επικίνδυνα ταξίδια. Η σύλληψή του είναι συχνά μέρος μιας ακατόρθωτης βασιλικής αποστολής, μαζί με άλλα θαυμαστά αντικείμενα.","fact":"Η μορφή του πουλιού της φωτιάς ενέπνευσε στον Ιγκόρ Στραβίνσκι το περίφημο ομώνυμο μπαλέτο, στις αρχές του 20ού αιώνα.","wiki_en":"Firebird (Slavic folklore)"},{"name":"Μορόζκο","emoji":"❄️","meta":["ρωσικό λαϊκό παραμύθι","το πνεύμα της χειμωνιάτικης παγωνιάς"],"description":"Αυστηρό αλλά δίκαιο πνεύμα του χειμωνιάτικου δάσους, που δοκιμάζει στο κρύο μια προγονή και τη φυσική κόρη της μητριάς και ανταμείβει πλουσιοπάροχα την υπομονή και την ευγένεια. Η μορφή του έγινε η βάση μιας διάσημης σοβιετικής κινηματογραφικής παραμυθιακής ταινίας.","fact":"Η σοβιετική ταινία «Μορόζκο» του 1964 έγινε χριστουγεννιάτικη παράδοση στην Τσεχία, όπου προβάλλεται στην τηλεόραση κάθε χρόνο.","wiki_en":"Morozko","wiki_ru":"Морозко (сказка)"},{"name":"Σνεγκούροτσκα","emoji":"🌨️","meta":["ρωσική λαϊκή παράδοση","κοπέλα από χιόνι"],"description":"Κοπέλα πλασμένη από χιόνι από ένα γέρικο ζευγάρι και ζωντανεμένη, που η μοίρα της δένεται με το κρύο: όταν έρχεται η ζέστη λιώνει ή πετά μακριά. Στη νεότερη παράδοση έγινε η μόνιμη συντροφιά του Ντεντ Μορόζ στις γιορτές της Πρωτοχρονιάς.","fact":"Μόνιμη βοηθός του Ντεντ Μορόζ στις πρωτοχρονιάτικες γιορτές έγινε σχετικά πρόσφατα, στα σοβιετικά χρόνια.","wiki_en":"Snow Maiden"},{"name":"Ντεντ Μορόζ","emoji":"🎅","meta":["ρωσική λαϊκή παράδοση","ο μάγος της Πρωτοχρονιάς"],"description":"Καλόκαρδος γέροντας με άσπρα γένια, μακριά γούνα και ραβδί, που φέρνει δώρα στα παιδιά την Πρωτοχρονιά και, κατά τον θρύλο, ζει στο Βελίκι Ουστιούγκ. Αρχικά η μορφή προερχόταν από ένα αυστηρό πνεύμα του χειμώνα και της παγωνιάς και με τον καιρό γλύκανε σε γενναιόδωρο δωρητή.","fact":"Επίσημη κατοικία του Ντεντ Μορόζ στη Ρωσία θεωρείται η πόλη Βελίκι Ουστιούγκ, στην περιφέρεια της Βόλογκντα.","wiki_en":"Ded Moroz"},{"name":"Μοϊντοντίρ","emoji":"🧼","meta":["παραμύθι του Κορνέι Τσουκόφσκι","ο διοικητής των νιπτήρων","1923"],"description":"Ένας ζωντανός νιπτήρας που μιλά, «αρχηγός των νιπτήρων και διοικητής των σφουγγαριών», ο οποίος κυνηγά ένα βρόμικο ατημέλητο αγόρι ώσπου αυτό δέχεται τελικά να πλυθεί. Ένα χαρούμενο και διδακτικό έμμετρο παραμύθι, που μαθαίνει στα παιδιά να αγαπούν την καθαριότητα.","fact":"Τους στίχους του Μοϊντοντίρ για την ανάγκη του πλυσίματος τους λένε ακόμη γονείς στη Ρωσία, μαθαίνοντας υγιεινή στα παιδιά.","wiki_en":"Moydodyr","wiki_ru":"Мойдодыр"},{"name":"Η Κατσαρίδα-Τέρας","emoji":"🪳","meta":["παραμύθι του Κορνέι Τσουκόφσκι","μουστακαλής γίγαντας τύραννος","1923"],"description":"Μια κοινή κατσαρίδα, που με τα φοβερά της μουστάκια και τις φωνές της σκορπά πανικό σε όλα τα ζώα του δάσους, ώσπου ένα μικροσκοπικό σπουργίτι την καταπίνει ολόκληρη. Το έμμετρο παραμύθι διαβάζεται συχνά ως πνευματώδης παραβολή για το πώς ο φουσκωμένος φόβος κάνει τεράστια μια μικρή απειλή.","fact":"Πολλοί μελετητές διαβάζουν το παραμύθι του Τσουκόφσκι ως πολιτική σάτιρα της προσωποπαγούς λατρείας ενός δικτάτορα.","wiki_en":"Tarakanishche","wiki_ru":"Тараканище"},{"name":"Η φλύαρη μύγα","emoji":"🪰","meta":["παραμύθι του Κορνέι Τσουκόφσκι","η μύγα που έχει γενέθλια","1924"],"description":"Μια στολισμένη μύγα, που βρίσκει ένα κέρμα στον δρόμο και στρώνει πλούσιο τσάι για τους καλεσμένους του δάσους, ώσπου την διακόπτει η επίθεση μιας κακιάς αράχνης. Τρέχει να τη σώσει ένα θαρραλέο κουνουπάκι με το σπαθί γυμνό.","fact":"Τους πρώτους στίχους, για τη μύγα που περπατά στο λιβάδι και βρίσκει ένα κέρμα, τους απαγγέλλουν από μνήμη οι περισσότεροι Ρώσοι.","wiki_en":"Mukha-Tsokotukha","wiki_ru":"Муха-Цокотуха"},{"name":"Έλι από τον «Μάγο της Σμαραγδένιας Πόλης»","emoji":"🌪️","meta":["Αλεξάντρ Βόλκοφ","κορίτσι από το Κάνσας","1939"],"description":"Κορίτσι που ένας ανεμοστρόβιλος το παρασύρει μαζί με το σπιτάκι του σε μια μαγική χώρα, όπου πρέπει να ακολουθήσει τον δρόμο με τα κίτρινα τούβλα για να βρει τρόπο να γυρίσει σπίτι. Στη διαδρομή αποκτά πιστούς φίλους, που ο καθένας ψάχνει αυτό που του λείπει.","fact":"Το βιβλίο του Βόλκοφ συγχέεται συχνά με το πρωτότυπο του Φρανκ Μπάουμ για την Αμερικανίδα Ντόροθι, αν και οι πλοκές απέκλιναν με τον καιρό.","wiki_en":"The Wizard of the Emerald City","wiki_ru":"Волшебник Изумрудного города"},{"name":"Τοτόσκα","emoji":"🐕","meta":["Αλεξάντρ Βόλκοφ","ο πιστός σκυλάκος της Έλι","1939"],"description":"Μικρό αλλά θαρραλέο σκυλάκι, που ο ανεμοστρόβιλος το μεταφέρει μαζί με την κυρά του στη μαγική χώρα και δεν μένει ούτε βήμα πίσω της σε όλο τον μακρύ δρόμο. Παρά το μέγεθός του, δείχνει πολλές φορές αληθινό κουράγιο μπροστά σε πραγματικούς κινδύνους.","fact":"Σε αντίθεση με τον Τότο του Φρανκ Μπάουμ, ο Τοτόσκα του Βόλκοφ αρχίζει να μιλά ανθρώπινα μόλις φτάνει στη Μαγική Χώρα.","wiki_en":"The Wizard of the Emerald City","wiki_ru":"Волшебник Изумрудного города"},{"name":"Το Σκιάχτρο","emoji":"🌾","meta":["Αλεξάντρ Βόλκοφ","αχυρένιος σοφός","1939"],"description":"Σκιάχτρο παραγεμισμένο με άχυρο και κρεμασμένο σε ένα παλούκι στη μέση ενός χωραφιού, που ζωντανεύει και ακολουθεί την Έλι με την ελπίδα να αποκτήσει αληθινό μυαλό. Παρά τις διαρκείς αμφιβολίες για την εξυπνάδα του, βρίσκει ξανά και ξανά τις πιο εύστοχες λύσεις.","fact":"Στην πορεία της ιστορίας το Σκιάχτρο γίνεται κυβερνήτης της Σμαραγδένιας Πόλης, αποδεικνύοντας ότι είχε εξυπνάδα από την αρχή.","wiki_en":"The Wizard of the Emerald City","wiki_ru":"Страшила Мудрый"},{"name":"Ο Σιδερένιος Ξυλοκόπος","emoji":"🪓","meta":["Αλεξάντρ Βόλκοφ","άνθρωπος από σίδερο","1939"],"description":"Κάποτε ένας συνηθισμένος ξυλοκόπος, που εξαιτίας μαγείας αντικατέστησε σταδιακά όλα τα μέλη του σώματός του με σιδερένια και μαζί τους έχασε την καρδιά του. Ακολουθεί την Έλι με την ελπίδα να μπορέσει ξανά να νιώσει και να αγαπήσει, δείχνοντας εξαιρετική καλοσύνη στους αδύναμους.","fact":"Ο Σιδερένιος Ξυλοκόπος φοβάται πάνω απ' όλα να σκουριάσει στη βροχή και κουβαλά πάντα μαζί του ένα λαδικό.","wiki_en":"The Wizard of the Emerald City","wiki_ru":"Железный Дровосек"},{"name":"Το Δειλό Λιοντάρι","emoji":"🦁","meta":["Αλεξάντρ Βόλκοφ","διστακτικός βασιλιάς των ζώων","1939"],"description":"Βασιλιάς των ζώων του δάσους, ρωμαλέος στην όψη, που στην πραγματικότητα φοβάται πανικόβλητα τα πάντα και ονειρεύεται να αποκτήσει αληθινό κουράγιο. Ακολουθεί το ταξίδι της Έλι προς τη Σμαραγδένια Πόλη και αποδεικνύει ότι η ανδρεία είναι πράξη παρά τον φόβο, όχι απουσία του.","fact":"Παρά το παρατσούκλι, το Δειλό Λιοντάρι σώζει πολλές φορές τους φίλους του, παλεύοντας με αληθινά επικίνδυνα πλάσματα.","wiki_en":"The Wizard of the Emerald City","wiki_ru":"Волшебник Изумрудного города"},{"name":"Ο θείος Φιόντορ","emoji":"🏡","meta":["Εντουάρντ Ουσπένσκι","αξιοθαύμαστα ανεξάρτητο αγόρι","1974"],"description":"Αγόρι πολύ πιο ανεξάρτητο απ' όσο δείχνει η ηλικία του, που πηγαίνει να ζήσει στο χωριό Προστοκβάσινο μαζί με τον γάτο Ματρόσκιν που μιλά και τον σκύλο Σάρικ, προς μεγάλη έκπληξη των γονιών του. Κρατά το νοικοκυριό, αποκτά αγελάδα και τα βγάζει πέρα με τους δύσκολους χαρακτήρες των ζώων του.","fact":"Το διάσημο κινούμενο σχέδιο «Τρεις από το Προστοκβάσινο», βασισμένο σε αυτό το βιβλίο, βγήκε το 1978 και είχε δύο συνέχειες.","wiki_en":"Uncle Fyodor, His Dog, and His Cat","wiki_ru":"Дядя Фёдор, пёс и кот"},{"name":"Ο σκύλος Σάρικ","emoji":"🐶","meta":["Προστοκβάσινο","σκύλος του κυνηγιού","1974"],"description":"Αγαθός σκύλος κυνηγιού, που άφησε την πόλη μαζί με τον θείο Φιόντορ και εγκαταστάθηκε στο χωριό Προστοκβάσινο. Ονειρεύεται να αποκτήσει καραμπίνα και να κυνηγήσει, ενώ τσακώνεται συνεχώς για ψύλλου πήδημα με τον λογικό γάτο Ματρόσκιν.","fact":"Στο κινούμενο σχέδιο ο Σάρικ αποκτά αντί για αληθινό όπλο μια φωτογραφική μηχανή και κυνηγά τα ζώα τραβώντας τους φωτογραφίες.","wiki_en":"Uncle Fyodor, His Dog, and His Cat","wiki_ru":"Шарик (Простоквашино)"},{"name":"Ο ταχυδρόμος Πέτσκιν","emoji":"📮","meta":["Προστοκβάσινο","ταχυδρόμος του χωριού","1974"],"description":"Σχολαστικός και καχύποπτος ταχυδρόμος του χωριού, που στην αρχή συγκρούεται με τους νέους κατοίκους του Προστοκβάσινο επειδή το αγόρι δεν έχει χαρτιά. Με τον καιρό μαλακώνει και γίνεται καλός φίλος του θείου Φιόντορ και των ζώων του.","fact":"Παίρνοντας δώρο ένα ποδήλατο, ο Πέτσκιν λέει μια περίφημη ατάκα: «Γιατί ήμουν τόσο κακός πριν; Επειδή δεν είχα ποδήλατο».","wiki_en":"Uncle Fyodor, His Dog, and His Cat","wiki_ru":"Почтальон Печкин"},{"name":"Κούζια, το ξωτικό του σπιτιού","emoji":"🧹","meta":["παραμύθι και κινούμενα σχέδια","σκανταλιάρικο σπιτικό ξωτικό"],"description":"Μαλλιαρό και καλόκαρδο σπιτικό ξωτικό, που ζει πίσω από τη σόμπα και φροντίζει για την τάξη στο σπίτι, ώσπου το μετακομίζουν σε ένα σύγχρονο διαμέρισμα. Γκρινιάρικο και προληπτικό, δυσκολεύεται με τα νέα ήθη, αλλά δένεται ειλικρινά με ένα κορίτσι, τη Νατάσα.","fact":"Στα κινούμενα σχέδια ο Κούζια έχει έναν γηραιότερο μέντορα, το παλιό ξωτικό Ναφάνια, στον οποίο τρέχει με κάθε του στενοχώρια.","wiki_en":"Domovyonok Kuzya","wiki_ru":"Домовёнок Кузя"},{"name":"Ο Λαγός από το «Nu, Pogodi!»","emoji":"🐰","meta":["«Nu, Pogodi!»","πανούργος λαγός","1969"],"description":"Ο γοητευτικός και επινοητικός λαγός, ο βασικός στόχος του άτυχου Λύκου στη διάσημη σοβιετική σειρά κινουμένων. Ξεφεύγει ξανά και ξανά από την καταδίωξη χρησιμοποιώντας την εξυπνάδα του και όχι τη δύναμη. Από τους πιο αναγνωρίσιμους και αγαπημένους ήρωες του σοβιετικού κινουμένου σχεδίου.","fact":"Παρά τον τίτλο της σειράς, που είναι η απειλή του Λύκου, ο Λαγός σχεδόν πάντα βγαίνει νικητής.","wiki_en":"Nu, pogodi!","wiki_ru":"Ну, погоди!"},{"name":"Το Γουρουνάκι","emoji":"🐷","meta":["«Γουίνι το Αρκουδάκι»","δειλό γουρουνάκι","1926"],"description":"Μικροσκοπικό και δειλό γουρουνάκι, ο καλύτερος φίλος του Γουίνι, που ανησυχεί για τα πάντα αλλά εμφανίζεται πάντα όταν οι φίλοι του το χρειάζονται. Παρά τον φοβητσιάρη χαρακτήρα του, δείχνει πολλές φορές αληθινό κουράγιο για όσους αγαπά.","fact":"Στο αγγλικό πρωτότυπο ο ήρωας λέγεται Piglet, που σημαίνει κυριολεκτικά «γουρουνάκι».","wiki_en":"Piglet (Winnie-the-Pooh)"},{"name":"Ο γαϊδαράκος Ίγιορ","emoji":"🎈","meta":["«Γουίνι το Αρκουδάκι»","μελαγχολικός γαϊδαράκος","1926"],"description":"Ο αιώνια κατηφής και απαισιόδοξος γαϊδαράκος του Δάσους των Εκατό Στρεμμάτων, που η ουρά του όλο και πάει να ξεκολλήσει. Παρά τα μαύρα προαισθήματα για το καθετί, εκτιμά ειλικρινά την προσοχή των φίλων του, ειδικά στα γενέθλιά του.","fact":"Σε γνωστό κεφάλαιο οι φίλοι οργανώνουν τα γενέθλια του Ίγιορ, και τα δώρα του είναι ένα σκασμένο μπαλόνι και ένα άδειο βάζο μελιού.","wiki_en":"Eeyore"},{"name":"Ο Κούνελος","emoji":"🥕","meta":["«Γουίνι το Αρκουδάκι»","πολυάσχολος γείτονας","1926"],"description":"Ο δραστήριος και λίγο γκρινιάρης κάτοικος του Δάσους των Εκατό Στρεμμάτων, που καμαρώνει για τον λαχανόκηπο και την τάξη στη φωλιά του. Οργανώνει συνεχώς δουλειές για τους φίλους του, χωρίς πάντα να λογαριάζει τι θέλουν οι ίδιοι.","fact":"Στη φωλιά του Κούνελου, τη στενή, σφηνώνει ο Γουίνι, αφού έχει φάει πολύ μέλι πριν πάρει τον δρόμο της επιστροφής.","wiki_en":"Rabbit (Winnie-the-Pooh)"},{"name":"Τσίκο","emoji":"🦔","meta":["«KikoRiki»","διαβασμένος σκαντζόχοιρος","2004"],"description":"Λογικός και διαβασμένος σκαντζόχοιρος, που εκτιμά τις ήσυχες φιλοσοφικές συζητήσεις και ένα καλό βιβλίο πιο πολύ από τις θορυβώδεις περιπέτειες. Από τους πιο ήρεμους και συνετούς ήρωες της σειράς, στέκεται συχνά η φωνή της λογικής μέσα σε μια παρέα πιο παρορμητικών φίλων.","fact":"Ο σκαντζόχοιρος και ο ακράτητος λαγός Κρας είναι το πιο γνωστό δίδυμο φίλων της σειράς: πολλά επεισόδια στηρίζονται στην αντίθεσή τους.","wiki_en":"Smeshariki","wiki_ru":"Ёжик в тумане"},{"name":"Ρόζα","emoji":"💅","meta":["«KikoRiki»","φιλάρεσκο γουρουνάκι","2004"],"description":"Ρόδινο φιλάρεσκο γουρουνάκι, που λατρεύει τα ρούχα, τα καλλυντικά και την προσοχή όλων, αλλά νοιάζεται ειλικρινά για τους φίλους της. Πίσω από τη φαινομενική ματαιοδοξία κρύβεται μια ευαίσθητη και καλή φύση. Από τις πιο έντονες ηρωίδες της σειράς.","fact":"Είναι μία από τις δύο βασικές γυναικείες μορφές της σειράς· η άλλη, η συνετή κουκουβάγια Όλγα, είναι πολύ μεγαλύτερη και πιο ήρεμη.","wiki_en":"Smeshariki","wiki_ru":"Нюша"},{"name":"Γουόλι","emoji":"🐑","meta":["«KikoRiki»","μελαγχολικός ποιητής κριάρι","2004"],"description":"Σγουρό κριάρι με καλλιτεχνική ψυχή, με τάση στη μελαγχολία, στα ποιήματα και στις ρομαντικές συγκινήσεις για το παραμικρό. Χάνεται συχνά στα σύννεφα των φαντασιώσεών του και μένει ο πιο λυρικός ήρωας της σειράς. Η ευαισθησία του γίνεται αφορμή για καλοπροαίρετα πειράγματα.","fact":"Ο Γουόλι γράφει συνεχώς ποιήματα, αλλά σχεδόν ποτέ δεν είναι ευχαριστημένος με τους στίχους του.","wiki_en":"Smeshariki"},{"name":"Μπάρι","emoji":"🐻","meta":["«KikoRiki»","νοικοκύρης αρκούδος κηπουρός","2004"],"description":"Καλόκαρδος και εργατικός αρκούδος, που αφιερώνει κάθε ελεύθερη ώρα στον λαχανόκηπο και στον κήπο του. Αργοκίνητος, συνετός και πάντα πρόθυμος να μοιραστεί τη σοδειά με τους φίλους του. Από τους πιο ισορροπημένους και νοικοκυρεμένους ήρωες της σειράς.","fact":"Το ρωσικό όνομά του, Κοπάτιτς, βγαίνει από το ρήμα «σκάβω», που είναι ακριβώς αυτό που κάνει όλη μέρα.","wiki_en":"Smeshariki","wiki_ru":"Копатыч"},{"name":"Λουίτζι","emoji":"💚","meta":["Nintendo","ο μικρός αδελφός υδραυλικός","1983"],"description":"Ο πιο δειλός και νευρικός δίδυμος μικρότερος αδελφός του Μάριο, υδραυλικός και αυτός, που μπλέκει διαρκώς στη διάσωση του Βασιλείου των Μανιταριών. Φοράει πράσινα αντί για τα κόκκινα του αδελφού του και ξεχώρισε κυρίως κυνηγώντας φαντάσματα στα παιχνίδια με το στοιχειωμένο αρχοντικό.","fact":"Για τα τριάντα χρόνια από την πρώτη του εμφάνιση, η Nintendo ανακήρυξε το 2013 «Χρονιά του Λουίτζι» και του αφιέρωσε αρκετά παιχνίδια.","wiki_en":"Luigi","wiki_ru":"Луиджи"},{"name":"Πριγκίπισσα Πιτς","emoji":"👑","meta":["Nintendo","ηγεμόνας του Βασιλείου των Μανιταριών","1985"],"description":"Η ηγεμόνας του Βασιλείου των Μανιταριών, που η απαγωγή της από τον κακό Μπάουζερ γίνεται ξανά και ξανά η αφετηρία των περιπετειών του Μάριο. Παρά την εικόνα του αιώνιου θύματος, σε ορισμένα παιχνίδια παίρνει η ίδια όπλα και δυνάμεις και αποδεικνύεται ευκίνητη και επινοητική.","fact":"Σε μερικά παιχνίδια της σειράς η πριγκίπισσα Πιτς μπορεί να αιωρείται για λίγο, χρησιμοποιώντας το φόρεμά της ως αλεξίπτωτο.","wiki_en":"Princess Peach"},{"name":"Μπάουζερ","emoji":"🐢","meta":["Nintendo","βασιλιάς των χελωνών Κούπα","1985"],"description":"Ο πελώριος κερασφόρος βασιλιάς της φυλής των χελωνών Κούπα, που από παιχνίδι σε παιχνίδι απάγει την πριγκίπισσα Πιτς και προσπαθεί να καταλάβει το Βασίλειο των Μανιταριών. Ξερνά φωτιά, διοικεί στρατιά υποτακτικών και διαθέτει δικό του ιπτάμενο στόλο.","fact":"Παρά την εικόνα του κακού, σε μερικά παιχνίδια ο Μπάουζερ γίνεται προσωρινός σύμμαχος του Μάριο απέναντι σε ακόμη πιο επικίνδυνους εχθρούς.","wiki_en":"Bowser (character)"},{"name":"Λινκ","emoji":"🛡️","meta":["The Legend of Zelda","ο σιωπηλός ήρωας του Χάιρουλ","1986"],"description":"Σιωπηλός νέος με πράσινο χιτώνιο, που από παιχνίδι σε παιχνίδι καλείται από τη μοίρα να σώσει το βασίλειο του Χάιρουλ από τον σκοτεινό άρχοντα Γκάνον. Κρατά το θρυλικό Σπαθί του Δασκάλου, ένα ξωτικένιο τόξο και δεκάδες εργαλεία για πονηρούς γρίφους.","fact":"Ο Λινκ δεν λέει ποτέ ατάκα δυνατά: σχεδόν σε όλη την ιστορία της σειράς παραμένει εντελώς άφωνος ήρωας.","wiki_en":"Link (The Legend of Zelda)"},{"name":"Πριγκίπισσα Ζέλντα","emoji":"🔺","meta":["The Legend of Zelda","πριγκίπισσα του Χάιρουλ","1986"],"description":"Η σοφή πριγκίπισσα του βασιλείου του Χάιρουλ, φύλακας του κομματιού της Τριδύναμης που αντιστοιχεί στη σοφία, με μοίρα που σε κάθε παιχνίδι δένεται με την ιστορία του Λινκ. Από τίτλο σε τίτλο εμφανίζεται αλλιώς, από αιχμάλωτο θύμα ως αυτόνομη πολεμίστρια.","fact":"Όλη η θρυλική σειρά παιχνιδιών είναι ονομασμένη από την πριγκίπισσα Ζέλντα, αν και ο παίκτης σχεδόν πάντα ελέγχει τον Λινκ.","wiki_en":"Princess Zelda"},{"name":"Master Chief","emoji":"🪖","meta":["Halo","υπερστρατιώτης Σπαρτιάτης","2001"],"description":"Ο Τζον-117, υπερστρατιώτης του μυστικού προγράμματος «Σπαρτιάτης», που πολεμά με βαριά μαχητική πανοπλία εναντίον της εξωγήινης συμμαχίας των Covenant. Λιγομίλητος, πειθαρχημένος και σχεδόν ποτέ χωρίς το κράνος του δημόσια.","fact":"Το πραγματικό πρόσωπο του Master Chief κάτω από το κράνος δεν δείχνεται σχεδόν ποτέ σε κοντινό πλάνο σε όλη τη σειρά.","wiki_en":"Master Chief (Halo)"},{"name":"Duke Nukem","emoji":"🕶️","meta":["Duke Nukem","αυτάρεσκος ήρωας δράσης","1991"],"description":"Μυώδης ήρωας βιντεοπαιχνιδιών με χτενισμένα ξανθά μαλλιά, σκούρα γυαλιά και ανεξάντλητο απόθεμα αυτάρεσκων ατακών. Πολεμά εξωγήινους εισβολείς, σπάζοντας παράλληλα τον τέταρτο τοίχο με παρωδίες των ταινιών δράσης του 1980. Από τις πιο καρικατουρίστικες φιγούρες του gaming.","fact":"Η περίφημη ατάκα του «It's time to kick ass and chew bubble gum» είναι από τις πιο πολυθρύλητες στην ιστορία των βιντεοπαιχνιδιών.","wiki_en":"Duke Nukem (character)"},{"name":"Πράκτορας 47","emoji":"🎱","meta":["Hitman","κλωνοποιημένος εκτελεστής","2000"],"description":"Φαλακρός επαγγελματίας δολοφόνος με χαρακτηριστικό μπάρκοντ στο πίσω μέρος του κεφαλιού, που μεγάλωσε σε μυστικό εργαστήριο ως αποτέλεσμα γενετικών πειραμάτων. Εκτελεί τις παραγγελίες της Υπηρεσίας με παγερή ψυχραιμία, μεταμφιεζόμενος αριστοτεχνικά στους πιο διαφορετικούς ανθρώπους.","fact":"Ο αριθμός 47 είναι απλώς τα τελευταία ψηφία του μακριού μπάρκοντ που είναι τατουάζ στο κεφάλι του.","wiki_en":"Agent 47"},{"name":"Κράτος","emoji":"⚔️","meta":["God of War","θεός του πολέμου και εκδικητής","2005"],"description":"Πρώην Σπαρτιάτης πολεμιστής, που με δόλο τον έκαναν να σκοτώσει την οικογένειά του και από τότε ξεσπά την οργή του στους θεούς του Ολύμπου. Μάχεται με δύο λεπίδες του χάους, αλυσοδεμένες στα χέρια του. Από τους πιο ισχυρούς και αναγνωρίσιμους ήρωες της βιομηχανίας των παιχνιδιών.","fact":"Η στάχτη της νεκρής οικογένειάς του κόλλησε για πάντα στο δέρμα του Κράτου και το έκανε λευκό: γι' αυτό τον λένε Φάντασμα της Σπάρτης.","wiki_en":"Kratos (God of War)"},{"name":"Αλταΐρ","emoji":"🦅","meta":["Assassin's Creed","ασασίνος της Ιερουσαλήμ","2007"],"description":"Αρχιασασίνος του τέλους του 12ου αιώνα, που δρα στα χρόνια της Γ΄ Σταυροφορίας και κυνηγά εννέα ισχυρούς Ναΐτες των Αγίων Τόπων. Κρατά την κρυφή λεπίδα και έχει το θρυλικό χάρισμα της αετίσιας όρασης. Ο ήρωας του πρώτου Assassin's Creed και σύμβολο όλου του φραντσάιζ.","fact":"Ο Αλταΐρ ήταν ο πρώτος ήρωας της σειράς, και ο παίκτης ζει τις αναμνήσεις του μέσα από τη μηχανή «Animus», με τα μάτια ενός μακρινού απογόνου.","wiki_en":"Altaïr Ibn-La'Ahad"},{"name":"Έτσιο Αουντιτόρε","emoji":"🎭","meta":["Assassin's Creed","ασασίνος της Αναγέννησης","2009"],"description":"Νέος Φλωρεντινός αριστοκράτης της Αναγέννησης, που μετά μια τραγωδία στην οικογένειά του αφιερώνει τη ζωή του στο Τάγμα των Ασασίνων και στον πόλεμο κατά των Ναϊτών. Περνά από τον εκδικητικό νέο στον σοφό μέντορα μιας νέας γενιάς δολοφόνων.","fact":"Η ιστορία του Έτσιο απλώνεται σε τρία ολόκληρα παιχνίδια της σειράς, από τα νεανικά ως τα ώριμα χρόνια του.","wiki_en":"Ezio Auditore da Firenze"},{"name":"Άρθουρ Μόργκαν","emoji":"🤠","meta":["Red Dead Redemption","παράνομος καουμπόι","2018"],"description":"Έμπειρο μέλος της συμμορίας του Ντατς βαν ντερ Λίντε, που δρα στην Αμερική του 1899, στο λυκόφως της Άγριας Δύσης. Συνδυάζει τη σκληράδα του μισθοφόρου με έναν δικό του εσωτερικό κώδικα τιμής. Από τους πιο βαθιά γραμμένους χαρακτήρες των σύγχρονων βιντεοπαιχνιδιών.","fact":"Το ημερολόγιο του Άρθουρ Μόργκαν, που ο παίκτης συμπληρώνει καθώς παίζει, θεωρήθηκε από τους καλύτερους τρόπους να αποκαλυφθεί ένας χαρακτήρας.","wiki_en":"Arthur Morgan"},{"name":"Τζόελ","emoji":"🎸","meta":["The Last of Us","επιζών λαθρέμπορος","2013"],"description":"Σκληραγωγημένος λαθρέμπορος, που επιβιώνει σε μια Αμερική είκοσι χρόνια μετά την έναρξη μιας επιδημίας που μετατρέπει τους ανθρώπους σε μολυσμένα τέρατα. Αναλαμβάνει να συνοδεύσει ένα κορίτσι εφηβικής ηλικίας μέσα από επικίνδυνη περιοχή, κάτι που τον αναγκάζει να ανοιχτεί ξανά συναισθηματικά.","fact":"Ο Τζόελ έμαθε κιθάρα σαν παιδί, και το όργανο επανέρχεται ως σημαντική λεπτομέρεια της ιστορίας του μέσα στο παιχνίδι.","wiki_en":"Joel (The Last of Us)"},{"name":"Έλι από το «The Last of Us»","emoji":"🦋","meta":["The Last of Us","έφηβη με ανοσία","2013"],"description":"Δεκατετράχρονο κορίτσι, που μεγάλωσε στον κόσμο μετά την πανδημία και διαθέτει το σπανιότερο αγαθό: ανοσία στη μόλυνση. Κοφτερή στη γλώσσα και επινοητική, ενηλικιώνεται γρήγορα κάτω από το βάρος όσων ζει σε ένα μακρύ ταξίδι μέσα από μια επικίνδυνη χώρα.","fact":"Το τατουάζ με τον σκόρο και τα φύλλα φτέρης, που αποκτά στη συνέχεια της ιστορίας, κρύβει το σημάδι από δάγκωμα μολυσμένου.","wiki_en":"Ellie (The Last of Us)"},{"name":"Γκόρντον Φρίμαν","emoji":"🥽","meta":["Half-Life","φυσικός επιστήμονας","1998"],"description":"Νέος ερευνητής φυσικός στο συγκρότημα «Μπλακ Μέσα», που βρίσκεται τυχαία στο επίκεντρο μιας καταστροφής, η οποία ανοίγει πύλη σε έναν κόσμο εχθρικών εξωγήινων. Είναι τόσο λιγομίλητος που σε όλη τη σειρά δεν λέει ούτε μία ατάκα. Τα γυαλιά και ο λοστός του έγιναν σύμβολα του gaming.","fact":"Κατά τη βιογραφία του στο παιχνίδι, ο Γκόρντον Φρίμαν είναι διδάκτορας θεωρητικής φυσικής με πτυχίο από το MIT.","wiki_en":"Gordon Freeman"},{"name":"Σαμ Φίσερ","emoji":"🌃","meta":["Splinter Cell","πράκτορας μυστικών υπηρεσιών","2002"],"description":"Βετεράνος των ειδικών δυνάμεων, που έγινε μυστικός πράκτορας μιας υπηρεσίας η οποία δρα εκτός νόμου για χάρη της εθνικής ασφάλειας. Δεξιοτέχνης της αθόρυβης διείσδυσης, χρησιμοποιεί τις σκιές και προηγμένο εξοπλισμό, με πρώτα τα αναγνωρίσιμα γυαλιά νυχτερινής όρασης.","fact":"Η χαρακτηριστική πράσινη λάμψη τριών κουκκίδων από τα γυαλιά νυχτερινής όρασης του Σαμ Φίσερ έγινε οπτικό σύμβολο του είδους.","wiki_en":"Sam Fisher","wiki_ru":"Сэм Фишер (Splinter Cell)"},{"name":"Solid Snake","emoji":"📦","meta":["Metal Gear","διαβρωτής των ειδικών δυνάμεων","1987"],"description":"Θρυλικός πράκτορας, που διεισδύει μόνος σε εχθρικές βάσεις για να σταματήσει την απειλή ενός πυρηνικού βαδίζοντος άρματος, του «Metal Gear». Δεξιοτέχνης της μεταμφίευσης και της αθόρυβης κίνησης, μπορεί να κρύβεται ώρες στις πιο απρόσμενες γωνιές.","fact":"Το να κρύβεται από τους εχθρούς κάτω από ένα κοινό χαρτόκουτο είναι το σήμα κατατεθέν και παραδόξως αποτελεσματικό κόλπο του.","wiki_en":"Solid Snake"},{"name":"Ντάντε από το Devil May Cry","emoji":"😈","meta":["Devil May Cry","ημιδαίμονας κυνηγός","2001"],"description":"Μισός άνθρωπος και μισός δαίμονας, κληρονόμησε από τον δαίμονα πατέρα του απάνθρωπη δύναμη και έγινε κυνηγός άλλων δαιμόνων για τα λεφτά και για τη διασκέδασή του. Συνδυάζει αριστοτεχνικό σπαθί και πυροβόλα με επιδεικτική, θρασεία παλικαριά.","fact":"Ο χαρακτηριστικός βυσσινί μανδύας και τα λευκά μαλλιά του Ντάντε έγιναν σήμα κατατεθέν του ήρωα από το πρώτο παιχνίδι.","wiki_en":"Dante (Devil May Cry)"},{"name":"Bayonetta","emoji":"🔫","meta":["Bayonetta","μάγισσα που κυνηγά αγγέλους","2009"],"description":"Ισχυρή μάγισσα με εφαρμοστή στολή φτιαγμένη από τα δικά της μαλλιά, που μάχεται τις δυνάμεις των ουρανών με τέσσερα πιστόλια ταυτόχρονα. Συνδυάζει χαριτωμένα ακροβατικά με καταστροφική μαχητική ισχύ και ειρωνικό αίσθημα στιλ.","fact":"Και τα τέσσερα πιστόλια τα κρατά μαζί: δύο στα χέρια και δύο ακόμη στερεωμένα στα τακούνια της.","wiki_en":"Bayonetta (character)"},{"name":"Νέιθαν Ντρέικ","emoji":"🗺️","meta":["Uncharted","κυνηγός θησαυρών","2007"],"description":"Γοητευτικός τυχοδιώκτης και απόγονος διάσημου θαλασσοπόρου, που κυνηγά σε όλο τον κόσμο θρυλικούς θησαυρούς και χαμένες πόλεις. Συνδυάζει το πνεύμα ενός ήρωα περιπετειώδους ταινίας του Χόλιγουντ με την ευλυγισία ακροβάτη και την ευστοχία σκοπευτή.","fact":"Οι δημιουργοί του παιχνιδιού παραδέχτηκαν ότι εμπνεύστηκαν από τον Ιντιάνα Τζόουνς για τον χαρακτήρα και τις περιπέτειες του Νέιθαν Ντρέικ.","wiki_en":"Nathan Drake"},{"name":"Βετζίτα","emoji":"💥","meta":["Dragon Ball","περήφανος πρίγκιπας των Σάιαν","1988"],"description":"Ο περήφανος πρίγκιπας της σχεδόν εξολοθρευμένης φυλής των Σάιαν, αρχικά εχθρός του ήρωα Σον Γκόκου και με τον καιρό βασικός αντίπαλος και σύμμαχός του. Έχει εμμονή να γίνει ο δυνατότερος πολεμιστής του σύμπαντος και δεν ανέχεται ποτέ την ανωτερότητα κανενός.","fact":"Ο άλλοτε εχθρός αποκτά τελικά οικογένεια στη Γη: γυναίκα του γίνεται η Μπούλμα και γιος του ο Τρανκς.","wiki_en":"Vegeta"},{"name":"Έντουαρντ Έλρικ","emoji":"⚗️","meta":["Fullmetal Alchemist","νεαρός αλχημιστής","2001"],"description":"Ταλαντούχος έφηβος αλχημιστής, που μετά από αποτυχημένη απόπειρα να αναστήσει τη νεκρή μητέρα του έχασε ένα χέρι και ένα πόδι, τα οποία αντικαταστάθηκαν με μηχανικά μέλη. Μαζί με τον μικρότερο αδελφό του ψάχνει τρόπο να ανακτήσουν τα σώματα που έχασαν.","fact":"Παρά τη νεαρή του ηλικία, ο Έντουαρντ Έλρικ φέρει τον επίσημο τίτλο του κρατικού αλχημιστή της Αμέστρις, σπάνια τιμή για έφηβο.","wiki_en":"Edward Elric"},{"name":"Ίτσιγκο Κουροσάκι","emoji":"👻","meta":["Bleach","μαθητής λυκείου και σινιγκάμι","2001"],"description":"Συνηθισμένος μαθητής λυκείου με την ικανότητα να βλέπει πνεύματα, που κληρονομεί τυχαία τις δυνάμεις ενός σινιγκάμι, του οδηγού των ψυχών στον άλλο κόσμο. Αρχίζει να πολεμά τα επικίνδυνα πνεύματα Χόλοου, προστατεύοντας ζωντανούς και νεκρούς από τις επιθέσεις τους.","fact":"Τα έντονα πορτοκαλί μαλλιά του Ίτσιγκο γίνονται από την αρχή της ιστορίας αφορμή για πειράγματα από τους άλλους ήρωες.","wiki_en":"Ichigo Kurosaki"},{"name":"Σάντζι","emoji":"🍳","meta":["One Piece","πειρατής μάγειρας","1997"],"description":"Ο κομψός μάγειρας του πειρατικού πληρώματος του Ψάθινου Καπέλου, που μάχεται αποκλειστικά με τα πόδια για να κρατά τα χέρια του ασφαλή για τη μαγειρική. Ιπποτικός με τις γυναίκες σχεδόν ως την καρικατούρα, ονειρεύεται να βρει τη θρυλική θάλασσα Ολ Μπλου.","fact":"Ο Σάντζι δεν χτυπά ποτέ γυναίκα, ως θέμα αρχής, ακόμη κι όταν εκείνη είναι ο άμεσος αντίπαλός του στη μάχη.","wiki_en":"Sanji (One Piece)"},{"name":"Ρορόνοα Ζόρο","emoji":"🗡️","meta":["One Piece","πειρατής ξιφομάχος","1997"],"description":"Πρώην κυνηγός επικηρυγμένων, που έγινε το πρώτο μέλος του πληρώματος του Ψάθινου Καπέλου και ονειρεύεται να γίνει ο δυνατότερος ξιφομάχος του κόσμου. Μάχεται με τρία σπαθιά ταυτόχρονα, σε δικό του στιλ, κρατώντας το ένα στα δόντια.","fact":"Παρά τη φήμη του φοβερού μαχητή, ο Ζόρο χάνεται τακτικά ακόμη και μέσα στο ίδιο του το πλοίο, κάτι που έγινε μόνιμο αστείο της σειράς.","wiki_en":"Roronoa Zoro"},{"name":"Σίντζι Ικάρι","emoji":"🤖","meta":["Neon Genesis Evangelion","πιλότος του ρομπότ Εύα","1995"],"description":"Δεκατετράχρονος έφηβος, που ο απόμακρος και απαιτητικός πατέρας του τον καλεί να πιλοτάρει ένα γιγάντιο βιομηχανικό ρομπότ, ένα Evangelion, για να υπερασπιστεί το Τόκιο-3 από τα μυστηριώδη πλάσματα που λέγονται Άγγελοι. Τον σκίζει η ανασφάλεια και ο φόβος της απόρριψης.","fact":"Το ψυχολογικό βάθος και η αμφισημία του Σίντζι Ικάρι έκαναν τη σειρά αντικείμενο ατελείωτων αναλύσεων και διαφωνιών.","wiki_en":"Shinji Ikari"},{"name":"Άσουκα Λάνγκλεϊ","emoji":"🔴","meta":["Neon Genesis Evangelion","πιλότος του ρομπότ Εύα","1995"],"description":"Φιλόδοξη και οξύθυμη νεαρή πιλότος του κόκκινου Evangelion, μεγαλωμένη από παιδί ως παιδί-θαύμα και με εμμονή να είναι η καλύτερη σε όλα. Πίσω από την επιδεικτική αυτοπεποίθηση κρύβει βαθιά ανασφάλεια και φόβο της μοναξιάς.","fact":"Η Άσουκα φτάνει στο Τόκιο-3 από τη Γερμανία, όπου την ετοίμαζαν ως πιλότο μαζί με το κόκκινο Eva-02 της.","wiki_en":"Asuka Langley Soryu"},{"name":"Αλαντίν","emoji":"🪔","meta":["«Χίλιες και μία νύχτες»","φτωχό αγόρι με το λυχνάρι","18ος αιώνας"],"description":"Επιτήδειος φτωχός του δρόμου σε μια ανατολίτικη πόλη, που βρίσκει τυχαία ένα μαγικό λυχνάρι με ένα τζίνι μέσα, το οποίο εκπληρώνει ευχές. Χρησιμοποιεί την ευκαιρία να αλλάξει τη μοίρα του για να κερδίσει την καρδιά μιας πριγκίπισσας και να δείξει ότι η καταγωγή δεν ορίζει την αξία ενός ανθρώπου.","fact":"Το αρχικό παραμύθι του Αλαντίν δεν προέρχεται από τα αραβικά χειρόγραφα: το πρόσθεσε στη συλλογή ένας Γάλλος μεταφραστής τον 18ο αιώνα.","wiki_en":"Aladdin"},{"name":"Το Τζίνι","emoji":"🧞","meta":["«Αλαντίν» της Disney","πανίσχυρο πνεύμα του λυχναριού","1992"],"description":"Πανίσχυρο πνεύμα, φυλακισμένο σε ένα μαγικό λυχνάρι και υποχρεωμένο να εκπληρώσει τρεις ευχές σε όποιον το ελευθερώσει. Συνδυάζει σχεδόν απεριόριστη μαγική δύναμη με την κούραση αιώνων στην υπηρεσία ξένων επιθυμιών. Το πιο αναγνωρίσιμο τζίνι της μαζικής κουλτούρας.","fact":"Οι κανόνες της μαγείας του απαγορεύουν να αναστήσει νεκρούς, να κάνει κάποιον να ερωτευτεί ή να δώσει παραπάνω ευχές από τις τρεις.","wiki_en":"Genie (Aladdin)"},{"name":"Γιασμίν","emoji":"🐯","meta":["«Αλαντίν»","πριγκίπισσα της Αγκράμπα","1992"],"description":"Η ανυπότακτη πριγκίπισσα του ανατολίτικου σουλτανάτου της Αγκράμπα, κουρασμένη από τις συμβάσεις του παλατιού και αποφασισμένη να διαλέγει μόνη της τη μοίρα και τον σύζυγό της. Έχει έναν ήμερο τίγρη, τον Ράτζα, και δεν φοβάται να βγει από το παλάτι για να δει την αληθινή ζωή της πόλης.","fact":"Η Γιασμίν ήταν από τις πρώτες πριγκίπισσες της Disney που εξεγέρθηκαν ανοιχτά κατά του γάμου από συνοικέσιο.","wiki_en":"Princess Jasmine"},{"name":"Μουλάν","emoji":"🗡️","meta":["«Μουλάν»","κοπέλα πολεμίστρια","1998"],"description":"Κόρη ενός Κινέζου πολεμιστή, που παίρνει κρυφά τη θέση του άρρωστου πατέρα της στον αυτοκρατορικό στρατό, μεταμφιεσμένη σε άντρα. Περνά τη σκληρή στρατιωτική εκπαίδευση ισότιμα με τους άντρες, αποδεικνύοντας ανδρεία και επινοητικότητα στη μάχη. Βασίζεται σε αρχαίο κινεζικό θρύλο.","fact":"Ο αληθινός θρύλος της πολεμίστριας Χούα Μουλάν, που ενέπνευσε την ταινία, λέγεται στην Κίνα πάνω από χίλια χρόνια.","wiki_en":"Mulan (Disney character)"},{"name":"Ποκαχόντας","emoji":"🍂","meta":["«Ποκαχόντας»","η κόρη του αρχηγού","1995"],"description":"Η ελευθερόφρων κόρη του αρχηγού της φυλής των Ποουχάταν, που η συνάντησή της με Άγγλους αποίκους γίνεται δοκιμασία κατανόησης ανάμεσα σε δύο εντελώς διαφορετικούς κόσμους. Είναι στενά δεμένη με τη φύση και με τη σοφία των προγόνων, που εκφράζεται στα οράματά της.","fact":"Η πραγματική Ποκαχόντας ήταν κόρη του αρχηγού Ποουχάταν, και η ζωή της εξελίχθηκε πολύ διαφορετικά απ' ό,τι στην ταινία.","wiki_en":"Pocahontas (Disney character)","wiki_ru":"Покахонтас"},{"name":"Μπελ","emoji":"📚","meta":["«Η Πεντάμορφη και το Τέρας»","διαβασμένη κοπέλα","1991"],"description":"Έξυπνη και διαβασμένη κοπέλα της γαλλικής επαρχίας, που νιώθει ξένη ανάμεσα στους γείτονές της επειδή αγαπά τα βιβλία και ονειρεύεται κάτι παραπάνω. Για να σώσει τον πατέρα της δέχεται να μείνει αιχμάλωτη στον πύργο ενός μαγεμένου Τέρατος.","fact":"Η Μπελ ήταν η πρώτη πριγκίπισσα της Disney της οποίας η ταινία προτάθηκε για Όσκαρ καλύτερης ταινίας της χρονιάς.","wiki_en":"Belle (Beauty and the Beast)","wiki_ru":"Белль (Дисней)"},{"name":"Το Τέρας","emoji":"🌹","meta":["«Η Πεντάμορφη και το Τέρας»","μαγεμένος πρίγκιπας","1991"],"description":"Κάποτε ένας κακομαθημένος νεαρός πρίγκιπας, που μια μάγισσα τον μεταμόρφωσε σε τέρας για την ψυχρότητα και την υπεροψία του. Πρέπει να μάθει να αγαπά αληθινά και να αγαπηθεί, προτού πέσει το τελευταίο πέταλο ενός μαγικού τριαντάφυλλου.","fact":"Οι σχεδιαστές του στούντιο συνέθεσαν τη μορφή του Τέρατος από χαρακτηριστικά πολλών ζώων: λιονταριού, αγριόχοιρου, γορίλα και αρκούδας.","wiki_en":"Beast (Beauty and the Beast)"},{"name":"Γκαστόν","emoji":"💪","meta":["«Η Πεντάμορφη και το Τέρας»","ναρκισσιστής κυνηγός","1991"],"description":"Ναρκισσιστής κυνηγός του χωριού, συνηθισμένος να παίρνει ό,τι θελήσει χάρη στη δύναμη και τη γοητεία του. Είναι σίγουρος ότι η Μπελ οφείλει απλώς να γίνει γυναίκα του και δεν καταλαβαίνει την αδιαφορία της για το πρόσωπό του.","fact":"Ο Γκαστόν ήταν από τους πρώτους κακούς της Disney που η απειλή τους δεν στηρίζεται στη μαγεία αλλά στην ανθρώπινη ματαιοδοξία και στη βία.","wiki_en":"Gaston (Beauty and the Beast)"},{"name":"Ούρσουλα","emoji":"🐙","meta":["«Η Μικρή Γοργόνα»","μάγισσα της θάλασσας","1989"],"description":"Δόλια μάγισσα-χταπόδι της θάλασσας, που ζει εξόριστη στην άκρη του υποβρύχιου βασιλείου και κλείνει ολέθριες συμφωνίες με αφελείς που της ζητούν χάρη. Παίρνει τη φωνή της γοργόνας Άριελ με αντάλλαγμα ανθρώπινα πόδια, κρύβοντας ύπουλο σχέδιο.","fact":"Η εμφάνιση και οι τρόποι της Ούρσουλα εμπνεύστηκαν σε μεγάλο βαθμό από τη διάσημη ντραγκ κουίν Divine.","wiki_en":"Ursula (The Little Mermaid)"},{"name":"Μέιτερ","emoji":"🚛","meta":["«Αυτοκίνητα»","αγαθό ρυμουλκό","2006"],"description":"Σκουριασμένο γεροντάκι ρυμουλκό από την ξεχασμένη κωμόπολη Ρέιντιεϊτορ Σπρινγκς, αγαθό και απίστευτα φλύαρο. Γίνεται ο καλύτερος φίλος του ξιπασμένου αγωνιστικού Λάιτνινγκ ΜακΚουίν και τον βοηθά να γίνει μέρος της μικρής κοινότητας της πόλης.","fact":"Ο Μέιτερ κινείται με την όπισθεν πιο γρήγορα απ' ό,τι τα περισσότερα αυτοκίνητα κινούνται κανονικά μπροστά.","wiki_en":"Cars (franchise)"},{"name":"Τζούντι Χοπς","emoji":"👮‍♀️","meta":["«Ζωούπολη»","κουνέλα αστυνομικός","2016"],"description":"Αποφασισμένη κουνέλα από ένα μικρό αγροτικό χωριό, που παρά τις αμφιβολίες όλων γίνεται η πρώτη κουνέλα αστυνομικός στη μεγάλη πόλη της Ζωούπολης. Έρχεται αντιμέτωπη με προκαταλήψεις και στερεότυπα για το τι μπορούν να κάνουν τα μικρά και φαινομενικά ακίνδυνα ζώα.","fact":"Η «Ζωούπολη» κέρδισε το Όσκαρ καλύτερης ταινίας κινουμένων σχεδίων, ενώ οι εισπράξεις της ξεπέρασαν το ένα δισεκατομμύριο δολάρια.","wiki_en":"Zootopia"},{"name":"Νικ Ουάιλντ","emoji":"🦊","meta":["«Ζωούπολη»","απατεώνας αλεπού","2016"],"description":"Γοητευτική αλεπού του δρόμου και απατεώνας, που ζει χρόνια από μικροκομπίνες και έχει συμβιβαστεί με τη φήμη του πονηρού, αναξιόπιστου θηρευτή. Η αναγκαστική συνεργασία με μια κουνέλα αστυνομικό τον κάνει να ξανασκεφτεί τη ζωή και τις δυνατότητές του.","fact":"Ο Νικ Ουάιλντ ονειρευόταν από παιδί να ανήκει στην κοινωνία, αλλά οι προκαταλήψεις των άλλων τον έσπρωξαν στον ρόλο του κυνικού απατεώνα.","wiki_en":"Zootopia"},{"name":"Άννα","emoji":"🧣","meta":["«Ψυχρά κι Ανάποδα»","πριγκίπισσα του Άρεντελ","2013"],"description":"Η χαρούμενη και παρορμητική μικρότερη πριγκίπισσα του βασιλείου του Άρεντελ, που μεγάλωσε χωριστά από τη μεγάλη της αδελφή Έλσα εξαιτίας του μαγικού της χαρίσματος. Ξεκινά ένα επικίνδυνο ταξίδι μέσα από χιονισμένα βουνά για να ξαναδεθεί με την αδελφή της και να σώσει το βασίλειο.","fact":"Οι άσπρες τούφες στα μαλλιά της Άννας εμφανίζονται αφού τη χτυπά η μαγεία του πάγου της ίδιας της αδελφής της.","wiki_en":"Anna (Frozen)","wiki_ru":"Анна (Дисней)"},{"name":"Όλαφ","emoji":"⛄","meta":["«Ψυχρά κι Ανάποδα»","ζωντανός χιονάνθρωπος","2013"],"description":"Αγαθός και απίστευτα καλόκαρδος χιονάνθρωπος, ζωντανεμένος από τη μαγεία της πριγκίπισσας Έλσα, που ονειρεύεται αφελώς να δει κάποτε καλοκαίρι. Δεν συνειδητοποιεί ότι η ζέστη είναι επικίνδυνη για το χιονένιο σώμα του, κάτι που γεννά διαρκή κωμική αντίθεση.","fact":"Ο Όλαφ λαχταρά στα σοβαρά να νιώσει τον καλοκαιρινό ήλιο πάνω του, χωρίς να καταλαβαίνει τι θα σήμαινε αυτό για εκείνον.","wiki_en":"Olaf (Frozen)"},{"name":"Ρος Γκέλερ","emoji":"🦕","meta":["«Friends»","παλαιοντολόγος άτυχος στον έρωτα","1994"],"description":"Επιστήμονας παλαιοντολόγος, ειδικός στους δεινόσαυρους, που η προσωπική του ζωή γίνεται μια σειρά από διαζύγια, ζήλιες και αμήχανες καταστάσεις μπροστά στα μάτια των φίλων του. Ένας από τους έξι κεντρικούς ήρωες της θρυλικής κωμικής σειράς.","fact":"Η ατάκα του Ρος «Είχαμε κάνει διάλειμμα!» έγινε από τις πιο αναγνωρίσιμες και πολυθρύλητες της σειράς.","wiki_en":"Ross Geller"},{"name":"Ρέιτσελ Γκριν","emoji":"☕","meta":["«Friends»","σερβιτόρα από πλούσια οικογένεια","1994"],"description":"Κακομαθημένη κόρη εύπορων γονιών, που το σκάει από τον ίδιο της τον γάμο και ξεκινά αυτόνομη ζωή ως σερβιτόρα στην καφετέρια Central Perk. Μπροστά στα μάτια των θεατών περνά από την ανήμπορη φασιονίστα στη σίγουρη επαγγελματία της μόδας.","fact":"Το κούρεμα της Ρέιτσελ, όπως το φορούσε η Τζένιφερ Άνιστον, έγινε από τα πιο αντιγραμμένα γυναικεία χτενίσματα της δεκαετίας του 1990.","wiki_en":"Rachel Green"},{"name":"Τσάντλερ Μπινγκ","emoji":"😏","meta":["«Friends»","ευφυολόγος υπάλληλος γραφείου","1994"],"description":"Σαρκαστικός υπάλληλος γραφείου με μια μυστηριώδη δουλειά, την οποία ούτε ο ίδιος μπορεί να εξηγήσει καθαρά στους φίλους του. Κρύβει την ανασφάλειά του πίσω από μια σχεδόν αδιάκοπη ροή ειρωνείας και αυτοσαρκασμού.","fact":"Ακόμη και οι φίλοι του Τσάντλερ μέσα στη σειρά παραδέχονται πολλές φορές ότι δεν κατάλαβαν ποτέ τι ακριβώς δουλειά κάνει.","wiki_en":"Chandler Bing"},{"name":"Μόνικα Γκέλερ","emoji":"🧽","meta":["«Friends»","τελειομανής σεφ","1994"],"description":"Σεφ με εμμονή στην καθαριότητα και την τάξη, που η απαιτητικότητά της απέναντι στον εαυτό της και στους άλλους έχει ρίζες σε μια δύσκολη παιδική ηλικία δίπλα στον πιο χαϊδεμένο αδελφό της, τον Ρος. Οργανώνει τη ζωή όλης της παρέας, στον ρόλο της φιλόξενης οικοδέσποινας.","fact":"Στην εφηβεία της, σύμφωνα με τη σειρά, η Μόνικα ήταν πολύ πιο παχουλή, κάτι που επανέρχεται συχνά στα φλας μπακ.","wiki_en":"Monica Geller"},{"name":"Φίμπι Μπουφέ","emoji":"🎸","meta":["«Friends»","εκκεντρική τραγουδίστρια και μασέζ","1994"],"description":"Εκκεντρική μασέζ και τραγουδίστρια του δρόμου, με δύσκολο παρελθόν και παράλογα αστεία τραγούδια δικής της σύνθεσης. Είναι το ελεύθερο πνεύμα της παρέας, ζει με τους δικούς της κανόνες και πιστεύει στα μεταφυσικά, ό,τι κι αν λένε οι φίλοι της.","fact":"Το τραγούδι της Φίμπι «Smelly Cat» το ερμήνευε ζωντανά στη σειρά η ίδια η ηθοποιός Λίζα Κούντροου.","wiki_en":"Phoebe Buffay"},{"name":"Τόνι Σοπράνο","emoji":"🍝","meta":["«The Sopranos»","αρχηγός της μαφίας","1999"],"description":"Ιταλοαμερικανός αρχηγός μιας οικογένειας της μαφίας στο Νιου Τζέρσεϊ, που συνδυάζει το σκληρό εγκληματικό επάγγελμα με τις έγνοιες ενός κοινού οικογενειάρχη του προαστίου. Πηγαίνει κρυφά σε ψυχοθεραπευτή, προσπαθώντας να αντέξει τις κρίσεις πανικού και το βάρος των αποφάσεών του.","fact":"Η σειρά και ο ίδιος ο Τόνι θεωρούνται από τις βασικές εμπνεύσεις για όλο το μετέπειτα κύμα δραμάτων με αμφίσημους πρωταγωνιστές.","wiki_en":"Tony Soprano"},{"name":"Ντουάιτ Σρουτ","emoji":"🥕","meta":["«The Office»","αγρότης και υπεύθυνος πωλήσεων","2005"],"description":"Εκκεντρικός υπεύθυνος πωλήσεων μιας εταιρείας χαρτιού και αγρότης παράλληλα, με εμμονή στους κανόνες, στις πολεμικές τέχνες και στις δικές του αντιλήψεις για την ιεραρχία. Η κυριολεκτική και παράξενη ματιά του στον κόσμο γεννά διαρκώς κωμικές καταστάσεις στο γραφείο.","fact":"Ο Ντουάιτ Σρουτ καλλιεργεί παντζάρια στην οικογενειακή φάρμα, κάτι που είναι έτοιμος να το πει στους συναδέλφους με κάθε ευκαιρία.","wiki_en":"Dwight Schrute"},{"name":"Τζιμ Χάλπερτ","emoji":"📎","meta":["«The Office»","πλακατζής πωλητής του γραφείου","2005"],"description":"Υπεύθυνος πωλήσεων μιας εταιρείας χαρτιού, που περνά τις βαρετές μέρες με φάρσες στο γραφείο, κυρίως σε βάρος του συναδέλφου του Ντουάιτ. Στρέφεται τακτικά κατευθείαν στην κάμερα, με ειρωνικό βλέμμα για το παράλογο που συμβαίνει γύρω του.","fact":"Μία από τις αγαπημένες φάρσες του Τζιμ είναι να κλείνει τα γραφικά είδη του Ντουάιτ μέσα σε ζελέ, πάνω στο ίδιο του το γραφείο.","wiki_en":"Jim Halpert"},{"name":"Χόντορ","emoji":"🚪","meta":["«Game of Thrones»","ο γιγαντόσωμος υπηρέτης των Σταρκ","1996"],"description":"Ο καλόκαρδος και απίστευτα δυνατός υπηρέτης του οίκου Σταρκ, που μπορεί να λέει μόνο το ίδιο του το όνομα αντί για οποιαδήποτε άλλη λέξη. Πίσω από τη φαινομενική απλότητα κρύβεται βαθιά αφοσίωση στην οικογένεια που υπηρετεί πιστά.","fact":"Ο πραγματικός λόγος για τον οποίο μπορεί να λέει μόνο μία λέξη αποκαλύπτεται πολλά χρόνια μετά την πρώτη του εμφάνιση.","wiki_en":"Hodor","wiki_ru":"Ходоров"},{"name":"Σέρσεϊ Λάνιστερ","emoji":"👑","meta":["«Game of Thrones»","η βασίλισσα των ιντριγκών","1996"],"description":"Φιλόδοξη βασίλισσα από τον πανίσχυρο οίκο των Λάνιστερ, έτοιμη για κάθε ίντριγκα και κάθε θυσία για την εξουσία και για την προστασία των παιδιών της. Το μυαλό και η ψυχραιμία της δεν υστερούν, και κάποτε ξεπερνούν, εκείνα των αντρών της αυλής.","fact":"Την περίφημη φράση «Όταν παίζεις το παιχνίδι των θρόνων, ή κερδίζεις ή πεθαίνεις» τη λέει η Σέρσεϊ Λάνιστερ.","wiki_en":"Cersei Lannister"},{"name":"Τζέιμι Λάνιστερ","emoji":"✋","meta":["«Game of Thrones»","ιππότης της βασιλικής φρουράς","1996"],"description":"Λαμπρός ξιφομάχος και ιππότης της βασιλικής φρουράς, που η φήμη του σκιάζεται για χρόνια από μια αμφιλεγόμενη πράξη του παρελθόντος. Στην πορεία της ιστορίας κάνει έναν μακρύ δρόμο επανεξέτασης της τιμής και της θέσης του στον κόσμο.","fact":"Το παρατσούκλι «Βασιλοκτόνος» τον ακολουθεί χρόνια, αν και οι αληθινοί λόγοι της πράξης του μένουν για καιρό άγνωστοι στους γύρω του.","wiki_en":"Jaime Lannister"},{"name":"Άρια Σταρκ","emoji":"🐺","meta":["«Game of Thrones»","νεαρή πολεμίστρια του οίκου Σταρκ","1996"],"description":"Η ανυπότακτη μικρότερη κόρη του οίκου Σταρκ, που από παιδί προτιμά την ξιφασκία από τις συνηθισμένες ασχολίες των αρχοντοπούλων. Μετά από τραγικές απώλειες περνά σκληρό σχολείο επιβίωσης και πολεμικής τέχνης.","fact":"Η εκπαίδευση της Άρια στο σπαθί ξεκινά με μια μικροσκοπική λεπίδα που τη λένε Βελόνα, δώρο του ετεροθαλή αδελφού της, του Τζον Σνόου.","wiki_en":"Arya Stark"},{"name":"Έντνταρντ Σταρκ","emoji":"🏰","meta":["«Game of Thrones»","άρχοντας του Γουίντερφελ","1996"],"description":"Ο αυστηρός και έντιμος άρχοντας του βόρειου κάστρου Γουίντερφελ, που βάζει το καθήκον και την τιμή πάνω από το συμφέρον και την ασφάλειά του. Η ακλόνητη ευθύτητά του έρχεται σε έντονη αντίθεση με τη δολιότητα της βασιλικής αυλής, όπου βρίσκεται μπλεγμένος.","fact":"Το ρητό του οίκου Σταρκ, «Ο χειμώνας έρχεται», δένεται πάνω απ' όλα με τον Έντνταρντ Σταρκ και τη διαρκή ετοιμότητά του για το χειρότερο.","wiki_en":"Eddard Stark"},{"name":"The Dude","emoji":"🎳","meta":["«The Big Lebowski»","γαλήνιος λάτρης του μπόουλινγκ","1998"],"description":"Άνεργος λάτρης του μπόουλινγκ και των κοκτέιλ White Russian, που τον φωνάζουν Dude και που τον ήρεμο ρυθμό της ζωής του διαταράσσει μια παράλογη παρεξήγηση με έναν συνονόματο εκατομμυριούχο. Αντιδρά στα πιο παράλογα γεγονότα με φιλοσοφική ηρεμία και ελάχιστο κόπο.","fact":"Ο ήρωας ενέπνευσε ένα ολόκληρο ανεπίσημο κίνημα οπαδών, τον «ντουντεϊσμό», που παρωδεί με τον τρόπο του τα θρησκευτικά κινήματα.","wiki_en":"The Dude","wiki_ru":"Большой Лебовски"},{"name":"Κροκόδειλος Ντάντι","emoji":"🐊","meta":["«Κροκόδειλος Ντάντι»","Αυστραλός ιχνηλάτης","1986"],"description":"Παλιός κυνηγός και ιχνηλάτης από την αυστραλιανή ενδοχώρα, συνηθισμένος στις συναντήσεις με κροκόδειλους και σε κάθε σκληρή δοκιμασία του μπους. Βρίσκοντας τον εαυτό του στη θορυβώδη Νέα Υόρκη, εφαρμόζει ατάραχος τις ικανότητες επιβίωσής του στις σκοτούρες της πόλης.","fact":"Το παρατσούκλι «Κροκόδειλος» το πήρε αφού επέζησε από πάλη με έναν κροκόδειλο· το Ντάντι είναι το αληθινό του επώνυμο.","wiki_en":"Crocodile Dundee"},{"name":"Μέρι Πόπινς","emoji":"☂️","meta":["«Μέρι Πόπινς»","μαγική νταντά","1934"],"description":"Αυστηρή στην όψη αλλά απίστευτα καλόκαρδη μαγική νταντά, που φτάνει πετώντας με μια ομπρέλα για να βάλει τάξη στην οικογένεια Μπανκς στο Λονδίνο. Μετατρέπει τις βαρετές υποχρεώσεις σε περιπέτειες με μικρά θαύματα και ακλόνητο αίσθημα τακτ.","fact":"Η ταινία της Disney του 1964 χάρισε στην Τζούλι Άντριους Όσκαρ, αν και η ίδια η Πάμελα Τράβερς έμεινε δυσαρεστημένη από τη μεταφορά.","wiki_en":"Mary Poppins (character)"},{"name":"Νέβιλ Λονγκμπότομ","emoji":"🌿","meta":["«Χάρι Πότερ»","αδέξιος μαθητής του Γκρίφιντορ","1997"],"description":"Στην αρχή ένας αδέξιος και δειλός μαθητής του Γκρίφιντορ, που χάνει διαρκώς τα πράγματά του και μπερδεύει τα απλούστερα ξόρκια. Μέσα στην ιστορία ανακαλύπτει το δικό του ταλέντο στη βοτανολογία και μια αντοχή χαρακτήρα που κανείς δεν περίμενε.","fact":"Ο Νέβιλ Λονγκμπότομ είναι αυτός που βγάζει από το Καπέλο της Επιλογής το θρυλικό σπαθί του Γκρίφιντορ, σε μια από τις πιο κρίσιμες στιγμές.","wiki_en":"Neville Longbottom"},{"name":"Ντράκο Μαλφόι","emoji":"🐍","meta":["«Χάρι Πότερ»","αλαζόνας μαθητής του Σλίθεριν","1997"],"description":"Αλαζόνας μαθητής του Σλίθεριν από οικογένεια καθαρόαιμων μάγων, αντίπαλος του Χάρι Πότερ από την πρώτη κιόλας μέρα στο Χόγκουαρτς. Καλύπτει με σνομπισμό και υπεροψία τη δική του ανασφάλεια και την πίεση που του ασκεί η οικογένειά του.","fact":"Μέσα στα εφτά βιβλία, η σχέση του Ντράκο Μαλφόι με τον Χάρι Πότερ γίνεται πολύ πιο σύνθετη από μια απλή σχολική κόντρα.","wiki_en":"Draco Malfoy"}];
